export const IntegrationGuide: React.FC = () => {
  const [copied, setCopied] = useState<string | null>(null);

  const handleCopy = (text: string, id: string) => {
    navigator.clipboard.writeText(text);
    setCopied(id);
    setTimeout(() => setCopied(null), 2000);
  };

  const gasCode = `// --- COPY TOÀN BỘ CODE NÀY VÀO APPS SCRIPT ---

// Cấu hình tên Sheet
var SHEET_NAME = "Users";

// 1. Hàm GET: Dùng cho Trang Web Quản Lý lấy dữ liệu về hiển thị
function doGet(e) {
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_NAME);
  if (!sheet) return ContentService.createTextOutput(JSON.stringify([])).setMimeType(ContentService.MimeType.JSON);

  var data = sheet.getDataRange().getValues();
  var headers = data[0]; // Dòng đầu là tiêu đề
  var users = [];

  // Bắt đầu từ dòng thứ 2 (index 1)
  for (var i = 1; i < data.length; i++) {
    var row = data[i];
    var user = {};
    // Map dữ liệu theo cột (Giả sử thứ tự: MachineID, Name, Company, Status, Expiration, LastLogin)
    user.id = row[0];            // Cột A: MachineID (Làm ID luôn)
    user.name = row[1];          // Cột B: Tên người dùng
    user.company = row[2];       // Cột C: Công ty
    user.status = row[3];        // Cột D: Status (Active/Blocked)
    user.expirationDate = row[4];// Cột E: Ngày hết hạn
    user.lastLogin = row[5];     // Cột F: Lần cuối đăng nhập
    user.licenseType = "subscription"; // Mặc định hoặc thêm cột G nếu muốn
    user.email = row[1] + "@domain.com"; // Fake email nếu không có cột email

    users.push(user);
  }

  return ContentService.createTextOutput(JSON.stringify(users))
    .setMimeType(ContentService.MimeType.JSON);
}

// 2. Hàm POST: Dùng cho Revit Tool gửi yêu cầu kiểm tra License
function doPost(e) {
  try {
    var data = JSON.parse(e.postData.contents);
    var sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_NAME);

    // Tự tạo Sheet nếu chưa có
    if (!sheet) {
      sheet = SpreadsheetApp.getActiveSpreadsheet().insertSheet(SHEET_NAME);
      sheet.appendRow(["MachineID", "Name", "Company", "Status", "Expiration", "LastLogin"]);
    }

    var rows = sheet.getDataRange().getValues();
    var isValid = false;
    var message = "Machine ID not found";
    var foundRowIndex = -1;

    // Tìm MachineID trong cột A (index 0)
    for (var i = 1; i < rows.length; i++) {
      if (rows[i][0] == data.machineId) {
        foundRowIndex = i + 1;
        if (rows[i][3] == "Active") { // Cột D là Status
           // Kiểm tra ngày hết hạn (Cột E)
           var expDate = new Date(rows[i][4]);
           var today = new Date();
           if (expDate >= today) {
             isValid = true;
             message = "Success";
           } else {
             message = "License Expired";
           }
        } else {
          message = "License Blocked";
        }
        break;
      }
    }

    // Nếu tìm thấy -> Cập nhật LastLogin (Cột F - Index 6 trong Excel, 5 trong mảng)
    if (foundRowIndex > -1) {
       sheet.getRange(foundRowIndex, 6).setValue(new Date().toLocaleString());
    }

    // Nếu không tìm thấy -> Tự động thêm mới vào dòng cuối (Optional - Chế độ Auto Register)
    // if (foundRowIndex == -1) {
    //    sheet.appendRow([data.machineId, data.user, "Unknown", "Blocked", new Date(), new Date()]);
    //    message = "New machine registered (Blocked by default)";
    // }

    return ContentService.createTextOutput(JSON.stringify({ 
      "isValid": isValid, 
      "message": message 
    })).setMimeType(ContentService.MimeType.JSON);

  } catch(err) {
    return ContentService.createTextOutput(JSON.stringify({ "error": err.toString() }));
  }
}
// --- HẾT COPY ---`;

  return (
    <div className="space-y-8 pb-12 max-w-4xl mx-auto">

      {/* Banner */}
      <div className="bg-gradient-to-r from-emerald-600 to-teal-600 rounded-2xl p-8 text-white shadow-xl">
        <div className="flex items-center gap-4 mb-4">
            <Globe className="w-10 h-10 text-white" />
