import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { UserManagement } from './components/UserManagement';
import { SessionMonitor } from './components/SessionMonitor';
import { AiAssistant } from './components/AiAssistant';
import { IntegrationGuide } from './components/IntegrationGuide';
import { AppView, User, Session } from './types';
import { MOCK_USERS, MOCK_SESSIONS } from './constants';
import { Database, Link2, Loader2, RotateCw, Menu } from 'lucide-react';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>(AppView.DASHBOARD);

  // Data State
  const [users, setUsers] = useState<User[]>(MOCK_USERS);
  const [sessions, setSessions] = useState<Session[]>(MOCK_SESSIONS);
  const [isUsingRealData, setIsUsingRealData] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  // Connection State
  const [sheetUrl, setSheetUrl] = useState('');
  const [isConnectModalOpen, setIsConnectModalOpen] = useState(false);

  // Mobile State
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Load saved URL on startup
  useEffect(() => {
    const savedUrl = localStorage.getItem('sheet_api_url');
    if (savedUrl) {
      setSheetUrl(savedUrl);
      fetchRealData(savedUrl);
    }
  }, []);

  // Ensure API Key exists (warning only)
  useEffect(() => {
    if (!process.env.API_KEY) {
      console.warn("Missing API_KEY environment variable.");
    }
  }, []);

  const fetchRealData = async (url: string) => {
    if (!url) return;
    setIsLoading(true);
    try {
      // Add a timestamp to prevent caching
      const response = await fetch(`${url}?t=${Date.now()}`);
      if (!response.ok) throw new Error("Network response was not ok");

      const data = await response.json();

      if (Array.isArray(data) && data.length > 0) {
        setUsers(data);
        setIsUsingRealData(true);
        // Clear sessions when using real data (as simple sheet doesn't track active sessions efficiently yet)
        setSessions([]); 
      } else {
        alert("Kết nối thành công nhưng không có dữ liệu hoặc định dạng sai.");
      }
    } catch (error) {
      console.error("Failed to fetch data", error);
      alert("Không thể kết nối tới Google Sheet. Vui lòng kiểm tra lại URL.");
      setIsUsingRealData(false);
    } finally {
      setIsLoading(false);
    }
  };

  const handleConnect = (e: React.FormEvent) => {
    e.preventDefault();
    if (sheetUrl) {
      localStorage.setItem('sheet_api_url', sheetUrl);
      fetchRealData(sheetUrl);
      setIsConnectModalOpen(false);
    }
  };

  const handleDisconnect = () => {
    localStorage.removeItem('sheet_api_url');
    setSheetUrl('');
    setIsUsingRealData(false);
    setUsers(MOCK_USERS);
    setSessions(MOCK_SESSIONS);
  };

  const handleUpdateStatus = (id: string, newStatus: User['status']) => {
    // In real app, this should also POST to API
    setUsers(prev => prev.map(u => u.id === id ? { ...u, status: newStatus } : u));
    if (isUsingRealData) {
        alert("Lưu ý: Bạn đang xem dữ liệu thật. Việc sửa trạng thái ở đây chỉ là tạm thời trên giao diện. Hãy sửa trong Google Sheet để có hiệu lực vĩnh viễn.");
    }
  };

  const handleAddUser = (user: User) => {
    setUsers(prev => [...prev, user]);
    if (isUsingRealData) {
         alert("Lưu ý: Hãy thêm người dùng mới trực tiếp vào Google Sheet.");
    }
  };

  const handleDeleteUser = (id: string) => {
    setUsers(prev => prev.filter(u => u.id !== id));
     if (isUsingRealData) {
         alert("Lưu ý: Hãy xóa người dùng trực tiếp trong Google Sheet.");
    }
  };

  const handleKillSession = (sessionId: string) => {
    if (window.confirm("Bạn có chắc chắn muốn buộc dừng phiên làm việc này?")) {
      setSessions(prev => prev.filter(s => s.id !== sessionId));
    }
  };

  const renderContent = () => {
    if (isLoading && users.length === 0) {
        return (
            <div className="flex h-full items-center justify-center flex-col gap-4 text-slate-500">
                <Loader2 className="w-10 h-10 animate-spin text-blue-600" />
                <p>Đang tải dữ liệu từ Google Sheet...</p>
            </div>
        )
    }

    switch (currentView) {
      case AppView.DASHBOARD:
        return <Dashboard users={users} sessions={sessions} />;
      case AppView.USERS:
        return <UserManagement 
          users={users} 
          onAddUser={handleAddUser} 
          onUpdateStatus={handleUpdateStatus} 
          onDeleteUser={handleDeleteUser}
        />;
      case AppView.SESSIONS:
        return <SessionMonitor sessions={sessions} onKillSession={handleKillSession} />;
      case AppView.AI_INSIGHTS:
        return <AiAssistant users={users} sessions={sessions} />;
      case AppView.INTEGRATION:
        return <IntegrationGuide />;
      default:
        return <Dashboard users={users} sessions={sessions} />;
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 font-sans overflow-hidden">
      {/* Sidebar - Mobile Responsive */}
      <Sidebar 
        currentView={currentView} 
        setCurrentView={setCurrentView} 
        isMobileOpen={isMobileMenuOpen}
        onCloseMobile={() => setIsMobileMenuOpen(false)}
      />

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col h-full w-full relative overflow-hidden">

        {/* Header */}
        <header className="flex-none px-4 py-4 md:px-8 border-b border-slate-200 bg-white shadow-sm flex justify-between items-center z-20">
          <div className="flex items-center gap-3">
             {/* Mobile Menu Button */}
             <button 
                onClick={() => setIsMobileMenuOpen(true)}
                className="md:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-lg"
             >
                <Menu className="w-6 h-6" />
             </button>

             <div>
                <h1 className="text-lg md:text-2xl font-bold text-slate-800 truncate max-w-[150px] md:max-w-none">
                  {currentView === AppView.DASHBOARD && 'Bảng điều khiển'}
                  {currentView === AppView.USERS && 'Người dùng'}
                  {currentView === AppView.SESSIONS && 'Phiên làm việc'}
                  {currentView === AppView.AI_INSIGHTS && 'Trợ lý AI'}
                  {currentView === AppView.INTEGRATION && 'Tích hợp API'}
                </h1>
                <div className="flex items-center gap-2 text-xs md:text-sm mt-0.5">
                    {isUsingRealData ? (
                        <span className="flex items-center gap-1 text-green-600 font-medium">
                            <Database className="w-3 h-3" /> <span className="hidden sm:inline">Connected</span>
                        </span>
                    ) : (
                        <span className="flex items-center gap-1 text-slate-500 italic">
                            <Database className="w-3 h-3" /> <span className="hidden sm:inline">Demo Data</span>
                        </span>
                    )}
                </div>
             </div>
          </div>

          <div className="flex items-center gap-2 md:gap-4">
            {isUsingRealData ? (
                <div className="flex gap-1 md:gap-2">
                    <button 
                        onClick={() => fetchRealData(sheetUrl)}
                        className="p-2 text-slate-500 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                        title="Làm mới"
                    >
                        <RotateCw className={`w-5 h-5 ${isLoading ? 'animate-spin' : ''}`} />
                    </button>
                    <button 
                        onClick={handleDisconnect}
                        className="text-xs bg-slate-200 hover:bg-slate-300 text-slate-700 px-2 py-1 md:px-3 md:py-2 rounded-lg font-medium transition-colors whitespace-nowrap"
                    >
                        Ngắt
                    </button>
                </div>
            ) : (
                <button 
                    onClick={() => setIsConnectModalOpen(true)}
                    className="flex items-center gap-2 bg-green-600 hover:bg-green-700 text-white px-3 py-2 rounded-lg text-sm font-medium transition-colors shadow-sm shadow-green-200 whitespace-nowrap"
                >
                    <Link2 className="w-4 h-4" />
                    <span className="hidden sm:inline">Kết nối Data</span>
                    <span className="sm:hidden">Kết nối</span>
                </button>
            )}

            <div className="h-8 w-px bg-slate-300 mx-1 md:mx-2 hidden sm:block"></div>

            <div className="flex items-center gap-3">
                <div className="text-right hidden sm:block">
                    <div className="text-sm font-bold text-slate-700">Admin</div>
                </div>
                <div className="w-8 h-8 md:w-10 md:h-10 rounded-full bg-slate-200 flex items-center justify-center text-slate-500 border-2 border-white shadow-sm font-bold text-xs md:text-base">
                    S
                </div>
            </div>
          </div>
        </header>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 bg-slate-50 scroll-smooth">
            <div className="max-w-7xl mx-auto">
                {renderContent()}
            </div>
        </div>

        {/* Modal Connect Data */}
        {isConnectModalOpen && (
            <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in">
                <div className="bg-white rounded-xl shadow-xl max-w-lg w-full p-6 animate-in zoom-in-95">
                    <h3 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2">
                        <Database className="w-5 h-5 text-blue-600" />
                        Kết nối Google Sheet
                    </h3>
                    <p className="text-sm text-slate-600 mb-4">
                        Nhập URL Web App từ Google Apps Script để tải dữ liệu thật. 
                        <br/>(Xem hướng dẫn ở menu "Tích hợp API").
                    </p>
                    <form onSubmit={handleConnect}>
                        <input 
                            type="url" 
                            required
                            placeholder="https://script.google.com/macros/s/..."
                            className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none mb-4"
                            value={sheetUrl}
                            onChange={(e) => setSheetUrl(e.target.value)}
                        />
                        <div className="flex justify-end gap-3">
                            <button 
                                type="button"
                                onClick={() => setIsConnectModalOpen(false)}
                                className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg font-medium"
                            >
                                Hủy
                            </button>
                            <button 
                                type="submit"
                                className="px-4 py-2 bg-blue-600 text-white hover:bg-blue-700 rounded-lg font-medium"
                            >
                                Kết nối ngay
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        )}

      </main>
    </div>
  );
};

export default App;

