import React from 'react';
import { User, Session } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Users, Wifi, AlertTriangle, ShieldCheck, Clock, Activity, CheckCircle2, XCircle } from 'lucide-react';

interface DashboardProps {
  users: User[];
  sessions: Session[];
}

export const Dashboard: React.FC<DashboardProps> = ({ users, sessions }) => {
  // Calculate Stats
  const activeUsers = users.filter(u => u.status === 'active').length;
  const expiredUsers = users.filter(u => u.status === 'expired').length;
  const totalSessions = sessions.length;

  // Calculate Expiring Users (Next 30 Days)
  const expiringUsers = users.filter(user => {
    // Skip if already expired or blocked
    if (user.status === 'expired' || user.status === 'blocked') return false;

    const expDate = new Date(user.expirationDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0); // Start of today

    const diffTime = expDate.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    // Check if expiring within 0 to 30 days
    return diffDays >= 0 && diffDays <= 30;
  }).sort((a, b) => new Date(a.expirationDate).getTime() - new Date(b.expirationDate).getTime());

  // Data for Charts
  const revitVersionData = sessions.reduce((acc: any[], session) => {
    const existing = acc.find(item => item.name === session.revitVersion);
    if (existing) {
      existing.value += 1;
    } else {
      acc.push({ name: session.revitVersion, value: 1 });
    }
    return acc;
  }, []);

  const licenseTypeData = users.reduce((acc: any[], user) => {
    const existing = acc.find(item => item.name === user.licenseType);
    if (existing) {
      existing.value += 1;
    } else {
      acc.push({ name: user.licenseType, value: 1 });
    }
    return acc;
  }, []);

  const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444'];

  const StatCard = ({ title, value, icon: Icon, color, bg }: any) => (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-start justify-between hover:shadow-md transition-shadow">
      <div>
        <p className="text-sm font-medium text-slate-500 mb-1">{title}</p>
        <h3 className="text-2xl font-bold text-slate-800">{value}</h3>
      </div>
      <div className={`p-3 rounded-lg ${bg}`}>
        <Icon className={`w-6 h-6 ${color}`} />
      </div>
    </div>
  );

  return (
    <div className="space-y-6 animate-fade-in">
      <h2 className="text-2xl font-bold text-slate-800">Tổng quan hệ thống</h2>

      {/* Expiring Licenses Warning Section */}
      {expiringUsers.length > 0 && (
        <div className="bg-orange-50 border border-orange-200 rounded-xl p-5 shadow-sm animate-in slide-in-from-top-2">
          <div className="flex items-start gap-4">
            <div className="p-2 bg-orange-100 rounded-lg text-orange-600 mt-1">
              <Clock className="w-5 h-5" />
            </div>
            <div className="flex-1">
              <h3 className="text-lg font-bold text-slate-800 mb-1">Cảnh báo: Có {expiringUsers.length} License sắp hết hạn</h3>
              <p className="text-sm text-slate-600 mb-4">
                Các tài khoản dưới đây cần được gia hạn trong vòng 30 ngày tới để đảm bảo dịch vụ không bị gián đoạn.
              </p>

              <div className="overflow-x-auto bg-white rounded-lg border border-orange-100 shadow-sm">
                <table className="w-full text-sm text-left">
                  <thead className="bg-orange-50 text-orange-900 font-semibold border-b border-orange-100">
                    <tr>
                      <th className="px-4 py-3">Người dùng</th>
                      <th className="px-4 py-3">Công ty</th>
                      <th className="px-4 py-3">Loại License</th>
                      <th className="px-4 py-3">Ngày hết hạn</th>
                      <th className="px-4 py-3 text-right">Thời gian còn lại</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-orange-50">
                    {expiringUsers.map(user => {
                      const daysLeft = Math.ceil((new Date(user.expirationDate).getTime() - new Date().setHours(0,0,0,0)) / (1000 * 60 * 60 * 24));
                      const isUrgent = daysLeft <= 7;
                      return (
                        <tr key={user.id} className="hover:bg-orange-50/50 transition-colors">
                          <td className="px-4 py-3 font-medium text-slate-800">
                            <div className="flex flex-col">
                              <span>{user.name}</span>
                              <span className="text-xs text-slate-400">{user.email}</span>
                            </div>
                          </td>
                          <td className="px-4 py-3 text-slate-600">{user.company}</td>
                          <td className="px-4 py-3 text-slate-600 capitalize">
                             {user.licenseType === 'perpetual' ? 'Vĩnh viễn' : user.licenseType === 'subscription' ? 'Thuê bao' : 'Dùng thử'}
                          </td>
                          <td className="px-4 py-3 text-slate-600">{new Date(user.expirationDate).toLocaleDateString('vi-VN')}</td>
                          <td className="px-4 py-3 text-right">
                            <span className={`font-bold px-2 py-1 rounded text-xs ${isUrgent ? 'bg-red-100 text-red-700' : 'bg-orange-100 text-orange-700'}`}>
                              {daysLeft} ngày
                            </span>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="Tổng người dùng" 
          value={users.length} 
          icon={Users} 
          color="text-blue-600" 
          bg="bg-blue-50" 
        />
        <StatCard 
          title="Đang trực tuyến" 
          value={totalSessions} 
          icon={Wifi} 
          color="text-green-600" 
          bg="bg-green-50" 
        />
        <StatCard 
          title="License Hết hạn" 
          value={expiredUsers} 
          icon={AlertTriangle} 
          color="text-amber-600" 
          bg="bg-amber-50" 
        />
        <StatCard 
          title="Hoạt động" 
          value={activeUsers} 
          icon={ShieldCheck} 
          color="text-purple-600" 
          bg="bg-purple-50" 
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Recent Activity Feed */}
        <div className="lg:col-span-1 bg-white p-6 rounded-xl shadow-sm border border-slate-100 h-96 flex flex-col">
            <h3 className="text-lg font-semibold text-slate-800 mb-4 flex items-center gap-2">
                <Activity className="w-5 h-5 text-blue-500" />
                Yêu cầu đăng nhập gần đây
            </h3>
            <div className="flex-1 overflow-y-auto pr-2 space-y-4">
                {[...Array(5)].map((_, i) => (
                    <div key={i} className="flex items-start gap-3 p-3 rounded-lg bg-slate-50 border border-slate-100">
                        <div className={`w-2 h-2 mt-2 rounded-full ${i === 0 ? 'bg-green-500' : 'bg-slate-400'}`}></div>
                        <div className="flex-1">
                            <p className="text-sm font-medium text-slate-800">
                                {['Nguyen Van A', 'Tran Thi B', 'Le Van C', 'Hoang D', 'Pham E'][i]}
                            </p>
                            <p className="text-xs text-slate-500">
                                {['Revit 2024', 'Revit 2023', 'Revit 2025', 'Revit 2022', 'Revit 2024'][i]} • IP: 192.168.1.{10+i}
                            </p>
                            <p className="text-[10px] text-slate-400 mt-1">{i === 0 ? 'Vừa xong' : `${i * 15} phút trước`}</p>
                        </div>
                        <div className="flex flex-col gap-1">
                             <button className="text-green-600 hover:bg-green-50 p-1 rounded" title="Allow">
                                 <CheckCircle2 className="w-4 h-4" />
                             </button>
                             <button className="text-red-500 hover:bg-red-50 p-1 rounded" title="Block">
                                 <XCircle className="w-4 h-4" />
                             </button>
                        </div>
                    </div>
                ))}
            </div>
        </div>

        {/* Charts Container */}
        <div className="lg:col-span-2 grid grid-cols-1 sm:grid-cols-2 gap-6 h-96">
             {/* Revit Version Distribution */}
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex flex-col">
            <h3 className="text-lg font-semibold text-slate-800 mb-4">Phiên bản Revit</h3>
            <div className="flex-1">
                <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={revitVersionData}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} />
                    <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 12}} />
                    <YAxis axisLine={false} tickLine={false} />
                    <Tooltip 
                        contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                        cursor={{ fill: '#f1f5f9' }}
                    />
                    <Bar dataKey="value" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={30} />
                    </BarChart>
                </ResponsiveContainer>
            </div>
            </div>

            {/* License Types */}
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex flex-col">
            <h3 className="text-lg font-semibold text-slate-800 mb-4">Loại License</h3>
