function doPost(e) {
  try {
    var data = JSON.parse(e.postData.contents);
    var sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_NAME);

    // Tự tạo Sheet nếu chưa có
    if (!sheet) {
      sheet = SpreadsheetApp.getActiveSpreadsheet().insertSheet(SHEET_NAME);
      sheet.appendRow(["MachineID", "Name", "Company", "Status", "Expiration", "LastLogin"]);
    }

    var rows = sheet.getDataRange().getValues();
    var isValid = false;
    var message = "Machine ID not found";
    var foundRowIndex = -1;

    // Tìm MachineID trong cột A (index 0)
    for (var i = 1; i < rows.length; i++) {
      if (rows[i][0] == data.machineId) {
        foundRowIndex = i + 1;
        if (rows[i][3] == "Active") { // Cột D là Status
           // Kiểm tra ngày hết hạn (Cột E)
           var expDate = new Date(rows[i][4]);
           var today = new Date();
           if (expDate >= today) {
             isValid = true;
             message = "Success";
           } else {
             message = "License Expired";
           }
        } else {
          message = "License Blocked";
        }
        break;
      }
    }

    // Nếu tìm thấy -> Cập nhật LastLogin (Cột F - Index 6 trong Excel, 5 trong mảng)
    if (foundRowIndex > -1) {
       sheet.getRange(foundRowIndex, 6).setValue(new Date().toLocaleString());
    }

    return ContentService.createTextOutput(JSON.stringify({ 
      "isValid": isValid, 
      "message": message 
    })).setMimeType(ContentService.MimeType.JSON);

  } catch(err) {
    return ContentService.createTextOutput(JSON.stringify({ "error": err.toString() }));
  }
}
