import { GoogleGenAI } from "@google/genai";
import { User, Session } from '../types';

declare const process: { env: any };

const getClient = () => {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const generateLicenseReport = async (users: User[], sessions: Session[], query: string): Promise<string> => {
    try {
        const client = getClient();

        const systemInstruction = `
            Bạn là một trợ lý quản trị viên cho hệ thống quản lý License (giấy phép) phần mềm Revit Add-in.
            Bạn sẽ nhận được dữ liệu JSON về người dùng và các phiên đăng nhập hiện tại.

            Nhiệm vụ của bạn là:
            1. Phân tích dữ liệu để trả lời câu hỏi của người dùng.
            2. Đưa ra các nhận xét về xu hướng sử dụng (ví dụ: phiên bản Revit nào phổ biến, công ty nào dùng nhiều nhất).
            3. Cảnh báo về các license sắp hết hạn hoặc người dùng bị chặn.

            Hãy trả lời bằng Tiếng Việt, định dạng Markdown, ngắn gọn và chuyên nghiệp.
        `;

        const dataContext = JSON.stringify({
            totalUsers: users.length,
            activeSessions: sessions.length,
            usersData: users,
            sessionsData: sessions
        });

        const prompt = `
            Dữ liệu hệ thống hiện tại:
            ${dataContext}

            Câu hỏi của quản trị viên: "${query}"
        `;

        const response = await client.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
                systemInstruction: systemInstruction,
            }
        });

        return response.text || "Xin lỗi, tôi không thể tạo báo cáo lúc này.";

    } catch (error) {
        console.error("Gemini API Error:", error);
        return "Đã xảy ra lỗi khi kết nối với AI. Vui lòng kiểm tra API Key.";
    }
};

