    setUsers(prev => prev.map(u => u.id === id ? { ...u, status: newStatus } : u));
  };

  const handleAddUser = (user: User) => {
    setUsers(prev => [...prev, user]);
  };

  const handleDeleteUser = (id: string) => {
    setUsers(prev => prev.filter(u => u.id !== id));
    // Also remove any sessions for this user
    setSessions(prev => prev.filter(s => s.userId !== id));
  };

  const handleKillSession = (sessionId: string) => {
    if (window.confirm("Bạn có chắc chắn muốn buộc dừng phiên làm việc này?")) {
      setSessions(prev => prev.filter(s => s.id !== sessionId));
    }
  };

  const handleAddSession = (session: Session) => {
    setSessions(prev => [session, ...prev]);
  };

  const renderContent = () => {
    switch (currentView) {
      case AppView.DASHBOARD:
        return <Dashboard users={users} sessions={sessions} />;
      case AppView.USERS:
        return <UserManagement 
          users={users} 
          onAddUser={handleAddUser} 
          onUpdateStatus={handleUpdateStatus} 
          onDeleteUser={handleDeleteUser}
        />;
      case AppView.SESSIONS:
        return <SessionMonitor 
          sessions={sessions} 
          users={users}
          onKillSession={handleKillSession} 
          onAddSession={handleAddSession}
        />;
      case AppView.AI_INSIGHTS:
        return <AiAssistant users={users} sessions={sessions} />;
      default:
        return <Dashboard users={users} sessions={sessions} />;
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 font-sans overflow-hidden">
      {/* Sidebar - Mobile Responsive */}
      <Sidebar 
        currentView={currentView} 
        setCurrentView={setCurrentView} 
        isMobileOpen={isMobileMenuOpen}
        onCloseMobile={() => setIsMobileMenuOpen(false)}
      />

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col h-full w-full relative overflow-hidden">

        {/* Header */}
        <header className="flex-none px-4 py-4 md:px-8 border-b border-slate-200 bg-white shadow-sm flex justify-between items-center z-20">
          <div className="flex items-center gap-3">
             {/* Mobile Menu Button */}
             <button 
                onClick={() => setIsMobileMenuOpen(true)}
                className="md:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-lg"
             >
                <Menu className="w-6 h-6" />
             </button>

             <div>
                <h1 className="text-lg md:text-2xl font-bold text-slate-800 truncate max-w-[150px] md:max-w-none">
                  {currentView === AppView.DASHBOARD && 'Bảng điều khiển'}
                  {currentView === AppView.USERS && 'Người dùng'}
                  {currentView === AppView.SESSIONS && 'Phiên làm việc'}
                  {currentView === AppView.AI_INSIGHTS && 'Trợ lý AI'}
                </h1>
                <div className="flex items-center gap-2 text-xs md:text-sm mt-0.5 text-slate-500">
                    Hệ thống quản lý License trực tuyến
                </div>
             </div>
          </div>

          <div className="flex items-center gap-2 md:gap-4">
            <button 
                onClick={handleResetData}
                className="text-slate-400 hover:text-red-600 hover:bg-red-50 px-3 py-2 rounded-lg transition-colors text-sm flex items-center gap-2"
                title="Khôi phục dữ liệu gốc"
            >
                <Trash2 className="w-4 h-4" />
                <span className="hidden sm:inline">Reset Dữ liệu</span>
            </button>

            <div className="h-8 w-px bg-slate-300 mx-1 md:mx-2 hidden sm:block"></div>

            <div className="flex items-center gap-3">
                <div className="text-right hidden sm:block">
                    <div className="text-sm font-bold text-slate-700">Administrator</div>
                    <div className="text-xs text-slate-500">Super User</div>
                </div>
                <div className="w-8 h-8 md:w-10 md:h-10 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 border-2 border-white shadow-sm font-bold text-xs md:text-base">
                    AD
                </div>
            </div>
          </div>
        </header>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 bg-slate-50 scroll-smooth">
            <div className="max-w-7xl mx-auto">
                {renderContent()}
            </div>
        </div>

      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { UserManagement } from './components/UserManagement';
import { SessionMonitor } from './components/SessionMonitor';
import { AiAssistant } from './components/AiAssistant';
import { AppView, User, Session } from './types';
import { MOCK_USERS, MOCK_SESSIONS } from './constants';
import { Menu, Trash2 } from 'lucide-react';

declare const process: { env: any };

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>(AppView.DASHBOARD);

  // Data State - Initialize from LocalStorage if available
  const [users, setUsers] = useState<User[]>(() => {
    try {
      const savedUsers = localStorage.getItem('app_users_data');
      return savedUsers ? JSON.parse(savedUsers) : MOCK_USERS;
    } catch (e) {
      return MOCK_USERS;
    }
  });

  const [sessions, setSessions] = useState<Session[]>(() => {
    try {
      const savedSessions = localStorage.getItem('app_sessions_data');
      return savedSessions ? JSON.parse(savedSessions) : MOCK_SESSIONS;
    } catch (e) {
      return MOCK_SESSIONS;
    }
  });

  // Mobile State
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Persistence Effects: Save to LocalStorage whenever data changes
  useEffect(() => {
    localStorage.setItem('app_users_data', JSON.stringify(users));
  }, [users]);

  useEffect(() => {
    localStorage.setItem('app_sessions_data', JSON.stringify(sessions));
  }, [sessions]);

  // Ensure API Key exists (warning only)
  useEffect(() => {
    if (typeof process !== 'undefined' && process.env && !process.env.API_KEY) {
      console.warn("Missing API_KEY environment variable.");
    }
  }, []);

  const handleResetData = () => {
    if (window.confirm("Bạn có chắc muốn xóa toàn bộ dữ liệu hiện tại và quay về mặc định?")) {
        localStorage.removeItem('app_users_data');
        localStorage.removeItem('app_sessions_data');
        setUsers(MOCK_USERS);
        setSessions(MOCK_SESSIONS);
    }
  };

  const handleUpdateStatus = (id: string, newStatus: User['status']) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, status: newStatus } : u));
  };

  const handleAddUser = (user: User) => {
    setUsers(prev => [...prev, user]);
  };

  const handleEditUser = (updatedUser: User) => {
    setUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
  };

  const handleDeleteUser = (id: string) => {
    setUsers(prev => prev.filter(u => u.id !== id));
    // Also remove any sessions for this user
    setSessions(prev => prev.filter(s => s.userId !== id));
  };

  const handleKillSession = (sessionId: string) => {
    if (window.confirm("Bạn có chắc chắn muốn buộc dừng phiên làm việc này?")) {
      setSessions(prev => prev.filter(s => s.id !== sessionId));
    }
  };

  const handleAddSession = (session: Session) => {
    setSessions(prev => [session, ...prev]);
  };

  const renderContent = () => {
    switch (currentView) {
      case AppView.DASHBOARD:
        return <Dashboard users={users} sessions={sessions} />;
      case AppView.USERS:
        return <UserManagement 
          users={users} 
          onAddUser={handleAddUser} 
          onEditUser={handleEditUser}
          onUpdateStatus={handleUpdateStatus} 
          onDeleteUser={handleDeleteUser}
        />;
      case AppView.SESSIONS:
        return <SessionMonitor 
          sessions={sessions} 
          users={users}
          onKillSession={handleKillSession} 
          onAddSession={handleAddSession}
        />;
      case AppView.AI_INSIGHTS:
        return <AiAssistant users={users} sessions={sessions} />;
      default:
        return <Dashboard users={users} sessions={sessions} />;
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 font-sans overflow-hidden">
      {/* Sidebar - Mobile Responsive */}
      <Sidebar 
        currentView={currentView} 
        setCurrentView={setCurrentView} 
        isMobileOpen={isMobileMenuOpen}
        onCloseMobile={() => setIsMobileMenuOpen(false)}
      />

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col h-full w-full relative overflow-hidden">

        {/* Header */}
        <header className="flex-none px-4 py-4 md:px-8 border-b border-slate-200 bg-white shadow-sm flex justify-between items-center z-20">
          <div className="flex items-center gap-3">
             {/* Mobile Menu Button */}
             <button 
                onClick={() => setIsMobileMenuOpen(true)}
                className="md:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-lg"
             >
                <Menu className="w-6 h-6" />
             </button>

             <div>
                <h1 className="text-lg md:text-2xl font-bold text-slate-800 truncate max-w-[150px] md:max-w-none">
                  {currentView === AppView.DASHBOARD && 'Bảng điều khiển'}
                  {currentView === AppView.USERS && 'Người dùng'}
                  {currentView === AppView.SESSIONS && 'Phiên làm việc'}
                  {currentView === AppView.AI_INSIGHTS && 'Trợ lý AI'}
                </h1>
                <div className="flex items-center gap-2 text-xs md:text-sm mt-0.5 text-slate-500">
                    Hệ thống quản lý License trực tuyến
                </div>
             </div>
          </div>

          <div className="flex items-center gap-2 md:gap-4">
            <button 
                onClick={handleResetData}
                className="text-slate-400 hover:text-red-600 hover:bg-red-50 px-3 py-2 rounded-lg transition-colors text-sm flex items-center gap-2"
                title="Khôi phục dữ liệu gốc"
            >
                <Trash2 className="w-4 h-4" />
                <span className="hidden sm:inline">Reset Dữ liệu</span>
            </button>

            <div className="h-8 w-px bg-slate-300 mx-1 md:mx-2 hidden sm:block"></div>

            <div className="flex items-center gap-3">
                <div className="text-right hidden sm:block">
                    <div className="text-sm font-bold text-slate-700">Administrator</div>
                    <div className="text-xs text-slate-500">Super User</div>
                </div>
                <div className="w-8 h-8 md:w-10 md:h-10 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 border-2 border-white shadow-sm font-bold text-xs md:text-base">
                    AD
                </div>
            </div>
          </div>
        </header>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 bg-slate-50 scroll-smooth">
            <div className="max-w-7xl mx-auto">
                {renderContent()}
            </div>
        </div>

      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { User } from '../types';
import { Search, UserPlus, Filter, Trash2, AlertTriangle, X, Pencil } from 'lucide-react';

interface UserManagementProps {
  users: User[];
  onAddUser: (user: User) => void;
  onEditUser: (user: User) => void;
  onUpdateStatus: (id: string, status: User['status']) => void;
  onDeleteUser: (id: string) => void;
}

export const UserManagement: React.FC<UserManagementProps> = ({ users, onUpdateStatus, onDeleteUser, onAddUser, onEditUser }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [userToDelete, setUserToDelete] = useState<User | null>(null);

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [modalMode, setModalMode] = useState<'add' | 'edit'>('add');

  const [formData, setFormData] = useState<Partial<User>>({
    name: '',
    email: '',
    company: '',
    status: 'active',
    licenseType: 'subscription',
    expirationDate: new Date(new Date().setFullYear(new Date().getFullYear() + 1)).toISOString().split('T')[0],
  });

  const filteredUsers = users.filter(user => {
    const matchesSearch = user.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          user.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          user.company.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = statusFilter === 'all' || user.status === statusFilter;
    return matchesSearch && matchesStatus;
  });

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active': return 'bg-green-100 text-green-700';
      case 'expired': return 'bg-amber-100 text-amber-700';
      case 'blocked': return 'bg-red-100 text-red-700';
      case 'on_hold': return 'bg-indigo-100 text-indigo-700';
      default: return 'bg-slate-100 text-slate-700';
    }
  };

  const getStatusLabel = (status: string) => {
    switch (status) {
        case 'active': return 'Active';
        case 'expired': return 'Expired';
        case 'blocked': return 'Blocked';
        case 'on_hold': return 'On Hold';
        default: return status;
    }
  };

  const confirmDelete = () => {
    if (userToDelete) {
      onDeleteUser(userToDelete.id);
      setUserToDelete(null);
    }
  };

  const handleOpenAddModal = () => {
    setModalMode('add');
    setFormData({
        name: '',
        email: '',
        company: '',
        status: 'active',
        licenseType: 'subscription',
        expirationDate: new Date(new Date().setFullYear(new Date().getFullYear() + 1)).toISOString().split('T')[0],
    });
    setIsModalOpen(true);
  };

  const handleOpenEditModal = (user: User) => {
    setModalMode('edit');
    setFormData({ ...user });
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.email || !formData.company || !formData.expirationDate) {
        return;
    }

    if (modalMode === 'add') {
        const userToAdd: User = {
            id: `U${Date.now().toString().slice(-6)}`,
            name: formData.name!,
            email: formData.email!,
            company: formData.company!,
            status: formData.status as any || 'active',
            licenseType: formData.licenseType as any || 'subscription',
            expirationDate: formData.expirationDate!,
            lastLogin: new Date().toISOString(),
        };
        onAddUser(userToAdd);
    } else {
        // Edit mode
        if (formData.id) {
            onEditUser(formData as User);
        }
    }

    setIsModalOpen(false);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <h2 className="text-2xl font-bold text-slate-800">Quản lý người dùng</h2>
        <button 
          onClick={handleOpenAddModal}
          className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 transition-colors"
        >
          <UserPlus className="w-4 h-4" />
          <span>Thêm mới</span>
        </button>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
        {/* Toolbar */}
        <div className="p-4 border-b border-slate-100 flex flex-col sm:flex-row gap-4">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
            <input 
              type="text" 
              placeholder="Tìm kiếm theo tên, email, công ty..." 
              className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="flex items-center gap-2">
            <Filter className="text-slate-400 w-5 h-5" />
            <select 
              className="border border-slate-200 rounded-lg px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white"
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
            >
              <option value="all">Tất cả trạng thái</option>
              <option value="active">Active</option>
              <option value="on_hold">On Hold</option>
              <option value="expired">Expired</option>
              <option value="blocked">Blocked</option>
            </select>
          </div>
        </div>

        {/* Table */}
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="bg-slate-50 border-b border-slate-100">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider">Người dùng</th>
                <th className="px-6 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider">Công ty</th>
                <th className="px-6 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider">Trạng thái</th>
                <th className="px-6 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider">Loại License</th>
                <th className="px-6 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider">Hết hạn</th>
                <th className="px-6 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider">Đăng nhập cuối</th>
                <th className="px-6 py-3 text-right text-xs font-semibold text-slate-500 uppercase tracking-wider">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredUsers.length > 0 ? (
                filteredUsers.map((user) => (
                  <tr key={user.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center">
                        <div className="flex-shrink-0 h-10 w-10 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold">
                          {user.name.charAt(0)}
                        </div>
                        <div className="ml-4">
                          <div className="text-sm font-medium text-slate-900">{user.name}</div>
                          <div className="text-sm text-slate-500">{user.email}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-600">{user.company}</td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span 
                        title={user.email}
                        className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full cursor-help ${getStatusColor(user.status)}`}
                      >
                        {getStatusLabel(user.status)}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-600">
                      {user.licenseType === 'perpetual' ? 'Vĩnh viễn' : user.licenseType === 'subscription' ? 'Thuê bao' : 'Dùng thử'}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-600">{user.expirationDate}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-600">
                      {new Date(user.lastLogin).toLocaleDateString('vi-VN')}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                      <div className="flex items-center justify-end gap-2">
                        <select
                          value={user.status}
                          onChange={(e) => onUpdateStatus(user.id, e.target.value as any)}
                          className="bg-white border border-slate-200 text-slate-700 text-xs rounded-lg py-1.5 px-2 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none cursor-pointer hover:border-blue-400 transition-colors shadow-sm"
                        >
                          <option value="active">Active</option>
                          <option value="on_hold">On Hold</option>
                          <option value="blocked">Blocked</option>
                          <option value="expired">Expired</option>
                        </select>
                        <button 
                          onClick={() => handleOpenEditModal(user)}
                          className="text-slate-400 hover:text-blue-500 hover:bg-blue-50 p-1.5 rounded-lg transition-colors"
                          title="Sửa thông tin"
                        >
                          <Pencil className="w-4 h-4" />
                        </button>
                        <button 
                          onClick={() => setUserToDelete(user)}
                          className="text-slate-400 hover:text-red-500 hover:bg-red-50 p-1.5 rounded-lg transition-colors"
                          title="Xóa người dùng"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={7} className="px-6 py-12 text-center text-slate-400">
                    Không tìm thấy người dùng nào phù hợp.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Delete Confirmation Modal */}
      {userToDelete && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6 animate-in zoom-in-95 duration-200">
            <div className="flex items-center gap-4 text-amber-600 mb-4">
              <div className="p-3 bg-amber-100 rounded-full">
                <AlertTriangle className="w-6 h-6" />
              </div>
              <h3 className="text-lg font-bold text-slate-900">Xác nhận xóa</h3>
            </div>
            <p className="text-slate-600 mb-6">
              Bạn có chắc chắn muốn xóa người dùng <span className="font-bold text-slate-800">{userToDelete.name}</span>? 
              <br />
              <span className="text-sm text-slate-500 mt-2 block">Hành động này không thể hoàn tác và sẽ xóa toàn bộ dữ liệu liên quan.</span>
            </p>
            <div className="flex justify-end gap-3">
              <button
                onClick={() => setUserToDelete(null)}
                className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg font-medium transition-colors"
              >
                Hủy bỏ
              </button>
              <button
                onClick={confirmDelete}
                className="px-4 py-2 bg-red-600 text-white hover:bg-red-700 rounded-lg font-medium shadow-sm shadow-red-200 transition-colors"
              >
                Xóa vĩnh viễn
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Add/Edit User Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-xl shadow-xl max-w-lg w-full p-6 animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-6 border-b border-slate-100 pb-4">
              <h3 className="text-xl font-bold text-slate-800">
                {modalMode === 'add' ? 'Thêm người dùng mới' : 'Cập nhật thông tin'}
              </h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600 transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-4">
              {/* Name */}
              <div>
                 <label className="block text-sm font-medium text-slate-700 mb-1">Họ và tên</label>
                 <input 
                   type="text"
                   required
                   placeholder="Nhập họ tên đầy đủ"
