  const [copied, setCopied] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'google' | 'vercel'>('google');

  const handleCopy = (text: string, id: string) => {
    navigator.clipboard.writeText(text);
    setCopied(id);
    setTimeout(() => setCopied(null), 2000);
  };

  const gasCode = `// --- COPY TOÀN BỘ CODE NÀY VÀO APPS SCRIPT ---

var SHEET_NAME = "Users";

// Hàm hỗ trợ lấy ngày giờ hiện tại
function getCurrentTime() {
  return new Date().toLocaleString("vi-VN", { timeZone: "Asia/Ho_Chi_Minh" });
}

// 1. GET: Lấy danh sách users (Admin Dashboard dùng)
function doGet(e) {
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_NAME);
  if (!sheet) return ContentService.createTextOutput(JSON.stringify([])).setMimeType(ContentService.MimeType.JSON);

  var data = sheet.getDataRange().getValues();
  var users = [];

  // Bỏ qua dòng tiêu đề (index 0)
  for (var i = 1; i < data.length; i++) {
    var row = data[i];
    // Mapping cột Excel -> JSON
    users.push({
      id: row[0],             // A: MachineID/UserID
      name: row[1],           // B: Name
      company: row[2],        // C: Company
      status: row[3],         // D: Status
      expirationDate: row[4], // E: Expiration
      lastLogin: row[5],      // F: LastLogin
      email: row[6] || "",    // G: Email
      licenseType: row[7] || "subscription" // H: Type
    });
  }

  return ContentService.createTextOutput(JSON.stringify(users))
    .setMimeType(ContentService.MimeType.JSON);
}

// 2. POST: Xử lý Check License & Đăng Ký Mới từ Revit API
function doPost(e) {
  try {
    var data = JSON.parse(e.postData.contents);
    var sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_NAME);

    // Tự tạo Sheet nếu chưa có
    if (!sheet) {
      sheet = SpreadsheetApp.getActiveSpreadsheet().insertSheet(SHEET_NAME);
      sheet.appendRow(["MachineID", "Name", "Company", "Status", "Expiration", "LastLogin", "Email", "LicenseType"]);
    }

    var action = data.action || "check"; // check | register

    // --- CASE 1: ĐĂNG KÝ TÀI KHOẢN MỚI ---
    if (action === "register") {
      var rows = sheet.getDataRange().getValues();
      // Kiểm tra trùng lặp MachineID
      for (var i = 1; i < rows.length; i++) {
        if (rows[i][0] == data.machineId) {
          return ContentService.createTextOutput(JSON.stringify({ 
            "success": false, 
            "message": "Machine ID already registered." 
          })).setMimeType(ContentService.MimeType.JSON);
        }
      }

      // Thêm dòng mới (Mặc định là 'on_hold' hoặc 'trial' chờ duyệt)
      var newRow = [
        data.machineId,
        data.name || "Unknown User",
        data.company || "Unknown Company",
        "on_hold", // Mặc định chờ duyệt
        data.expirationDate || "2025-12-31", // Mặc định 1 năm nếu không gửi
        getCurrentTime(),
        data.email || "",
        "trial"
      ];

      sheet.appendRow(newRow);

      return ContentService.createTextOutput(JSON.stringify({ 
        "success": true, 
        "message": "Registration successful. Waiting for admin approval." 
      })).setMimeType(ContentService.MimeType.JSON);
    }

    // --- CASE 2: KIỂM TRA LICENSE (Mặc định) ---
    var rows = sheet.getDataRange().getValues();
    var isValid = false;
    var message = "Machine ID not found";
    var foundRowIndex = -1;

    for (var i = 1; i < rows.length; i++) {
      if (rows[i][0] == data.machineId) {
        foundRowIndex = i + 1;

        var status = rows[i][3];
        var expDateStr = rows[i][4];

        if (status == "active") {
           var expDate = new Date(expDateStr);
           var today = new Date();
           if (expDate >= today) {
             isValid = true;
             message = "Authorized";
           } else {
             message = "License Expired";
           }
        } else if (status == "on_hold") {
           message = "Account Pending Approval";
        } else {
           message = "Account Blocked";
        }
        break;
      }
    }

    // Cập nhật thời gian đăng nhập nếu tìm thấy
    if (foundRowIndex > -1) {
       sheet.getRange(foundRowIndex, 6).setValue(getCurrentTime());
    }

    return ContentService.createTextOutput(JSON.stringify({ 
      "isValid": isValid, 
      "message": message 
    })).setMimeType(ContentService.MimeType.JSON);

  } catch(err) {
    return ContentService.createTextOutput(JSON.stringify({ "error": err.toString() }));
  }
}
// --- HẾT COPY ---`;

  const csharpCode = `// C# Example for Revit API (RestSharp or HttpClient)
