import { GoogleGenAI } from "@google/genai";
import { User, Session } from '../types';

declare const process: { env: any };

const getClient = () => {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const generateLicenseReport = async (users: User[], sessions: Session[], query: string): Promise<string> => {
    try {
        const client = getClient();

        const systemInstruction = `
            Bạn là một trợ lý quản trị viên chuyên nghiệp cho hệ thống quản lý License Revit Add-in.
            Bạn sẽ nhận được dữ liệu JSON về người dùng và các phiên đăng nhập.

            Nhiệm vụ:
            1. Trả lời câu hỏi dựa trên dữ liệu thật.
            2. Phân tích xu hướng (phiên bản Revit, công ty hoạt động mạnh).
            3. Cảnh báo rủi ro (license sắp hết hạn, IP lạ, nhiều máy dùng chung 1 account).

            Trả lời bằng Tiếng Việt, ngắn gọn, súc tích, định dạng Markdown đẹp mắt.
        `;

        const dataContext = JSON.stringify({
            totalUsers: users.length,
            activeSessions: sessions.length,
            usersData: users,
            sessionsData: sessions
        });

        const prompt = `
            Dữ liệu hệ thống hiện tại:
            ${dataContext}

            Câu hỏi từ quản trị viên: "${query}"
        `;

        const response = await client.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                systemInstruction: systemInstruction,
            }
        });

        return response.text || "Xin lỗi, tôi không thể xử lý yêu cầu lúc này.";

    } catch (error) {
        console.error("Gemini API Error:", error);
        return "Đã xảy ra lỗi khi kết nối với AI. Vui lòng thử lại sau.";
    }
};

import React from 'react';
import { User, Session } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Users, Wifi, AlertTriangle, ShieldCheck, Clock, Activity, CheckCircle2, XCircle, RefreshCw } from 'lucide-react';

interface DashboardProps {
  users: User[];
  sessions: Session[];
  onUpdateStatus: (id: string, status: User['status']) => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ users, sessions, onUpdateStatus }) => {
  // Calculate Stats
  const activeUsers = users.filter(u => u.status === 'active').length;
  const expiredUsers = users.filter(u => u.status === 'expired').length;
  const totalSessions = sessions.length;

  // Identify users that need attention (On Hold status) for the "Quick Approval" feature
  const pendingRequests = users
    .filter(u => u.status === 'on_hold')
    .sort((a, b) => new Date(b.lastLogin).getTime() - new Date(a.lastLogin).getTime());

  // If no pending, show recently active ones but with status badges
  const recentActivity = pendingRequests.length > 0 
    ? pendingRequests 
    : [...users].sort((a, b) => new Date(b.lastLogin).getTime() - new Date(a.lastLogin).getTime()).slice(0, 5);

  // Calculate Expiring Users (Next 30 Days)
  const expiringUsers = users.filter(user => {
    if (user.status === 'expired' || user.status === 'blocked') return false;

    const expDate = new Date(user.expirationDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const diffTime = expDate.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    return diffDays >= 0 && diffDays <= 30;
  }).sort((a, b) => new Date(a.expirationDate).getTime() - new Date(b.expirationDate).getTime());

  // Data for Charts
  const revitVersionData = sessions.reduce((acc: any[], session) => {
    const existing = acc.find(item => item.name === session.revitVersion);
    if (existing) {
      existing.value += 1;
    } else {
      acc.push({ name: session.revitVersion, value: 1 });
    }
    return acc;
  }, []);

  const licenseTypeData = users.reduce((acc: any[], user) => {
    const existing = acc.find(item => item.name === user.licenseType);
    if (existing) {
      existing.value += 1;
    } else {
      acc.push({ name: user.licenseType, value: 1 });
    }
    return acc;
  }, []);

  const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444'];

  const StatCard = ({ title, value, icon: Icon, color, bg }: any) => (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-start justify-between hover:shadow-md transition-shadow">
      <div>
        <p className="text-sm font-medium text-slate-500 mb-1">{title}</p>
        <h3 className="text-2xl font-bold text-slate-800">{value}</h3>
      </div>
      <div className={`p-3 rounded-lg ${bg}`}>
        <Icon className={`w-6 h-6 ${color}`} />
      </div>
    </div>
  );

  return (
