export default async function handler(req: Request) {
  if (req.method !== 'POST') {
    return new Response(JSON.stringify({ error: 'Method not allowed' }), {
      status: 405,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  try {
    const data = await req.json();

    // Kiểm tra dữ liệu đầu vào từ Revit Tool
    if (!data.email || !data.machineId || !data.name) {
      return new Response(JSON.stringify({ error: 'Thiếu thông tin bắt buộc' }), {
        status: 400,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    // Ghi dữ liệu trực tiếp vào Firestore qua REST API 
    // (Để tránh cài thêm thư viện nặng trong Edge Function)
    const projectId = "your-project-id"; // THAY THẾ PROJECT ID CỦA BẠN
    const firestoreUrl = `https://firestore.googleapis.com/v1/projects/${projectId}/databases/(default)/documents/users/${data.machineId}?updateMask.fieldPaths=name&updateMask.fieldPaths=email&updateMask.fieldPaths=company&updateMask.fieldPaths=status&updateMask.fieldPaths=licenseType&updateMask.fieldPaths=expirationDate&updateMask.fieldPaths=lastLogin`;

    const response = await fetch(firestoreUrl, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        fields: {
          id: { stringValue: data.machineId },
          name: { stringValue: data.name },
          email: { stringValue: data.email },
          company: { stringValue: data.company || "Unknown" },
          status: { stringValue: "on_hold" }, // Mặc định chờ duyệt
          licenseType: { stringValue: "trial" },
          expirationDate: { stringValue: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0] },
          lastLogin: { stringValue: new Date().toISOString() }
        }
      })
    });

    if (!response.ok) {
        throw new Error('Firestore Error');
    }

    return new Response(JSON.stringify({ 
      success: true, 
      message: 'Đã nhận yêu cầu đăng ký, vui lòng chờ admin duyệt.' 
    }), {
      status: 200,
      headers: { 
        'Content-Type': 'application/json',
        'Access-Control-Allow-Origin': '*' // Cho phép gọi từ Tool
      },
    });

  } catch (error) {
    return new Response(JSON.stringify({ error: 'Internal Server Error', details: error.message }), {
      status: 500,
      headers: { 'Content-Type': 'application/json' },
    });
  }
}

