import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { UserManagement } from './components/UserManagement';
import { SessionMonitor } from './components/SessionMonitor';
import { AiAssistant } from './components/AiAssistant';
import { IntegrationGuide } from './components/IntegrationGuide';
import { LoginScreen } from './components/LoginScreen';
import { AppView, User, Session } from './types';
import { MOCK_USERS, MOCK_SESSIONS } from './constants';
import { Menu, RotateCcw, Download, Upload, Cloud, RefreshCw } from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => {
    return localStorage.getItem('app_auth_token') === 'true';
  });

  const [currentView, setCurrentView] = useState<AppView>(() => {
    return (localStorage.getItem('app_current_view') as AppView) || AppView.DASHBOARD;
  });

  const [users, setUsers] = useState<User[]>(() => {
    const saved = localStorage.getItem('app_users_data');
    return saved ? JSON.parse(saved) : MOCK_USERS;
  });

  const [sessions, setSessions] = useState<Session[]>(() => {
    const saved = localStorage.getItem('app_sessions_data');
    return saved ? JSON.parse(saved) : MOCK_SESSIONS;
  });

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  // Auto-save to LocalStorage
  useEffect(() => {
    localStorage.setItem('app_users_data', JSON.stringify(users));
    localStorage.setItem('app_sessions_data', JSON.stringify(sessions));
    localStorage.setItem('app_current_view', currentView);
  }, [users, sessions, currentView]);

  const handleSyncCloud = async () => {
    setIsSyncing(true);
    try {
        const response = await fetch('/api/register');
        if (response.ok) {
            const pendingRequests: User[] = await response.json();
            if (pendingRequests.length > 0) {
                // Lọc bỏ những người đã tồn tại dựa trên ID
                const newUsers = pendingRequests.filter(req => !users.some(u => u.id === req.id));
                if (newUsers.length > 0) {
                    setUsers(prev => [...newUsers, ...prev]);
                    alert(`Đã tải xuống ${newUsers.length} yêu cầu đăng ký mới!`);
                } else {
                    alert("Không có yêu cầu mới nào.");
                }
            } else {
                alert("Cloud đang trống.");
            }
        }
    } catch (e) {
        alert("Lỗi đồng bộ. Hãy đảm bảo bạn đã cấu hình Vercel KV.");
    } finally {
        setIsSyncing(false);
    }
  };

  const handleExportData = () => {
    const data = { users, sessions, exportDate: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `revit_license_backup_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
  };

  const handleImportData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
        try {
            const data = JSON.parse(event.target?.result as string);
            if (data.users && Array.isArray(data.users)) {
                setUsers(data.users);
                if (data.sessions) setSessions(data.sessions);
                alert("Khôi phục dữ liệu thành công!");
            }
        } catch (err) {
            alert("File không hợp lệ.");
        }
    };
    reader.readAsText(file);
  };

  const handleLogin = () => {
    localStorage.setItem('app_auth_token', 'true');
    setIsAuthenticated(true);
  };

  const handleLogout = () => {
    localStorage.removeItem('app_auth_token');
    setIsAuthenticated(false);
  };

  const handleUpdateStatus = (id: string, newStatus: User['status']) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, status: newStatus } : u));
  };

  const handleDeleteUser = (id: string) => {
    if(window.confirm("Xóa người dùng này?")) {
        setUsers(prev => prev.filter(u => u.id !== id));
    }
  };

  if (!isAuthenticated) return <LoginScreen onLogin={handleLogin} />;

  return (
    <div className="flex h-screen bg-slate-50 font-sans overflow-hidden">
      <Sidebar 
        currentView={currentView} 
        setCurrentView={setCurrentView} 
        isMobileOpen={isMobileMenuOpen}
        onCloseMobile={() => setIsMobileMenuOpen(false)}
        onLogout={handleLogout}
      />

      <main className="flex-1 flex flex-col h-full w-full relative overflow-hidden">
        <header className="flex-none px-4 py-4 md:px-8 border-b border-slate-200 bg-white shadow-sm flex justify-between items-center z-20">
          <div className="flex items-center gap-3">
             <button onClick={() => setIsMobileMenuOpen(true)} className="md:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                <Menu className="w-6 h-6" />
             </button>
             <div>
                <h1 className="text-lg md:text-2xl font-bold text-slate-800">
                  {currentView}
                </h1>
                <div className="text-xs text-slate-500 flex items-center gap-1">
                    <span className="w-2 h-2 rounded-full bg-blue-500 animate-pulse"></span>
                    Local Storage Mode
                </div>
             </div>
          </div>

          <div className="flex items-center gap-2 md:gap-4">
            <button 
                onClick={handleSyncCloud}
                disabled={isSyncing}
                className="hidden sm:flex items-center gap-2 px-3 py-2 bg-indigo-50 text-indigo-700 rounded-lg hover:bg-indigo-100 transition-colors text-sm font-medium"
                title="Tải yêu cầu từ Revit Tool"
            >
                {isSyncing ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Cloud className="w-4 h-4" />}
                Đồng bộ Cloud
            </button>

            <div className="h-8 w-px bg-slate-200"></div>

            <div className="flex items-center gap-1">
                <button onClick={handleExportData} className="p-2 text-slate-500 hover:text-blue-600 hover:bg-slate-100 rounded-lg" title="Backup (Tải về JSON)">
                    <Download className="w-5 h-5" />
                </button>
                <label className="p-2 text-slate-500 hover:text-green-600 hover:bg-slate-100 rounded-lg cursor-pointer" title="Restore (Tải lên JSON)">
                    <Upload className="w-5 h-5" />
                    <input type="file" className="hidden" accept=".json" onChange={handleImportData} />
                </label>
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-8 bg-slate-50">
            <div className="max-w-7xl mx-auto">
                {currentView === AppView.DASHBOARD && <Dashboard users={users} sessions={sessions} onUpdateStatus={handleUpdateStatus} />}
                {currentView === AppView.USERS && <UserManagement users={users} onAddUser={(u)=>setUsers([u, ...users])} onEditUser={(u)=>setUsers(users.map(x=>x.id===u.id?u:x))} onUpdateStatus={handleUpdateStatus} onDeleteUser={handleDeleteUser} />}
                {currentView === AppView.SESSIONS && <SessionMonitor sessions={sessions} users={users} onKillSession={(id)=>setSessions(sessions.filter(s=>s.id!==id))} onAddSession={(s)=>setSessions([s, ...sessions])} />}
                {currentView === AppView.AI_INSIGHTS && <AiAssistant users={users} sessions={sessions} />}
                {currentView === AppView.INTEGRATION && <IntegrationGuide />}
            </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import { initializeApp } from "firebase/app";
import { 
  getFirestore, 
  collection, 
  onSnapshot, 
  doc, 
  updateDoc, 
  setDoc, 
  deleteDoc, 
  query, 
  orderBy,
  QuerySnapshot,
  DocumentData
} from "firebase/firestore";
import { User, Session } from '../types';

// CẤU HÌNH FIREBASE: Thay thế bằng thông số từ dự án Firebase của bạn
const firebaseConfig = {
  apiKey: "YOUR_API_KEY",
  authDomain: "your-project-id.firebaseapp.com",
  projectId: "your-project-id",
  storageBucket: "your-project-id.appspot.com",
  messagingSenderId: "your-id",
  appId: "your-app-id"
};

const app = initializeApp(firebaseConfig);
export const db = getFirestore(app);

// Các hàm thao tác với Users
export const subscribeToUsers = (callback: (users: User[]) => void) => {
  const q = query(collection(db, "users"), orderBy("name", "asc"));
  return onSnapshot(q, (snapshot: QuerySnapshot<DocumentData>) => {
    const users = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as User));
    callback(users);
  });
};

export const updateFirestoreUser = async (userId: string, data: Partial<User>) => {
  const userRef = doc(db, "users", userId);
  await updateDoc(userRef, data);
};

export const addFirestoreUser = async (user: User) => {
  const userRef = doc(db, "users", user.id);
  await setDoc(userRef, user);
};

export const deleteFirestoreUser = async (userId: string) => {
  await deleteDoc(doc(db, "users", userId));
};

// Các hàm thao tác với Sessions
export const subscribeToSessions = (callback: (sessions: Session[]) => void) => {
  const q = query(collection(db, "sessions"), orderBy("loginTime", "desc"));
  return onSnapshot(q, (snapshot: QuerySnapshot<DocumentData>) => {
    const sessions = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as Session));
    callback(sessions);
  });
};

export const addFirestoreSession = async (session: Session) => {
  const sessionRef = doc(db, "sessions", session.id);
  await setDoc(sessionRef, session);
};

export const deleteFirestoreSession = async (sessionId: string) => {
  await deleteDoc(doc(db, "sessions", sessionId));
};

// Hàm khởi tạo dữ liệu mẫu nếu Database trống (Dùng cho lần đầu setup)
export const seedDatabase = async (mockUsers: User[], mockSessions: Session[]) => {
    for (const user of mockUsers) {
        await addFirestoreUser(user);
    }
    for (const session of mockSessions) {
        await addFirestoreSession(session);
    }
};

import { createClient } from '@vercel/kv';

export const config = {
  runtime: 'edge',
};

// Khởi tạo KV Client
const kv = createClient({
  url: process.env.KV_REST_API_URL || '',
  token: process.env.KV_REST_API_TOKEN || '',
});

export default async function handler(req: Request) {
  if (req.method === 'GET') {
    try {
        const pendingRequests = await kv.lrange('pending_registrations', 0, -1);
        return new Response(JSON.stringify(pendingRequests), {
            status: 200,
            headers: { 'Content-Type': 'application/json' },
        });
    } catch (e) {
        return new Response(JSON.stringify([]), { status: 200 });
    }
  }

  if (req.method !== 'POST') {
    return new Response(JSON.stringify({ error: 'Method not allowed' }), { status: 405 });
  }

  try {
    const data = await req.json();
    if (!data.machineId || !data.name) {
      return new Response(JSON.stringify({ error: 'Thiếu thông tin' }), { status: 400 });
    }

    const newRequest = {
        ...data,
        id: data.machineId,
        status: 'on_hold',
        licenseType: 'trial',
        expirationDate: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
        lastLogin: new Date().toISOString(),
        timestamp: Date.now()
    };

    await kv.lpush('pending_registrations', newRequest);

    return new Response(JSON.stringify({ 
      success: true, 
      message: 'Yêu cầu đã được lưu trên Cloud. Admin sẽ duyệt sớm.' 
    }), {
      status: 200,
      headers: { 
        'Content-Type': 'application/json',
        'Access-Control-Allow-Origin': '*'
      },
    });

  } catch (error) {
    return new Response(JSON.stringify({ error: 'Internal Error' }), { status: 500 });
  }
}

