using Newtonsoft.Json;
using System;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;

namespace DSH_RevitAPI
{
    public class ApiResponse
    {
        public bool Success { get; set; }
        public string Message { get; set; }
        public string Token { get; set; }
    }

    public class AuthService
    {
        // URL thực tế của bạn
        private readonly string _baseUrl = "https://revit-a4snd1b8a-hungdoans-projects-1dbfedff.vercel.app/api/register";
        private readonly HttpClient _httpClient;

        public AuthService()
        {
            _httpClient = new HttpClient();
            _httpClient.Timeout = TimeSpan.FromSeconds(10);
        }

        // Hàm Đăng Nhập
        public async Task<ApiResponse> LoginAsync(string email, string password)
        {
            var data = new
            {
                email = email,
                password = password
            };

            return await PostDataAsync("/login", data);
        }

        // Hàm Đăng Ký (Đã bỏ tham số licenseKey)
        public async Task<ApiResponse> RegisterAsync(string name, string email, string password)
        {
            var data = new
            {
                fullName = name,
                email = email,
                password = password
                // status = "pending" (Backend tự xử lý)
            };

            // Dùng endpoint /register cho đúng ngữ nghĩa, hoặc /activate tùy backend của bạn
            return await PostDataAsync("/register", data);
        }

        private async Task<ApiResponse> PostDataAsync(string endpoint, object data)
        {
            try
            {
                var json = JsonConvert.SerializeObject(data);
                var content = new StringContent(json, Encoding.UTF8, "application/json");

                var response = await _httpClient.PostAsync(_baseUrl + endpoint, content);
                var responseString = await response.Content.ReadAsStringAsync();

                var result = JsonConvert.DeserializeObject<ApiResponse>(responseString);

                if (result == null)
                {
                    return new ApiResponse { Success = false, Message = "Server trả về dữ liệu không hợp lệ." };
                }

                return result;
            }
            catch (Exception ex)
            {
                return new ApiResponse { Success = false, Message = "Lỗi kết nối: " + ex.Message };
            }
        }
    }
