        };

        // Lưu vào KV list
        await kv.lpush('pending_registrations', newRequest);

        return new Response(JSON.stringify({
          Success: true,
          Message: "Yêu cầu đăng ký đã được gửi tới hệ thống. Vui lòng chờ Admin kích hoạt.",
          Token: ""
        }), { status: 200, headers });
      }

      // TRƯỜNG HỢP: ĐĂNG NHẬP (/api/register/login)
      if (path.endsWith('/login')) {
        const { email, password } = body;

        // Logic kiểm tra đơn giản: Hiện tại chúng ta trả về thông báo chờ duyệt
        // vì dữ liệu đang nằm trong hàng chờ 'pending_registrations'
        return new Response(JSON.stringify({
          Success: false,
          Message: "Tài khoản của bạn đang trong trạng thái chờ duyệt hoặc thông tin không chính xác.",
          Token: ""
        }), { status: 200, headers });
      }

      return new Response(JSON.stringify({ Success: false, Message: "Endpoint không hợp lệ", Token: "" }), { status: 404, headers });

    } catch (error) {
      return new Response(JSON.stringify({ Success: false, Message: "Lỗi hệ thống API", Token: "" }), { status: 500, headers });
    }
  }

  return new Response('Not Found', { status: 404 });
}

