          licenseType: 'trial',
          expirationDate: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
          lastLogin: new Date().toISOString(),
          machineId: body.machineId || "Revit-Tool"
        };

        // Lưu vào danh sách chờ duyệt
        await kv.lpush('pending_registrations', newRequest);

        return new Response(JSON.stringify({
          Success: true,
          Message: "Gửi yêu cầu thành công! Admin sẽ duyệt tài khoản của bạn sớm.",
          Token: ""
        }), { status: 200, headers });
      }

      // XỬ LÝ ĐĂNG NHẬP
      if (path.endsWith('/login')) {
        const { email, password } = body;

        // Tìm trong danh sách chờ duyệt (giả lập database người dùng)
        const allPending = await kv.lrange('pending_registrations', 0, -1);
        const user = allPending.find((u: any) => u.email === email && u.password === password);

        if (user) {
          // Nếu user tồn tại nhưng Admin chưa đổi status trên web sang 'active'
          if (user.status === 'active') {
            return new Response(JSON.stringify({
              Success: true,
              Message: "Đăng nhập thành công!",
              Token: "auth-token-" + Date.now()
            }), { status: 200, headers });
          } else {
            return new Response(JSON.stringify({
              Success: false,
              Message: "Tài khoản chưa được kích hoạt. Vui lòng liên hệ Admin để duyệt.",
              Token: ""
            }), { status: 200, headers });
          }
        }

        return new Response(JSON.stringify({
          Success: false,
          Message: "Email hoặc mật khẩu không chính xác.",
          Token: ""
        }), { status: 200, headers });
      }

      return new Response(JSON.stringify({ Success: false, Message: "Đường dẫn API không hợp lệ.", Token: "" }), { status: 404, headers });

    } catch (error: any) {
      return new Response(JSON.stringify({ 
        Success: false, 
        Message: "Lỗi Server: " + (error.message || "Unknown error"), 
        Token: "" 
      }), { status: 200, headers });
    }
  }

  return new Response('Not Found', { status: 404 });
}

import { createClient } from '@vercel/kv';

export const config = {
  runtime: 'edge',
};

// Khởi tạo KV client (chỉ khởi tạo khi có biến môi trường)
const kvUrl = process.env.KV_REST_API_URL;
const kvToken = process.env.KV_REST_API_TOKEN;

const kv = (kvUrl && kvToken) ? createClient({
  url: kvUrl,
  token: kvToken,
}) : null;

export default async function handler(req: Request) {
  const url = new URL(req.url);
  const path = url.pathname;

  const headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'POST, GET, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type',
  };

  if (req.method === 'OPTIONS') {
    return new Response(null, { status: 204, headers });
  }

  // Kiểm tra cấu hình KV
  if (!kv) {
    return new Response(JSON.stringify({ 
      Success: false, 
      Message: "Chưa cấu hình Database! Hãy chọn 'Upstash' -> 'Redis' trong tab Storage của Vercel.", 
      Token: "" 
    }), { status: 200, headers });
  }

  // GET: Lấy danh sách cho Dashboard Web
  if (req.method === 'GET') {
    try {
      const pendingRequests = await kv.lrange('pending_registrations', 0, -1);
      return new Response(JSON.stringify(pendingRequests || []), { status: 200, headers });
    } catch (e: any) {
      return new Response(JSON.stringify({ error: e.message }), { status: 500, headers });
    }
  }

  // POST: Xử lý từ Revit Tool
  if (req.method === 'POST') {
    try {
      const body = await req.json();

      // XỬ LÝ ĐĂNG KÝ
      if (path.endsWith('/register')) {
        const { fullName, email, password, machineId } = body;

        if (!email || !password) {
           return new Response(JSON.stringify({ Success: false, Message: "Thiếu Email hoặc Mật khẩu.", Token: "" }), { status: 200, headers });
        }

        const newRequest = {
          id: `U${Date.now()}`,
          name: fullName || "User mới",
          email: email,
          password: password, 
          status: 'on_hold',
          licenseType: 'trial',
          expirationDate: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
          lastLogin: new Date().toISOString(),
          machineId: machineId || "Revit-Tool-PC"
        };

        // Lưu vào KV (Redis List)
        await kv.lpush('pending_registrations', newRequest);

        return new Response(JSON.stringify({
          Success: true,
          Message: "Đăng ký thành công! Vui lòng chờ Admin kích hoạt trên trang quản trị.",
          Token: ""
        }), { status: 200, headers });
      }

      // XỬ LÝ ĐĂNG NHẬP
      if (path.endsWith('/login')) {
        const { email, password } = body;
        const allPending = await kv.lrange('pending_registrations', 0, -1);
        const user = allPending.find((u: any) => u.email === email && u.password === password);

        if (user) {
          if (user.status === 'active') {
            return new Response(JSON.stringify({
              Success: true,
              Message: "Đăng nhập thành công!",
              Token: "token_" + Math.random().toString(36).substring(7)
            }), { status: 200, headers });
          } else {
            return new Response(JSON.stringify({
              Success: false,
              Message: "Tài khoản của bạn đang chờ Admin duyệt (Trạng thái: On Hold).",
              Token: ""
            }), { status: 200, headers });
          }
        }

        return new Response(JSON.stringify({
          Success: false,
          Message: "Email hoặc mật khẩu không đúng.",
          Token: ""
        }), { status: 200, headers });
      }

      return new Response(JSON.stringify({ Success: false, Message: "Sai đường dẫn API", Token: "" }), { status: 404, headers });

    } catch (error: any) {
      return new Response(JSON.stringify({ Success: false, Message: "Lỗi Server: " + error.message, Token: "" }), { status: 200, headers });
    }
  }

  return new Response('Method Not Allowed', { status: 405 });
}

import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { UserManagement } from './components/UserManagement';
import { SessionMonitor } from './components/SessionMonitor';
import { AiAssistant } from './components/AiAssistant';
import { IntegrationGuide } from './components/IntegrationGuide';
import { LoginScreen } from './components/LoginScreen';
import { AppView, User, Session } from './types';
import { MOCK_USERS, MOCK_SESSIONS } from './constants';
import { Menu, RotateCcw, Download, Upload, Cloud, RefreshCw, CheckCircle2 } from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => {
    return localStorage.getItem('app_auth_token') === 'true';
  });

  const [currentView, setCurrentView] = useState<AppView>(() => {
    return (localStorage.getItem('app_current_view') as AppView) || AppView.DASHBOARD;
  });

  const [users, setUsers] = useState<User[]>(() => {
    const saved = localStorage.getItem('app_users_data');
    return saved ? JSON.parse(saved) : MOCK_USERS;
  });

  const [sessions, setSessions] = useState<Session[]>(() => {
    const saved = localStorage.getItem('app_sessions_data');
    return saved ? JSON.parse(saved) : MOCK_SESSIONS;
  });

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  useEffect(() => {
    localStorage.setItem('app_users_data', JSON.stringify(users));
    localStorage.setItem('app_sessions_data', JSON.stringify(sessions));
    localStorage.setItem('app_current_view', currentView);
  }, [users, sessions, currentView]);

  const handleSyncCloud = async () => {
    setIsSyncing(true);
    try {
        // Gọi API để lấy danh sách từ Vercel KV
        const response = await fetch('/api/register');
        const data = await response.json();

        if (data.Success === false && data.Message.includes("cấu hình")) {
            alert(data.Message);
            return;
        }

        if (Array.isArray(data) && data.length > 0) {
            // Chỉ thêm những user chưa có trong danh sách local (dựa trên email)
            const newUsersFromCloud = data.filter(cloudUser => 
                !users.some(localUser => localUser.email === cloudUser.email)
            );

            if (newUsersFromCloud.length > 0) {
                setUsers(prev => [...newUsersFromCloud, ...prev]);
                alert(`Đã đồng bộ ${newUsersFromCloud.length} yêu cầu đăng ký mới! Hãy chuyển họ sang trạng thái 'Active' để họ có thể đăng nhập.`);
            } else {
                alert("Dữ liệu đã được cập nhật mới nhất.");
            }
        } else {
            alert("Không có yêu cầu đăng ký mới nào trên Cloud.");
        }
    } catch (e) {
        console.error("Sync error:", e);
        alert("Lỗi kết nối API Cloud. Hãy đảm bảo bạn đã deploy thành công.");
    } finally {
        setIsSyncing(false);
    }
  };

  const handleExportData = () => {
    const data = { users, sessions, exportDate: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `revit_license_backup_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
  };

  const handleLogin = () => {
    localStorage.setItem('app_auth_token', 'true');
    setIsAuthenticated(true);
  };

  const handleLogout = () => {
    localStorage.removeItem('app_auth_token');
    setIsAuthenticated(false);
  };

  const handleUpdateStatus = (id: string, newStatus: User['status']) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, status: newStatus } : u));
  };

  const handleDeleteUser = (id: string) => {
    if(window.confirm("Xóa người dùng này?")) {
        setUsers(prev => prev.filter(u => u.id !== id));
    }
  };

  if (!isAuthenticated) return <LoginScreen onLogin={handleLogin} />;

  return (
    <div className="flex h-screen bg-slate-50 font-sans overflow-hidden">
      <Sidebar 
        currentView={currentView} 
        setCurrentView={setCurrentView} 
        isMobileOpen={isMobileMenuOpen}
        onCloseMobile={() => setIsMobileMenuOpen(false)}
        onLogout={handleLogout}
      />

      <main className="flex-1 flex flex-col h-full w-full relative overflow-hidden">
        <header className="flex-none px-4 py-4 md:px-8 border-b border-slate-200 bg-white shadow-sm flex justify-between items-center z-20">
          <div className="flex items-center gap-3">
             <button onClick={() => setIsMobileMenuOpen(true)} className="md:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                <Menu className="w-6 h-6" />
             </button>
             <div>
                <h1 className="text-lg md:text-xl font-bold text-slate-800">{currentView}</h1>
                <div className="text-[10px] text-slate-500 flex items-center gap-1">
                    <span className="w-1.5 h-1.5 rounded-full bg-green-500"></span>
                    Hệ thống quản trị License
                </div>
             </div>
          </div>

          <div className="flex items-center gap-2 md:gap-4">
            <button 
                onClick={handleSyncCloud}
                disabled={isSyncing}
                className="flex items-center gap-2 px-3 py-1.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors text-xs font-semibold shadow-sm disabled:opacity-50"
            >
                {isSyncing ? <RefreshCw className="w-3.5 h-3.5 animate-spin" /> : <Cloud className="w-3.5 h-3.5" />}
                Sync Cloud
            </button>
            <div className="h-6 w-px bg-slate-200"></div>
            <button onClick={handleExportData} className="p-1.5 text-slate-400 hover:text-blue-600 hover:bg-slate-50 rounded-lg transition-colors" title="Backup">
                <Download className="w-4 h-4" />
            </button>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-8">
            <div className="max-w-7xl mx-auto">
                {currentView === AppView.DASHBOARD && <Dashboard users={users} sessions={sessions} onUpdateStatus={handleUpdateStatus} />}
                {currentView === AppView.USERS && <UserManagement users={users} onAddUser={(u)=>setUsers([u, ...users])} onEditUser={(u)=>setUsers(users.map(x=>x.id===u.id?u:x))} onUpdateStatus={handleUpdateStatus} onDeleteUser={handleDeleteUser} />}
                {currentView === AppView.SESSIONS && <SessionMonitor sessions={sessions} users={users} onKillSession={(id)=>setSessions(sessions.filter(s=>s.id!==id))} onAddSession={(s)=>setSessions([s, ...sessions])} />}
                {currentView === AppView.AI_INSIGHTS && <AiAssistant users={users} sessions={sessions} />}
                {currentView === AppView.INTEGRATION && <IntegrationGuide />}
            </div>
        </div>
      </main>
    </div>
  );
};

export default App;

