import React, { useState, useEffect } from 'react';
import { User } from '../types';
import { Search, UserPlus, Filter, Trash2, AlertTriangle, X, Pencil, FileJson, CheckCircle2, XCircle, PauseCircle, Check, ChevronDown, Eye, EyeOff } from 'lucide-react';

interface UserManagementProps {
  users: User[];
  onAddUser: (user: User) => void;
  onEditUser: (user: User) => void;
  onUpdateStatus: (id: string, status: User['status']) => void;
  onDeleteUser: (id: string) => void;
}

export const UserManagement: React.FC<UserManagementProps> = ({ users, onUpdateStatus, onDeleteUser, onAddUser, onEditUser }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showPasswords, setShowPasswords] = useState<Record<string, boolean>>({});

  const [statusFilters, setStatusFilters] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('app_user_status_filters');
      return saved ? JSON.parse(saved) : ['all'];
    } catch (e) {
      return ['all'];
    }
  }); 

  const [isFilterDropdownOpen, setIsFilterDropdownOpen] = useState(false);
  const [userToDelete, setUserToDelete] = useState<User | null>(null);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [modalMode, setModalMode] = useState<'add' | 'edit'>('add');
  const [importJson, setImportJson] = useState('');
  const [importError, setImportError] = useState('');

  const [formData, setFormData] = useState<Partial<User>>({
    name: '',
    email: '',
    password: '',
    company: '',
    status: 'active',
    licenseType: 'subscription',
    expirationDate: new Date(new Date().setFullYear(new Date().getFullYear() + 1)).toISOString().split('T')[0],
  });

  useEffect(() => {
    localStorage.setItem('app_user_status_filters', JSON.stringify(statusFilters));
  }, [statusFilters]);

  const togglePasswordVisibility = (userId: string) => {
    setShowPasswords(prev => ({ ...prev, [userId]: !prev[userId] }));
  };

  const filteredUsers = users.filter(user => {
    const matchesSearch = user.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          user.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          user.company.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = statusFilters.includes('all') || statusFilters.includes(user.status);
    return matchesSearch && matchesStatus;
  });

  const toggleStatusFilter = (status: string) => {
    if (status === 'all') {
      setStatusFilters(['all']);
      return;
    }
    let newFilters = statusFilters.includes('all') ? [] : [...statusFilters];
    if (newFilters.includes(status)) {
      newFilters = newFilters.filter(s => s !== status);
    } else {
      newFilters.push(status);
    }
    if (newFilters.length === 0) newFilters = ['all'];
    setStatusFilters(newFilters);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active': return 'bg-green-100 text-green-700';
      case 'expired': return 'bg-amber-100 text-amber-700';
      case 'blocked': return 'bg-red-100 text-red-700';
      case 'on_hold': return 'bg-indigo-100 text-indigo-700';
      default: return 'bg-slate-100 text-slate-700';
    }
  };

  const getStatusLabel = (status: string) => {
    switch (status) {
        case 'active': return 'Active';
        case 'expired': return 'Expired';
        case 'blocked': return 'Blocked';
        case 'on_hold': return 'On Hold';
        case 'all': return 'Tất cả';
        default: return status;
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
        case 'active': return <CheckCircle2 className="w-5 h-5 text-green-500" />;
        case 'expired': return <AlertTriangle className="w-5 h-5 text-amber-500" />;
        case 'blocked': return <XCircle className="w-5 h-5 text-red-500" />;
        case 'on_hold': return <PauseCircle className="w-5 h-5 text-indigo-500" />;
        default: return <div className="w-5 h-5" />;
    }
  };

  const handleOpenAddModal = () => {
    setModalMode('add');
    setFormData({
        name: '',
        email: '',
        password: '',
        company: '',
        status: 'active',
        licenseType: 'subscription',
        expirationDate: new Date(new Date().setFullYear(new Date().getFullYear() + 1)).toISOString().split('T')[0],
    });
    setIsModalOpen(true);
  };

  const handleOpenEditModal = (user: User) => {
    setModalMode('edit');
    setFormData({ ...user });
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.email || !formData.company || !formData.expirationDate) return;

    if (modalMode === 'add') {
        const userToAdd: User = {
            id: `U${Date.now().toString().slice(-6)}`,
            name: formData.name!,
            email: formData.email!,
            password: formData.password || '123456',
            company: formData.company!,
            status: formData.status as any || 'active',
            licenseType: formData.licenseType as any || 'subscription',
            expirationDate: formData.expirationDate!,
            lastLogin: new Date().toISOString(),
        };
        onAddUser(userToAdd);
    } else {
        if (formData.id) onEditUser(formData as User);
    }
    setIsModalOpen(false);
  };

  const handleImportSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setImportError('');
    try {
        const data = JSON.parse(importJson);
        const userToAdd: User = {
            id: data.machineId || data.id || `U${Date.now()}`,
            name: data.fullName || data.name || "Người dùng mới",
            email: data.email || "no-email@example.com",
            password: data.password || "N/A",
            company: data.company || "Công ty BIM",
            status: 'on_hold',
            licenseType: 'trial',
            expirationDate: new Date(new Date().setMonth(new Date().getMonth() + 1)).toISOString().split('T')[0],
            lastLogin: new Date().toISOString(),
        };
        onAddUser(userToAdd);
        setIsImportModalOpen(false);
        setImportJson('');
    } catch (err: any) {
        setImportError("Lỗi định dạng JSON: " + err.message);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <h2 className="text-2xl font-bold text-slate-800">Quản lý người dùng</h2>
        <div className="flex gap-2">
            <button onClick={() => setIsImportModalOpen(true)} className="bg-slate-800 hover:bg-slate-900 text-white px-4 py-2 rounded-lg flex items-center gap-2 transition-colors">
              <FileJson className="w-4 h-4" />
              <span className="hidden sm:inline">Import API</span>
            </button>
            <button onClick={handleOpenAddModal} className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 transition-colors">
              <UserPlus className="w-4 h-4" />
              <span>Thêm mới</span>
            </button>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="p-4 border-b border-slate-100 flex flex-col sm:flex-row gap-4">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
            <input 
              type="text" 
              placeholder="Tìm kiếm..." 
              className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="relative">
            <button 
                onClick={() => setIsFilterDropdownOpen(!isFilterDropdownOpen)}
                className={`flex items-center gap-2 border rounded-lg px-3 py-2 transition-colors ${!statusFilters.includes('all') ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}
            >
                <Filter className="w-4 h-4" />
                <span className="text-sm font-medium">Lọc trạng thái</span>
                <ChevronDown className="w-4 h-4" />
            </button>
            {isFilterDropdownOpen && (
