                    <div className="fixed inset-0 z-10" onClick={() => setIsFilterDropdownOpen(false)}></div>
                    <div className="absolute right-0 mt-2 w-56 bg-white border border-slate-200 rounded-xl shadow-lg z-20 p-2">
