using DSH_RevitAPI;

namespace DSH_RevitAPI.LicenseMannager
{
    public partial class License_WPF : Window
    {
        private readonly AuthService _authService;

        public License_WPF()
        {
            InitializeComponent();
            _authService = new AuthService();
        }

        // --- QUAN TRỌNG: Cho phép kéo thả cửa sổ khi không có thanh tiêu đề mặc định ---
        protected override void OnMouseLeftButtonDown(MouseButtonEventArgs e)
        {
            base.OnMouseLeftButtonDown(e);
            // Chỉ cho phép kéo khi nhấn chuột trái
            if (e.ButtonState == MouseButtonState.Pressed)
            {
                this.DragMove();
            }
        }

        private void SwitchToRegister_Click(object sender, RoutedEventArgs e)
        {
            LoginView.Visibility = Visibility.Collapsed;
            RegisterView.Visibility = Visibility.Visible;
            TxtRegName.Focus();
        }

        private void SwitchToLogin_Click(object sender, RoutedEventArgs e)
        {
            RegisterView.Visibility = Visibility.Collapsed;
            LoginView.Visibility = Visibility.Visible;
            TxtLoginEmail.Focus();
        }

        // --- XỬ LÝ ĐĂNG NHẬP ---
        private async void BtnLogin_Click(object sender, RoutedEventArgs e)
        {
            string email = TxtLoginEmail.Text;
            string password = TxtLoginPass.Password;

            if (string.IsNullOrWhiteSpace(email) || string.IsNullOrWhiteSpace(password))
            {
                ShowMessage("Lỗi nhập liệu", "Vui lòng nhập đầy đủ Email và Mật khẩu.");
                return;
            }

            var btn = (Wpf.Ui.Controls.Button)sender;
            btn.Content = "Đang kiểm tra...";
            btn.IsEnabled = false;

            try
            {
                // Gọi API kiểm tra đăng nhập
                ApiResponse result = await _authService.LoginAsync(email, password);

                if (result.Success)
                {
                    ShowMessage("Đăng nhập thành công", $"Chào mừng trở lại!\n{result.Message}");
                    this.DialogResult = true; // Báo cho Command biết là thành công
                    this.Close();
                }
                else
                {
                    ShowMessage("Đăng nhập thất bại", result.Message);
                }
            }
            catch (Exception ex)
            {
                ShowMessage("Lỗi hệ thống", ex.Message);
            }
            finally
            {
                // Luôn mở lại nút bấm dù thành công hay thất bại
                btn.Content = "ĐĂNG NHẬP";
                btn.IsEnabled = true;
            }
        }

        // --- XỬ LÝ ĐĂNG KÝ (Gửi yêu cầu chờ duyệt) ---
        private async void BtnRegister_Click(object sender, RoutedEventArgs e)
        {
            string name = TxtRegName.Text;
            string email = TxtRegEmail.Text;
            string pass = TxtRegPass.Password;

            if (string.IsNullOrWhiteSpace(name) || string.IsNullOrWhiteSpace(email) ||
                string.IsNullOrWhiteSpace(pass))
            {
                ShowMessage("Thiếu thông tin", "Vui lòng điền đầy đủ Họ tên, Email và Mật khẩu.");
                return;
            }

            var btn = (Wpf.Ui.Controls.Button)sender;
            btn.Content = "Đang gửi...";
            btn.IsEnabled = false;

            try
            {
                // Gọi API đăng ký
                ApiResponse result = await _authService.RegisterAsync(name, email, pass);

                if (result.Success)
                {
                    ShowMessage("Gửi yêu cầu thành công",
                        $"Tài khoản {email} đã được ghi nhận.\n\nVui lòng chờ Quản trị viên duyệt kích hoạt trước khi đăng nhập.");

                    // Chuyển về màn hình đăng nhập và điền sẵn email
                    SwitchToLogin_Click(null, null);
                    TxtLoginEmail.Text = email;
                    TxtLoginPass.Focus();
                }
                else
                {
                    ShowMessage("Đăng ký thất bại", result.Message);
                }
            }
            catch (Exception ex)
            {
                ShowMessage("Lỗi hệ thống", ex.Message);
            }
            finally
            {
                btn.Content = "GỬI YÊU CẦU ĐĂNG KÝ";
                btn.IsEnabled = true;
            }
        }

        private void ShowMessage(string title, string content)
        {
            System.Windows.MessageBox.Show(content, title,  System.Windows.MessageBoxButton.OK, MessageBoxImage.Information);
        }
    }
