}using Newtonsoft.Json;
using System;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;

namespace DSH_RevitAPI
{
    public class ApiResponse
    {
        public bool Success { get; set; }
        public string Message { get; set; }
    }

    public class AuthService
    {
        // QUAN TRỌNG: Chỉ dùng URL gốc đến file api/register.ts
        private readonly string _baseUrl = "https://revit-api.vercel.app/api/register";
        private readonly HttpClient _httpClient;

        public AuthService()
        {
            _httpClient = new HttpClient();
        }

        public async Task<ApiResponse> LoginAsync(string email, string password)
        {
            var data = new
            {
                action = "login", // Gửi kèm action để API phân biệt
                email = email,
                password = password,
                machineId = Environment.MachineName // Gửi kèm tên máy để quản lý
            };
            return await PostToApi(data);
        }

        public async Task<ApiResponse> RegisterAsync(string name, string email, string password)
        {
            var data = new
            {
                action = "register",
                fullName = name,
                email = email,
                password = password,
                machineId = Environment.MachineName
            };
            return await PostToApi(data);
        }

        private async Task<ApiResponse> PostToApi(object data)
        {
            try
            {
                var json = JsonConvert.SerializeObject(data);
                var content = new StringContent(json, Encoding.UTF8, "application/json");

                var response = await _httpClient.PostAsync(_baseUrl, content);
                var responseString = await response.Content.ReadAsStringAsync();

                return JsonConvert.DeserializeObject<ApiResponse>(responseString);
            }
            catch (Exception ex)
            {
                return new ApiResponse { Success = false, Message = "Lỗi: " + ex.Message };
            }
        }
    }
