import { createClient } from '@vercel/kv';

export const config = {
  runtime: 'edge',
};

const getEnv = (key: string) => {
  return process.env[`KV_${key}`] || process.env[`STORAGE_${key}`] || process.env[key];
};

const kv = createClient({
  url: getEnv('REST_API_URL') || '',
  token: getEnv('REST_API_TOKEN') || '',
});

export default async function handler(req: Request) {
  const url = new URL(req.url);
  const path = url.pathname;

  const headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'POST, GET, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type',
  };

  if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers });

  try {
    // API Lấy danh sách cho Dashboard
    if (req.method === 'GET') {
      const data = await kv.lrange('pending_registrations', 0, -1);
      return new Response(JSON.stringify(data || []), { status: 200, headers });
    }

    if (req.method === 'POST') {
      const body = await req.json();
      // Hỗ trợ cả path-based (/login) và action-based ({action: "login"})
      const isRegister = path.endsWith('/register') || body.action === 'register';
      const isLogin = path.endsWith('/login') || body.action === 'login';

      // XỬ LÝ ĐĂNG KÝ
      if (isRegister) {
        const { fullName, email, password, machineId } = body;

        if (!email || !password) {
           return new Response(JSON.stringify({ Success: false, Message: "Thiếu Email hoặc Mật khẩu." }), { status: 200, headers });
        }

        // Kiểm tra trùng email (tùy chọn nhưng nên có)
        const allUsers = (await kv.lrange('pending_registrations', 0, -1)) as any[];
        if (allUsers.some(u => u.email === email)) {
            return new Response(JSON.stringify({ Success: false, Message: "Email này đã được đăng ký trước đó." }), { status: 200, headers });
        }

        const newUser = {
          id: `U${Date.now()}`,
          name: fullName || "User mới",
          email,
          password, 
          machineId: machineId || "Unknown",
          status: 'on_hold',
          licenseType: 'trial',
          company: 'Pending Approval',
          expirationDate: new Date(Date.now() + 7 * 86400000).toISOString().split('T')[0],
          lastLogin: new Date().toISOString()
        };

        await kv.lpush('pending_registrations', newUser);
        return new Response(JSON.stringify({ Success: true, Message: "Đăng ký thành công! Vui lòng chờ Admin kích hoạt." }), { status: 200, headers });
      }

      // XỬ LÝ ĐĂNG NHẬP
      if (isLogin) {
        const { email, password } = body;
        const allUsers = (await kv.lrange('pending_registrations', 0, -1)) as any[];
        const user = allUsers.find(u => u.email === email && u.password === password);

        if (!user) {
            return new Response(JSON.stringify({ Success: false, Message: "Email hoặc mật khẩu không chính xác." }), { status: 200, headers });
        }

        if (user.status !== 'active') {
            const statusMsg = user.status === 'on_hold' ? "chờ kích hoạt" : (user.status === 'blocked' ? "bị khóa" : "hết hạn");
            return new Response(JSON.stringify({ Success: false, Message: `Tài khoản của bạn đang ${statusMsg}.` }), { status: 200, headers });
        }

        return new Response(JSON.stringify({ 
          Success: true, 
          Message: "Đăng nhập thành công", 
          Token: `sk_${Math.random().toString(36).slice(2)}`,
          UserData: { name: user.name, expiry: user.expirationDate }
        }), { status: 200, headers });
      }
    }
  } catch (err: any) {
    return new Response(JSON.stringify({ Success: false, Message: "Lỗi Server: " + err.message }), { status: 200, headers });
  }

  return new Response(JSON.stringify({ Success: false, Message: "Yêu cầu không hợp lệ" }), { status: 404, headers });
}

