                      <code className="bg-slate-100 px-2 py-1 rounded text-xs font-mono">
                        {visiblePasswords[user.id] ? user.password : '••••••••'}
                      </code>
                      <button onClick={() => togglePass(user.id)} className="text-slate-400 hover:text-slate-600 p-1">
                        {visiblePasswords[user.id] ? <EyeOff className="w-3.5 h-3.5" /> : <Eye className="w-3.5 h-3.5" />}
                      </button>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <select 
                      value={user.status} 
                      onChange={e => onUpdateStatus(user.id, e.target.value as any)}
                      className={`text-[10px] font-bold px-3 py-1.5 rounded-full uppercase outline-none border-none cursor-pointer appearance-none text-center min-w-[90px] ${
                        user.status === 'active' ? 'bg-green-100 text-green-700' : 
                        user.status === 'on_hold' ? 'bg-amber-100 text-amber-700 animate-pulse' : 'bg-red-100 text-red-700'
                      }`}
                    >
                      <option value="active">Active</option>
                      <option value="on_hold">Pending</option>
                      <option value="blocked">Blocked</option>
                      <option value="expired">Expired</option>
                    </select>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-2">
                      <Clock className="w-3.5 h-3.5 text-slate-400" />
                      <input 
                        type="date" 
                        value={user.expirationDate}
                        onChange={(e) => onUpdateExpiration(user.id, e.target.value)}
                        className="text-xs border border-slate-200 rounded px-2 py-1 outline-none focus:ring-1 focus:ring-blue-500 bg-transparent text-slate-700 font-medium hover:bg-white transition-colors"
                      />
                    </div>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <button onClick={() => onDeleteUser(user.id)} className="p-2 text-slate-400 hover:text-red-500 rounded-lg hover:bg-red-50 transition-all">
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </td>
                </tr>
              ))}
              {filtered.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-6 py-12 text-center text-slate-400 italic">
                    Không tìm thấy dữ liệu phù hợp.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { UserManagement } from './components/UserManagement';
import { SessionMonitor } from './components/SessionMonitor';
import { AiAssistant } from './components/AiAssistant';
import { IntegrationGuide } from './components/IntegrationGuide';
import { LoginScreen } from './components/LoginScreen';
import { AppView, User, Session } from './types';
import { MOCK_USERS, MOCK_SESSIONS } from './constants';
import { Menu, Cloud, RefreshCw, Download } from 'lucide-react';

const App: React.FC = () => {
  // Khởi tạo Auth với kiểm tra lỗi
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => {
    try {
      return localStorage.getItem('app_auth_token') === 'true';
    } catch (e) {
      return false;
    }
  });

  // Khởi tạo View với giá trị mặc định an toàn
  const [currentView, setCurrentView] = useState<AppView>(() => {
    try {
      const saved = localStorage.getItem('app_current_view') as AppView;
      return Object.values(AppView).includes(saved) ? saved : AppView.DASHBOARD;
    } catch (e) {
      return AppView.DASHBOARD;
    }
  });

  // Khởi tạo Users với cơ chế fallback an toàn
  const [users, setUsers] = useState<User[]>(() => {
    try {
      const saved = localStorage.getItem('app_users_data');
      if (!saved) return MOCK_USERS;
      const parsed = JSON.parse(saved);
      return Array.isArray(parsed) ? parsed : MOCK_USERS;
    } catch (e) {
      console.error("Lỗi đọc dữ liệu người dùng:", e);
      return MOCK_USERS;
    }
  });

  // Khởi tạo Sessions với cơ chế fallback an toàn
  const [sessions, setSessions] = useState<Session[]>(() => {
    try {
      const saved = localStorage.getItem('app_sessions_data');
      if (!saved) return MOCK_SESSIONS;
      const parsed = JSON.parse(saved);
      return Array.isArray(parsed) ? parsed : MOCK_SESSIONS;
    } catch (e) {
      console.error("Lỗi đọc dữ liệu phiên làm việc:", e);
      return MOCK_SESSIONS;
    }
  });

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  const usersRef = useRef(users);
  useEffect(() => {
    usersRef.current = users;
  }, [users]);

  const syncFromCloud = useCallback(async (silent = false) => {
    if (!silent) setIsSyncing(true);
    try {
        const response = await fetch(`/api/register?t=${Date.now()}`, {
          headers: { 'Accept': 'application/json' }
        });

        if (!response.ok) throw new Error(`HTTP ${response.status}`);

        const contentType = response.headers.get("content-type");
        if (contentType && contentType.includes("application/json")) {
            const data = await response.json();
            if (Array.isArray(data)) {
                setUsers(prevUsers => {
                    const currentEmails = new Set(prevUsers.map(u => u.email));
                    const newOnes = data.filter(cloudUser => cloudUser && cloudUser.email && !currentEmails.has(cloudUser.email));
                    return newOnes.length > 0 ? [...newOnes, ...prevUsers] : prevUsers;
                });
            }
        }
    } catch (e) {
        if (!silent) console.error("Sync failed:", e);
    } finally {
        if (!silent) setIsSyncing(false);
    }
  }, []);

  useEffect(() => {
    if (!isAuthenticated) return;
    syncFromCloud(true);
    const interval = setInterval(() => syncFromCloud(true), 30000);
    return () => clearInterval(interval);
  }, [isAuthenticated, syncFromCloud]);

  // Lưu dữ liệu vào LocalStorage an toàn
  useEffect(() => {
    try {
      localStorage.setItem('app_users_data', JSON.stringify(users));
      localStorage.setItem('app_sessions_data', JSON.stringify(sessions));
      localStorage.setItem('app_current_view', currentView);
    } catch (e) {
      console.error("Lỗi lưu LocalStorage:", e);
    }
  }, [users, sessions, currentView]);

  const handleManualSync = () => syncFromCloud(false);

  const handleExportData = () => {
    try {
      const data = { users, sessions, exportDate: new Date().toISOString() };
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `revit_license_backup_${new Date().toISOString().split('T')[0]}.json`;
      a.click();
    } catch (e) {
      alert("Lỗi khi xuất dữ liệu");
    }
  };

  const handleLogin = () => {
    localStorage.setItem('app_auth_token', 'true');
    setIsAuthenticated(true);
  };

  const handleLogout = () => {
    localStorage.removeItem('app_auth_token');
    setIsAuthenticated(false);
  };

  const handleUpdateStatus = (id: string, newStatus: User['status']) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, status: newStatus } : u));
  };

  const handleUpdateExpiration = (id: string, newDate: string) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, expirationDate: newDate } : u));
  };

  const handleDeleteUser = (id: string) => {
    if(window.confirm("Xóa người dùng này?")) {
        setUsers(prev => prev.filter(u => u.id !== id));
    }
  };

  if (!isAuthenticated) return <LoginScreen onLogin={handleLogin} />;

  return (
    <div className="flex h-screen bg-slate-50 font-sans overflow-hidden">
      <Sidebar 
        currentView={currentView} 
        setCurrentView={setCurrentView} 
        isMobileOpen={isMobileMenuOpen}
        onCloseMobile={() => setIsMobileMenuOpen(false)}
        onLogout={handleLogout}
      />

      <main className="flex-1 flex flex-col h-full w-full relative overflow-hidden">
        <header className="flex-none px-4 py-4 md:px-8 border-b border-slate-200 bg-white shadow-sm flex justify-between items-center z-20">
          <div className="flex items-center gap-3">
             <button onClick={() => setIsMobileMenuOpen(true)} className="md:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                <Menu className="w-6 h-6" />
             </button>
             <div>
                <h1 className="text-lg md:text-xl font-bold text-slate-800">{currentView}</h1>
                <div className="text-[10px] text-slate-500 flex items-center gap-1">
                    <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></span>
                    Hệ thống: Sẵn sàng
                </div>
             </div>
          </div>

          <div className="flex items-center gap-2 md:gap-4">
            <button 
                onClick={handleManualSync}
                disabled={isSyncing}
                className="flex items-center gap-2 px-3 py-1.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors text-xs font-semibold shadow-sm disabled:opacity-50"
            >
                {isSyncing ? <RefreshCw className="w-3.5 h-3.5 animate-spin" /> : <Cloud className="w-3.5 h-3.5" />}
                Sync Cloud
            </button>
            <div className="h-6 w-px bg-slate-200"></div>
            <button onClick={handleExportData} className="p-1.5 text-slate-400 hover:text-blue-600 hover:bg-slate-50 rounded-lg transition-colors" title="Backup">
                <Download className="w-4 h-4" />
            </button>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-8">
            <div className="max-w-7xl mx-auto">
                {currentView === AppView.DASHBOARD && <Dashboard users={users} sessions={sessions} onUpdateStatus={handleUpdateStatus} />}
                {currentView === AppView.USERS && (
                  <UserManagement 
                    users={users} 
                    onAddUser={(u)=>setUsers([u, ...users])} 
                    onEditUser={(u)=>setUsers(users.map(x=>x.id===u.id?u:x))} 
                    onUpdateStatus={handleUpdateStatus} 
                    onUpdateExpiration={handleUpdateExpiration}
                    onDeleteUser={handleDeleteUser} 
                  />
                )}
                {currentView === AppView.SESSIONS && <SessionMonitor sessions={sessions} users={users} onKillSession={(id)=>setSessions(sessions.filter(s=>s.id!==id))} onAddSession={(s)=>setSessions([s, ...sessions])} />}
                {currentView === AppView.AI_INSIGHTS && <AiAssistant users={users} sessions={sessions} />}
                {currentView === AppView.INTEGRATION && <IntegrationGuide />}
            </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { User, Session } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, LineChart, Line } from 'recharts';
import { Users, Wifi, AlertTriangle, ShieldCheck, Clock, Activity, CheckCircle2, XCircle, RefreshCw, Database, Cloud, BellRing } from 'lucide-react';

interface DashboardProps {
  users: User[];
  sessions: Session[];
  onUpdateStatus: (id: string, status: User['status']) => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ users = [], sessions = [], onUpdateStatus }) => {
  // Đảm bảo dữ liệu là mảng trước khi xử lý
  const safeUsers = Array.isArray(users) ? users : [];
  const safeSessions = Array.isArray(sessions) ? sessions : [];

  const activeUsers = safeUsers.filter(u => u.status === 'active').length;
  const expiredUsers = safeUsers.filter(u => u.status === 'expired').length;
  const onHoldUsers = safeUsers.filter(u => u.status === 'on_hold').length;
  const totalSessions = safeSessions.length;

  // Dữ liệu cho biểu đồ xu hướng
  const registrationTrend = safeUsers.reduce((acc: any[], user) => {
    if (!user.lastLogin) return acc;
    const date = new Date(user.lastLogin).toLocaleDateString('vi-VN', { month: 'short', day: 'numeric' });
    const existing = acc.find(item => item.name === date);
    if (existing) existing.count += 1;
    else acc.push({ name: date, count: 1 });
    return acc;
  }, []).sort((a, b) => new Date(a.name).getTime() - new Date(b.name).getTime()).slice(-7);

  const licenseTypeData = [
    { name: 'Subscription', value: safeUsers.filter(u => u.licenseType === 'subscription').length },
    { name: 'Perpetual', value: safeUsers.filter(u => u.licenseType === 'perpetual').length },
    { name: 'Trial', value: safeUsers.filter(u => u.licenseType === 'trial').length },
  ].filter(d => d.value > 0);

  const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444'];

  const StatCard = ({ title, value, subValue, icon: Icon, color, bg, highlight }: any) => (
    <div className={`bg-white p-6 rounded-2xl shadow-sm border ${highlight ? 'border-blue-200 ring-2 ring-blue-50' : 'border-slate-100'} flex items-start justify-between hover:shadow-md transition-all hover:-translate-y-1`}>
      <div>
        <p className="text-sm font-medium text-slate-500 mb-1">{title}</p>
        <div className="flex items-baseline gap-2">
            <h3 className="text-3xl font-bold text-slate-800">{value}</h3>
            {subValue && <span className={`text-xs font-medium ${highlight ? 'text-blue-600 animate-pulse' : 'text-slate-400'}`}>{subValue}</span>}
        </div>
      </div>
      <div className={`p-3 rounded-xl ${bg}`}>
        <Icon className={`w-6 h-6 ${color}`} />
      </div>
    </div>
  );

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
         <div>
            <h2 className="text-2xl font-bold text-slate-800">Bảng điều khiển trung tâm</h2>
            <p className="text-sm text-slate-500">Giám sát hệ thống license thời gian thực</p>
         </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="Yêu cầu mới" value={onHoldUsers} subValue="Cần kích hoạt" icon={BellRing} color="text-blue-600" bg="bg-blue-50" highlight={onHoldUsers > 0} />
        <StatCard title="Đang Online" value={totalSessions} subValue="Phiên Revit" icon={Wifi} color="text-green-600" bg="bg-green-50" />
        <StatCard title="Đã hết hạn" value={expiredUsers} subValue="Cần gia hạn" icon={AlertTriangle} color="text-amber-600" bg="bg-amber-50" />
        <StatCard title="User hoạt động" value={activeUsers} subValue="Tổng License" icon={ShieldCheck} color="text-purple-600" bg="bg-purple-50" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col h-[400px]">
            <h3 className="font-bold text-slate-800 flex items-center gap-2 mb-6">
                <Activity className="w-5 h-5 text-indigo-500" /> Xu hướng đăng ký
            </h3>
            <div className="flex-1">
                <ResponsiveContainer width="100%" height="100%">
                    <LineChart data={registrationTrend.length ? registrationTrend : [{name: 'Không có dữ liệu', count: 0}]}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                        <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 12, fill: '#64748b'}} />
                        <YAxis axisLine={false} tickLine={false} tick={{fontSize: 12, fill: '#64748b'}} />
                        <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} />
                        <Line type="monotone" dataKey="count" stroke="#6366f1" strokeWidth={3} dot={{ r: 4, fill: '#6366f1' }} activeDot={{ r: 6 }} />
                    </LineChart>
                </ResponsiveContainer>
            </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col h-[400px]">
            <h3 className="font-bold text-slate-800 mb-6">Phân loại License</h3>
            <div className="flex-1">
                <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                        <Pie data={licenseTypeData.length ? licenseTypeData : [{name: 'Trống', value: 1}]} innerRadius={60} outerRadius={80} paddingAngle={8} dataKey="value">
                            {licenseTypeData.map((_, index) => (
                                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                            ))}
                            {licenseTypeData.length === 0 && <Cell fill="#e2e8f0" />}
                        </Pie>
                        <Tooltip />
                    </PieChart>
                </ResponsiveContainer>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { User } from '../types';
import { Search, Trash2, Eye, EyeOff, Clock, Shield, Building2 } from 'lucide-react';

interface UserManagementProps {
  users: User[];
  onAddUser: (user: User) => void;
  onEditUser: (user: User) => void;
  onUpdateStatus: (id: string, status: User['status']) => void;
  onUpdateExpiration: (id: string, date: string) => void;
  onDeleteUser: (id: string) => void;
}

export const UserManagement: React.FC<UserManagementProps> = ({ 
  users = [], 
  onUpdateStatus, 
  onUpdateExpiration,
  onDeleteUser 
}) => {
  const [search, setSearch] = useState('');
  const [visiblePasswords, setVisiblePasswords] = useState<Record<string, boolean>>({});

  const togglePass = (id: string) => setVisiblePasswords(prev => ({...prev, [id]: !prev[id]}));

  // Lọc an toàn: Kiểm tra u tồn tại và các trường là string trước khi dùng toLowerCase
  const filtered = (Array.isArray(users) ? users : []).filter(u => {
    if (!u) return false;
    const s = search.toLowerCase();
    const name = (u.name || '').toLowerCase();
    const email = (u.email || '').toLowerCase();
    const company = (u.company || '').toLowerCase();
    const machineId = (u.machineId || '').toLowerCase();

    return name.includes(s) || email.includes(s) || company.includes(s) || machineId.includes(s);
  });

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
            <h2 className="text-2xl font-bold text-slate-800">Quản lý License & Yêu cầu</h2>
            <p className="text-sm text-slate-500">Kích hoạt và quản lý thời hạn người dùng</p>
        </div>
        <div className="relative w-full md:w-80">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
          <input 
            className="w-full pl-10 pr-4 py-2.5 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500 shadow-sm transition-all"
            placeholder="Tìm theo tên, email, máy, công ty..."
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50/50 border-b border-slate-100 text-slate-500 font-semibold">
              <tr>
                <th className="px-6 py-4">Thông tin</th>
                <th className="px-6 py-4">Công ty</th>
                <th className="px-6 py-4">Mật khẩu</th>
                <th className="px-6 py-4">Trạng thái</th>
                <th className="px-6 py-4">Hạn dùng</th>
                <th className="px-6 py-4 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filtered.map(user => {
                if (!user) return null;
                return (
                  <tr key={user.id} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="px-6 py-4">
