                      <div className="text-xs text-slate-500">{user.email || 'No email'}</div>
                      <div className="text-[10px] text-blue-500 mt-1 font-mono flex items-center gap-1">
                        <Shield className="w-2.5 h-2.5" />
                        {user.machineId || 'Chưa nhận diện máy'}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2 text-slate-600">
                        <Building2 className="w-3.5 h-3.5 text-slate-400" />
                        <span className="truncate max-w-[120px]">{user.company || 'Cá nhân'}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2">
                        <code className="bg-slate-100 px-2 py-1 rounded text-[11px] font-mono min-w-[70px] inline-block text-center">
                          {visiblePasswords[user.id] ? (user.password || 'N/A') : '••••••••'}
