import { createClient } from '@vercel/kv';

export const config = {
  runtime: 'edge',
};

const getEnv = (key: string) => {
  return process.env[`KV_REST_API_URL`] || process.env[`REST_API_URL`] || '';
};

const getToken = (key: string) => {
  return process.env[`KV_REST_API_TOKEN`] || process.env[`REST_API_TOKEN`] || '';
};

export default async function handler(req: Request) {
  const url = new URL(req.url);
  const headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'POST, GET, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type',
    'Cache-Control': 'no-store, no-cache, must-revalidate, proxy-revalidate',
  };

  if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers });

  const kvUrl = getEnv('KV_REST_API_URL');
  const kvToken = getToken('KV_REST_API_TOKEN');

  if (!kvUrl || !kvToken) {
    return new Response(JSON.stringify({ Success: false, Message: "Lỗi cấu hình KV" }), { status: 500, headers });
  }

  const kv = createClient({ url: kvUrl, token: kvToken });
  const LIST_KEY = 'pending_registrations';

  try {
    if (req.method === 'GET') {
      const data = await kv.lrange(LIST_KEY, 0, -1);
      return new Response(JSON.stringify(data || []), { status: 200, headers });
    }

    if (req.method === 'POST') {
      const body = await req.json();
      const action = body.action || (url.pathname.includes('/register') ? 'register' : '');

      // 1. ĐĂNG KÝ MỚI
      if (action === 'register') {
        const { fullName, email, password, machineId, company } = body;
        if (!email || !password) {
           return new Response(JSON.stringify({ Success: false, Message: "Thiếu thông tin." }), { status: 200, headers });
        }

        const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
        if (allUsers.some(u => u.email === email)) {
            return new Response(JSON.stringify({ Success: false, Message: "Email đã tồn tại." }), { status: 200, headers });
        }

        const newUser = {
          id: `U${Date.now()}`,
          name: fullName || "User mới",
          email,
          password, 
          machineId: machineId || "Unknown",
          status: 'on_hold',
          licenseType: 'trial',
          company: company || 'Cá nhân',
          expirationDate: new Date(Date.now() + 30 * 86400000).toISOString().split('T')[0],
          lastLogin: new Date().toISOString()
        };

        await kv.lpush(LIST_KEY, newUser);
        return new Response(JSON.stringify({ Success: true, Message: "Đăng ký thành công!" }), { status: 200, headers });
      }

      // 2. CẬP NHẬT THÔNG TIN (Hạn dùng, Trạng thái...)
      if (action === 'update_user') {
        const { id, data } = body;
        const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
        const index = allUsers.findIndex(u => u.id === id);

        if (index !== -1) {
          const updatedUser = { ...allUsers[index], ...data };
          await kv.lset(LIST_KEY, index, updatedUser);
          return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
        }
        return new Response(JSON.stringify({ Success: false, Message: "Không tìm thấy user" }), { status: 404, headers });
      }

      // 3. XÓA NGƯỜI DÙNG VĨNH VIỄN
      if (action === 'delete_user') {
        const { id } = body;
        const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
        const userToDelete = allUsers.find(u => u.id === id);

        if (userToDelete) {
          // LREM trong KV cần giá trị chính xác để xóa
          await kv.lrem(LIST_KEY, 1, userToDelete);
          return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
        }
        return new Response(JSON.stringify({ Success: false, Message: "Không tìm thấy user để xóa" }), { status: 404, headers });
      }

      // 4. LOGIN
      if (action === 'login') {
        const { email, password } = body;
        const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
        const user = allUsers.find(u => u.email === email && u.password === password);
        if (!user || user.status !== 'active') {
          return new Response(JSON.stringify({ Success: false, Message: "Tài khoản không hợp lệ hoặc chưa kích hoạt." }), { status: 200, headers });
        }
        return new Response(JSON.stringify({ Success: true, Token: "ok" }), { status: 200, headers });
      }
    }
  } catch (err: any) {
    return new Response(JSON.stringify({ Success: false, Message: err.message }), { status: 500, headers });
  }

  return new Response(JSON.stringify({ Success: false, Message: "Hành động không hợp lệ" }), { status: 404, headers });
}

