      const res = await fetch('/api/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'delete_user', id })
      });
      if (res.ok) {
        lastSyncHashRef.current = ""; // Reset hash to fetch clean state
        console.log("Deleted from cloud successfully");
      }
    } catch (e) {
      alert("Lỗi khi xóa trên Cloud. Vui lòng thử lại.");
    }
  };

  const handleLogin = () => {
    localStorage.setItem('app_auth_token', 'true');
    setIsAuthenticated(true);
