import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { UserManagement } from './components/UserManagement';
import { SessionMonitor } from './components/SessionMonitor';
import { AiAssistant } from './components/AiAssistant';
import { IntegrationGuide } from './components/IntegrationGuide';
import { LoginScreen } from './components/LoginScreen';
import { AppView, User, Session } from './types';
import { MOCK_USERS, MOCK_SESSIONS } from './constants';
import { Menu, RefreshCw, Download as LucideDownload } from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => {
    return localStorage.getItem('app_auth_token') === 'true';
  });

  const [currentView, setCurrentView] = useState<AppView>(() => {
    const saved = localStorage.getItem('app_current_view') as AppView;
    return Object.values(AppView).includes(saved) ? saved : AppView.DASHBOARD;
  });

  const [users, setUsers] = useState<User[]>(() => {
    const saved = localStorage.getItem('app_users_data');
    if (!saved) return [];
    try {
      const parsed = JSON.parse(saved);
      return Array.isArray(parsed) ? parsed : [];
    } catch { return []; }
  });

  const [sessions, setSessions] = useState<Session[]>(() => {
    const saved = localStorage.getItem('app_sessions_data');
    if (!saved) return [];
    try {
      const parsed = JSON.parse(saved);
      return Array.isArray(parsed) ? parsed : [];
    } catch { return []; }
  });

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  const lastSyncHashRef = useRef<string>("");

  const syncFromCloud = useCallback(async (silent = false) => {
    if (!silent) setIsSyncing(true);
    try {
      const response = await fetch(`/api/register?t=${Date.now()}`);
      if (!response.ok) throw new Error("Fetch failed");

      const cloudData = await response.json();
      if (Array.isArray(cloudData)) {
        const currentHash = JSON.stringify(cloudData);

        if (currentHash !== lastSyncHashRef.current) {
          lastSyncHashRef.current = currentHash;
          setUsers(prev => {
            const cloudIds = new Set(cloudData.map(u => u.id));
            const localOnly = prev.filter(u => !cloudIds.has(u.id));
            return [...cloudData, ...localOnly];
          });
          if (!silent) console.log("Cloud data synced.");
        }
      }
    } catch (e) {
      if (!silent) console.error("Sync error:", e);
    } finally {
      if (!silent) setIsSyncing(false);
    }
  }, []);

  useEffect(() => {
    if (!isAuthenticated) return;
    syncFromCloud(true);
    const interval = setInterval(() => syncFromCloud(true), 30000);
    return () => clearInterval(interval);
  }, [isAuthenticated, syncFromCloud]);

  useEffect(() => {
    localStorage.setItem('app_users_data', JSON.stringify(users));
    localStorage.setItem('app_sessions_data', JSON.stringify(sessions));
    localStorage.setItem('app_current_view', currentView);
  }, [users, sessions, currentView]);

  const handleUpdateStatus = async (id: string, newStatus: User['status']) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, status: newStatus } : u));
    if (id.startsWith('U') && !id.startsWith('U00')) {
      try {
        await fetch('/api/register', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ action: 'update_user', id, data: { status: newStatus } })
        });
      } catch (e) { console.error("Cloud update failed"); }
    }
  };

  const handleUpdateExpiration = async (id: string, newDate: string) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, expirationDate: newDate } : u));
    if (id.startsWith('U') && !id.startsWith('U00')) {
      try {
        await fetch('/api/register', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ action: 'update_user', id, data: { expirationDate: newDate } })
        });
      } catch (e) { console.error("Cloud update failed"); }
    }
  };

  const handleDeleteUser = async (id: string) => {
    if (!window.confirm("Xóa vĩnh viễn người dùng này?")) return;
    setUsers(prev => prev.filter(u => u.id !== id));
    if (id.startsWith('U') && !id.startsWith('U00')) {
      try {
        await fetch('/api/register', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ action: 'delete_user', id })
        });
      } catch (e) { console.error("Cloud delete failed"); }
    }
  };

  const handleLogin = () => {
    localStorage.setItem('app_auth_token', 'true');
    setIsAuthenticated(true);
  };

  const handleLogout = () => {
    localStorage.removeItem('app_auth_token');
    localStorage.removeItem('app_users_data'); // Clear local data on logout for a fresh start
    localStorage.removeItem('app_sessions_data');
    setIsAuthenticated(false);
  };

  if (!isAuthenticated) return <LoginScreen onLogin={handleLogin} />;

  return (
    <div className="flex h-screen bg-slate-50 font-sans overflow-hidden">
      <Sidebar 
        currentView={currentView} 
        setCurrentView={setCurrentView} 
        isMobileOpen={isMobileMenuOpen}
        onCloseMobile={() => setIsMobileMenuOpen(false)}
        onLogout={handleLogout}
      />

      <main className="flex-1 flex flex-col h-full w-full relative overflow-hidden">
        <header className="flex-none px-4 py-4 md:px-8 border-b border-slate-200 bg-white shadow-sm flex justify-between items-center z-20">
          <div className="flex items-center gap-3">
             <button onClick={() => setIsMobileMenuOpen(true)} className="md:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                <Menu className="w-6 h-6" />
             </button>
             <div>
                <h1 className="text-lg md:text-xl font-bold text-slate-800">{currentView}</h1>
                <div className="text-[10px] text-slate-500 flex items-center gap-1">
                    <span className={`w-1.5 h-1.5 rounded-full ${isSyncing ? 'bg-blue-500 animate-spin' : 'bg-green-500 animate-pulse'}`}></span>
                    Cloud Sync: {isSyncing ? 'Đang kiểm tra...' : 'Sẵn sàng'}
                </div>
             </div>
          </div>

          <div className="flex items-center gap-2 md:gap-4">
            <button 
                onClick={() => syncFromCloud(false)}
                disabled={isSyncing}
                className="flex items-center gap-2 px-3 py-1.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors text-xs font-semibold shadow-sm disabled:opacity-50"
            >
                {isSyncing ? (
                  <RefreshCw className="w-3.5 h-3.5 animate-spin" />
                ) : (
                  <LucideDownload className="w-3.5 h-3.5" />
                )}
                Làm mới dữ liệu
            </button>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-8">
            <div className="max-w-7xl mx-auto">
                {currentView === AppView.DASHBOARD && <Dashboard users={users} sessions={sessions} onUpdateStatus={handleUpdateStatus} />}
                {currentView === AppView.USERS && (
                  <UserManagement 
                    users={users} 
                    onAddUser={(u)=>setUsers([u, ...users])} 
                    onEditUser={(u)=>setUsers(users.map(x=>x.id===u.id?u:x))} 
                    onUpdateStatus={handleUpdateStatus} 
                    onUpdateExpiration={handleUpdateExpiration}
                    onDeleteUser={handleDeleteUser} 
                  />
                )}
                {currentView === AppView.SESSIONS && (
                  <SessionMonitor 
                    sessions={sessions} 
                    users={users} 
                    onKillSession={(id)=>setSessions(sessions.filter(s=>s.id!==id))} 
                    onAddSession={(s)=>setSessions([s, ...sessions])} 
                  />
                )}
                {currentView === AppView.AI_INSIGHTS && <AiAssistant users={users} sessions={sessions} />}
                {currentView === AppView.INTEGRATION && <IntegrationGuide />}
            </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { User } from '../types';
import { Search, Trash2, Eye, EyeOff, Clock, Shield, Building2, UserPlus, X, Save, Edit3, Award } from 'lucide-react';

interface UserManagementProps {
  users: User[];
  onAddUser: (user: User) => void;
  onEditUser: (user: User) => void;
  onUpdateStatus: (id: string, status: User['status']) => void;
  onUpdateExpiration: (id: string, date: string) => void;
  onDeleteUser: (id: string) => void;
}

const INITIAL_FORM_STATE: Partial<User> = {
  name: '',
  email: '',
  password: '',
  company: '',
  licenseType: 'subscription',
  status: 'active',
  expirationDate: new Date(Date.now() + 365 * 86400000).toISOString().split('T')[0],
};

export const UserManagement: React.FC<UserManagementProps> = ({ 
  users = [], 
  onAddUser,
  onEditUser,
  onUpdateStatus, 
  onUpdateExpiration,
  onDeleteUser 
}) => {
  const [search, setSearch] = useState('');
  const [visiblePasswords, setVisiblePasswords] = useState<Record<string, boolean>>({});
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);

  // Form state với Persistence cho bản nháp
  const [formData, setFormData] = useState<Partial<User>>(() => {
    const saved = localStorage.getItem('user_form_draft');
    return saved ? JSON.parse(saved) : INITIAL_FORM_STATE;
  });

  // Lưu bản nháp mỗi khi form thay đổi
  useEffect(() => {
    if (!editingUser) {
      localStorage.setItem('user_form_draft', JSON.stringify(formData));
    }
  }, [formData, editingUser]);

  const togglePass = (id: string) => setVisiblePasswords(prev => ({...prev, [id]: !prev[id]}));

  const handleOpenAdd = () => {
    setEditingUser(null);
    setFormData(INITIAL_FORM_STATE);
    setIsModalOpen(true);
  };

  const handleOpenEdit = (user: User) => {
    setEditingUser(user);
    setFormData(user);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setFormData(INITIAL_FORM_STATE);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingUser) {
      onEditUser({ ...editingUser, ...formData } as User);
    } else {
      const newUser: User = {
        ...formData,
        id: `LOC-${Date.now()}`,
        lastLogin: new Date().toISOString(),
      } as User;
      onAddUser(newUser);
      localStorage.removeItem('user_form_draft');
      setFormData(INITIAL_FORM_STATE);
    }
    setIsModalOpen(false);
  };

  const filtered = (Array.isArray(users) ? users : []).filter(u => {
    if (!u) return false;
    const s = search.toLowerCase();
    return (u.name || '').toLowerCase().includes(s) || 
           (u.email || '').toLowerCase().includes(s) || 
           (u.company || '').toLowerCase().includes(s);
  });

  const getLicenseBadgeStyle = (type: string) => {
    switch (type) {
      case 'subscription': return 'bg-blue-100 text-blue-700 border-blue-200';
      case 'perpetual': return 'bg-purple-100 text-purple-700 border-purple-200';
      case 'trial': return 'bg-slate-100 text-slate-700 border-slate-200';
      default: return 'bg-gray-100 text-gray-700 border-gray-200';
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
            <h2 className="text-2xl font-bold text-slate-800">Quản lý License & Yêu cầu</h2>
            <p className="text-sm text-slate-500">Kích hoạt và quản lý thời hạn người dùng</p>
        </div>
        <div className="flex flex-col sm:flex-row items-center gap-3 w-full md:w-auto">
          <div className="relative w-full sm:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
            <input 
              className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500 shadow-sm transition-all"
              placeholder="Tìm kiếm..."
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
          </div>
          <button 
            onClick={handleOpenAdd}
            className="w-full sm:w-auto flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-xl text-sm font-bold shadow-sm shadow-blue-100 transition-all active:scale-95"
          >
            <UserPlus className="w-4 h-4" /> Thêm người dùng
          </button>
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50/50 border-b border-slate-100 text-slate-500 font-semibold">
              <tr>
                <th className="px-6 py-4">Thông tin</th>
                <th className="px-6 py-4">Công ty</th>
                <th className="px-6 py-4">Mật khẩu</th>
                <th className="px-6 py-4">Loại License</th>
                <th className="px-6 py-4">Trạng thái</th>
                <th className="px-6 py-4">Hạn dùng</th>
                <th className="px-6 py-4 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filtered.length > 0 ? filtered.map(user => (
                <tr key={user.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-6 py-4">
                    <div className="font-bold text-slate-900">{user.name}</div>
                    <div className="text-xs text-slate-500">{user.email}</div>
                    <div className="text-[10px] text-blue-500 mt-1 font-mono flex items-center gap-1">
                      <Shield className="w-2.5 h-2.5" /> {user.machineId || 'Local User'}
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-2 text-slate-600">
                      <Building2 className="w-3.5 h-3.5 text-slate-400" />
                      <span className="truncate max-w-[120px]">{user.company}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-2">
                      <code className="bg-slate-100 px-2 py-1 rounded text-[11px] font-mono min-w-[70px] inline-block text-center">
                        {visiblePasswords[user.id] ? (user.password || '••••••') : '••••••••'}
                      </code>
                      <button onClick={() => togglePass(user.id)} className="text-slate-400 hover:text-slate-600 p-1">
                        {visiblePasswords[user.id] ? <EyeOff className="w-3.5 h-3.5" /> : <Eye className="w-3.5 h-3.5" />}
                      </button>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-bold uppercase border ${getLicenseBadgeStyle(user.licenseType)}`}>
                      <Award className="w-3 h-3" />
                      {user.licenseType}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <select 
                      value={user.status} 
                      onChange={e => onUpdateStatus(user.id, e.target.value as any)}
                      className={`text-[10px] font-bold px-3 py-1.5 rounded-full uppercase outline-none border-none cursor-pointer text-center min-w-[100px] shadow-sm ${
                        user.status === 'active' ? 'bg-green-100 text-green-700' : 
                        user.status === 'on_hold' ? 'bg-amber-100 text-amber-700' : 'bg-red-100 text-red-700'
                      }`}
                    >
                      <option value="active">Active</option>
                      <option value="on_hold">Pending</option>
                      <option value="blocked">Blocked</option>
                      <option value="expired">Expired</option>
                    </select>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-2 text-slate-600">
                      <Clock className="w-3.5 h-3.5 text-slate-400" />
                      <input 
                        type="date" 
                        value={user.expirationDate}
                        onChange={(e) => onUpdateExpiration(user.id, e.target.value)}
                        className="text-xs border border-slate-200 rounded-lg px-2 py-1 focus:ring-2 focus:ring-blue-100 bg-slate-50 outline-none"
                      />
                    </div>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end items-center gap-1">
                      <button onClick={() => handleOpenEdit(user)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all" title="Chỉnh sửa">
                        <Edit3 className="w-4 h-4" />
                      </button>
                      <button onClick={() => onDeleteUser(user.id)} className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all" title="Xóa">
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              )) : (
                <tr>
                  <td colSpan={7} className="px-6 py-12 text-center text-slate-400 italic">
                    Chưa có người dùng nào. Nhấn "Thêm người dùng" để bắt đầu.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modal Add/Edit */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in">
          <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-slate-800">
                {editingUser ? 'Chỉnh sửa người dùng' : 'Thêm người dùng mới'}
              </h3>
              <button onClick={handleCloseModal} className="p-2 hover:bg-slate-100 rounded-full text-slate-400">
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Họ và tên</label>
                <input 
                  required
                  className="w-full px-4 py-2.5 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Email</label>
                  <input 
                    type="email" required
                    className="w-full px-4 py-2.5 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
                    value={formData.email}
                    onChange={e => setFormData({...formData, email: e.target.value})}
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Mật khẩu</label>
                  <input 
                    type="text" required
