using System.Net.Http;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;

namespace DSH_RevitAPI.Services
{
    public class AuthService
    {
        // Địa chỉ máy chủ quản lý
        private readonly string _apiUrl = "${currentUrl}/api/register";

        public async Task<bool> RegisterAsync(string name, string email, string pass, string company)
        {
            using (var client = new HttpClient())
            {
                var payload = new { 
                    action = "register", 
                    fullName = name, 
                    email = email, 
                    password = pass, 
                    company = company,
                    machineId = Environment.MachineName 
                };

                try {
                    var json = JsonConvert.SerializeObject(payload);
                    var content = new StringContent(json, Encoding.UTF8, "application/json");
                    var response = await client.PostAsync(_apiUrl, content);

                    // Trả về true nếu máy chủ phản hồi OK (200)
                    return response.IsSuccessStatusCode;
                }
                catch (Exception ex) {
                    System.Diagnostics.Debug.WriteLine("API Error: " + ex.Message);
                    return false; 
                }
            }
        }
    }
}`
