        <p className="text-sm font-medium text-slate-500 mb-1 group-hover:text-blue-600 transition-colors">{title}</p>
        <div className="flex items-baseline gap-2">
            <h3 className="text-3xl font-bold text-slate-800">{value}</h3>
            {subValue && <span className={`text-xs font-medium ${highlight ? 'text-blue-600 animate-pulse' : 'text-slate-400'}`}>{subValue}</span>}
        </div>
      </div>
      <div className={`p-3 rounded-xl transition-colors ${bg} group-hover:bg-opacity-80`}>
        <Icon className={`w-6 h-6 ${color}`} />
      </div>
    </button>
  );

  const renderModalContent = () => {
    switch (activeModal) {
      case 'new':
        return (
          <div className="space-y-4">
            <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
              <BellRing className="w-5 h-5 text-blue-600" /> Danh sách chờ duyệt ({onHoldUsers.length})
            </h3>
            <div className="max-h-[60vh] overflow-y-auto pr-2 space-y-3">
              {onHoldUsers.length > 0 ? onHoldUsers.map(u => (
                <div key={u.id} className="p-4 bg-slate-50 rounded-xl border border-slate-100 flex items-center justify-between group">
                  <div>
                    <div className="font-bold text-slate-900">{u.name}</div>
                    <div className="text-xs text-slate-500">{u.email} • {u.company}</div>
                  </div>
                  <div className="flex items-center gap-2">
                    <select 
                      value={u.licenseType} 
                      onChange={e => onUpdateLicenseType(u.id, e.target.value as any)}
                      className="text-[10px] font-bold px-2 py-1 bg-white border border-slate-200 rounded-lg outline-none"
                    >
                      <option value="subscription">SUBSCRIPTION</option>
                      <option value="perpetual">PERPETUAL</option>
                      <option value="trial">TRIAL</option>
                    </select>
                    <button 
                      onClick={() => onUpdateStatus(u.id, 'active')}
                      className="flex items-center gap-1 px-3 py-1.5 bg-blue-600 text-white text-xs font-bold rounded-lg hover:bg-blue-700 transition-colors shadow-sm"
                    >
                      <UserCheck className="w-3.5 h-3.5" /> Duyệt
                    </button>
                  </div>
                </div>
              )) : <p className="text-center py-8 text-slate-400 italic">Không có yêu cầu nào mới.</p>}
            </div>
          </div>
        );
      case 'online':
        return (/* Online sessions logic... */ null);
      case 'active':
        return (
          <div className="space-y-4">
            <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
              <ShieldCheck className="w-5 h-5 text-purple-600" /> Người dùng đang hoạt động ({activeUsers.length})
            </h3>
            <div className="max-h-[60vh] overflow-y-auto pr-2 space-y-3">
              {activeUsers.map(u => (
                <div key={u.id} className="p-3 bg-white border border-slate-100 rounded-xl flex items-center justify-between shadow-sm">
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-xs font-bold text-slate-500">
                      {u.name.charAt(0)}
                    </div>
                    <div>
                      <div className="text-sm font-bold text-slate-800">{u.name}</div>
                      <div className="text-[10px] text-slate-500">{u.company}</div>
                    </div>
                  </div>
                  <select 
                    value={u.licenseType} 
                    onChange={e => onUpdateLicenseType(u.id, e.target.value as any)}
                    className={`text-[9px] font-bold px-2 py-1 rounded-full uppercase outline-none border-none cursor-pointer transition-colors ${
                      u.licenseType === 'subscription' ? 'bg-blue-100 text-blue-700' : 
                      u.licenseType === 'perpetual' ? 'bg-purple-100 text-purple-700' : 'bg-slate-100 text-slate-700'
                    }`}
                  >
                    <option value="subscription">Subscription</option>
                    <option value="perpetual">Perpetual</option>
                    <option value="trial">Trial</option>
                  </select>
                </div>
              ))}
            </div>
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="Yêu cầu mới" value={onHoldUsers.length} subValue="Cần kích hoạt" icon={BellRing} color="text-blue-600" bg="bg-blue-50" highlight={onHoldUsers.length > 0} onClick={() => setActiveModal('new')} />
        <StatCard title="Đang Online" value={onlineSessions.length} subValue="Phiên Revit" icon={Wifi} color="text-green-600" bg="bg-green-50" onClick={() => setActiveModal('online')} />
        <StatCard title="Đã hết hạn" value={expiredUsers.length} subValue="Cần gia hạn" icon={AlertTriangle} color="text-amber-600" bg="bg-amber-50" onClick={() => setActiveModal('expired')} />
        <StatCard title="User hoạt động" value={activeUsers.length} subValue="Tổng License" icon={ShieldCheck} color="text-purple-600" bg="bg-purple-50" onClick={() => setActiveModal('active')} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col h-[400px]">
            <h3 className="font-bold text-slate-800 flex items-center gap-2 mb-6"><Activity className="w-5 h-5 text-indigo-500" /> Xu hướng đăng ký</h3>
            <div className="flex-1">
                <ResponsiveContainer width="100%" height="100%">
                    <LineChart data={registrationTrend.length ? registrationTrend : [{name: 'Không có dữ liệu', count: 0}]}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                        <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 12, fill: '#64748b'}} />
                        <YAxis axisLine={false} tickLine={false} tick={{fontSize: 12, fill: '#64748b'}} />
                        <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} />
                        <Line type="monotone" dataKey="count" stroke="#6366f1" strokeWidth={3} dot={{ r: 4, fill: '#6366f1' }} activeDot={{ r: 6 }} />
                    </LineChart>
                </ResponsiveContainer>
            </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col h-[400px]">
            <h3 className="font-bold text-slate-800 mb-6">Phân loại License</h3>
            <div className="flex-1">
                <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                        <Pie data={licenseTypeData.length ? licenseTypeData : [{name: 'Trống', value: 1}]} innerRadius={60} outerRadius={80} paddingAngle={8} dataKey="value">
