        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User } from '../types';
import { Search, Trash2, Eye, EyeOff, Clock, Shield, Building2, UserPlus, X, Save, Edit3 } from 'lucide-react';

interface UserManagementProps {
  users: User[];
  onAddUser: (user: User) => void;
  onEditUser: (user: User) => void;
  onUpdateStatus: (id: string, status: User['status']) => void;
  onUpdateLicenseType: (id: string, type: User['licenseType']) => void;
  onUpdateExpiration: (id: string, date: string) => void;
  onDeleteUser: (id: string) => void;
}

const INITIAL_FORM_STATE: Partial<User> = {
  name: '',
  email: '',
  password: '',
  company: '',
  licenseType: 'subscription',
  status: 'active',
  expirationDate: new Date(Date.now() + 365 * 86400000).toISOString().split('T')[0],
};

export const UserManagement: React.FC<UserManagementProps> = ({ 
  users = [], 
  onAddUser,
  onEditUser,
  onUpdateStatus, 
  onUpdateLicenseType,
  onUpdateExpiration,
  onDeleteUser 
}) => {
  const [search, setSearch] = useState('');
  const [visiblePasswords, setVisiblePasswords] = useState<Record<string, boolean>>({});
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [formData, setFormData] = useState<Partial<User>>(INITIAL_FORM_STATE);

  const togglePass = (id: string) => setVisiblePasswords(prev => ({...prev, [id]: !prev[id]}));

  const handleOpenAdd = () => {
    setEditingUser(null);
    setFormData(INITIAL_FORM_STATE);
    setIsModalOpen(true);
  };

  const handleOpenEdit = (user: User) => {
    setEditingUser(user);
    setFormData(user);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setFormData(INITIAL_FORM_STATE);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingUser) {
      onEditUser({ ...editingUser, ...formData } as User);
    } else {
      const newUser: User = {
        ...formData,
        id: `U${Date.now()}`,
        lastLogin: new Date().toISOString(),
      } as User;
      onAddUser(newUser);
    }
    setIsModalOpen(false);
  };

  const filtered = users.filter(u => {
    const s = search.toLowerCase();
    return u.name.toLowerCase().includes(s) || u.email.toLowerCase().includes(s) || u.company.toLowerCase().includes(s);
  });

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
            <h2 className="text-2xl font-bold text-slate-800">Quản lý License & Yêu cầu</h2>
            <p className="text-sm text-slate-500">Kích hoạt và quản lý thời hạn người dùng</p>
        </div>
        <div className="flex flex-col sm:flex-row items-center gap-3 w-full md:w-auto">
          <div className="relative w-full sm:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
            <input 
              className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500 shadow-sm transition-all"
              placeholder="Tìm kiếm..."
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
          </div>
          <button 
            onClick={handleOpenAdd}
            className="w-full sm:w-auto flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-xl text-sm font-bold shadow-sm transition-all active:scale-95"
          >
            <UserPlus className="w-4 h-4" /> Thêm người dùng
          </button>
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50/50 border-b border-slate-100 text-slate-500 font-semibold">
              <tr>
                <th className="px-6 py-4">Thông tin</th>
                <th className="px-6 py-4">Công ty</th>
                <th className="px-6 py-4">Mật khẩu</th>
                <th className="px-6 py-4">Loại License</th>
                <th className="px-6 py-4">Trạng thái</th>
                <th className="px-6 py-4">Hạn dùng</th>
                <th className="px-6 py-4 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filtered.map(user => (
                <tr key={user.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-6 py-4">
                    <div className="font-bold text-slate-900">{user.name}</div>
                    <div className="text-xs text-slate-500">{user.email}</div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-2 text-slate-600">
                      <Building2 className="w-3.5 h-3.5 text-slate-400" />
                      <span className="truncate max-w-[120px]">{user.company}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-2">
                      <code className="bg-slate-100 px-2 py-1 rounded text-[11px] font-mono min-w-[70px] inline-block text-center text-slate-600">
                        {visiblePasswords[user.id] ? (user.password || '••••••') : '••••••••'}
                      </code>
                      <button onClick={() => togglePass(user.id)} className="text-slate-400 hover:text-slate-600 p-1">
                        {visiblePasswords[user.id] ? <EyeOff className="w-3.5 h-3.5" /> : <Eye className="w-3.5 h-3.5" />}
                      </button>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <select 
                      value={user.licenseType} 
                      onChange={e => onUpdateLicenseType(user.id, e.target.value as any)}
                      className={`text-[10px] font-bold px-3 py-1.5 rounded-full uppercase outline-none border-none cursor-pointer text-center min-w-[115px] shadow-sm transition-colors ${
                        user.licenseType === 'subscription' ? 'bg-blue-100 text-blue-700' : 
                        user.licenseType === 'perpetual' ? 'bg-purple-100 text-purple-700' : 'bg-slate-100 text-slate-700'
                      }`}
                    >
                      <option value="subscription">Subscription</option>
                      <option value="perpetual">Perpetual</option>
                      <option value="trial">Trial</option>
                    </select>
                  </td>
                  <td className="px-6 py-4">
                    <select 
                      value={user.status} 
                      onChange={e => onUpdateStatus(user.id, e.target.value as any)}
                      className={`text-[10px] font-bold px-3 py-1.5 rounded-full uppercase outline-none border-none cursor-pointer text-center min-w-[100px] shadow-sm transition-colors ${
                        user.status === 'active' ? 'bg-green-100 text-green-700' : 
                        user.status === 'on_hold' ? 'bg-amber-100 text-amber-700' : 'bg-red-100 text-red-700'
                      }`}
                    >
                      <option value="active">Active</option>
                      <option value="on_hold">Pending</option>
                      <option value="blocked">Blocked</option>
                      <option value="expired">Expired</option>
                    </select>
                  </td>
                  <td className="px-6 py-4 text-xs">
                    <input 
                        type="date" 
                        value={user.expirationDate}
                        onChange={(e) => onUpdateExpiration(user.id, e.target.value)}
                        className="border border-slate-200 rounded-lg px-2 py-1 focus:ring-2 focus:ring-blue-100 bg-slate-50 outline-none"
                      />
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-1">
                      <button onClick={() => handleOpenEdit(user)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg"><Edit3 className="w-4 h-4" /></button>
                      <button onClick={() => onDeleteUser(user.id)} className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg"><Trash2 className="w-4 h-4" /></button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in">
          <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-slate-800">{editingUser ? 'Chỉnh sửa người dùng' : 'Thêm người dùng mới'}</h3>
              <button onClick={handleCloseModal} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X className="w-5 h-5" /></button>
            </div>
            <form onSubmit={handleSubmit} className="space-y-4">
              <input placeholder="Họ và tên" className="w-full px-4 py-2 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} required />
              <input placeholder="Email" className="w-full px-4 py-2 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} required />
              <input placeholder="Mật khẩu" className="w-full px-4 py-2 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500" value={formData.password} onChange={e => setFormData({...formData, password: e.target.value})} required />
              <input placeholder="Công ty" className="w-full px-4 py-2 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500" value={formData.company} onChange={e => setFormData({...formData, company: e.target.value})} />
              <div className="flex justify-end gap-3 mt-6">
                <button type="button" onClick={handleCloseModal} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-xl font-bold">Hủy</button>
                <button type="submit" className="px-6 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold shadow-lg shadow-blue-100 flex items-center gap-2"><Save className="w-4 h-4" /> Lưu</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { AppView } from '../types';
import { 
  LayoutDashboard, 
  Users, 
  MonitorPlay, 
  Bot, 
  Box,
  LogOut,
  X,
  FileCode,
  AlertCircle
} from 'lucide-react';

