  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);

  const menuItems = [
    { view: AppView.DASHBOARD, icon: LayoutDashboard, label: 'Tổng quan' },
    { view: AppView.USERS, icon: Users, label: 'Người dùng' },
