  const handleItemClick = (view: AppView) => {
    setCurrentView(view);
    onCloseMobile();
  };

  const handleLogoutClick = () => {
    setShowLogoutConfirm(true);
  };

  const confirmLogout = () => {
    setShowLogoutConfirm(false);
    onLogout();
  };

  return (
    <>
