import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { UserManagement } from './components/UserManagement';
import { SessionMonitor } from './components/SessionMonitor';
import { AiAssistant } from './components/AiAssistant';
import { IntegrationGuide } from './components/IntegrationGuide';
import { LoginScreen } from './components/LoginScreen';
import { AppView, User, Session } from './types';
import { MOCK_USERS, MOCK_SESSIONS } from './constants';
import { Menu, RefreshCw, Download as LucideDownload } from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => {
    return localStorage.getItem('app_auth_token') === 'true';
  });

  const [currentView, setCurrentView] = useState<AppView>(() => {
    const saved = localStorage.getItem('app_current_view') as AppView;
    return Object.values(AppView).includes(saved) ? saved : AppView.DASHBOARD;
  });

  const [users, setUsers] = useState<User[]>(() => {
    const saved = localStorage.getItem('app_users_data');
    if (!saved || saved === '[]') return MOCK_USERS; // Sử dụng MOCK_USERS nếu chưa có dữ liệu
    try {
      const parsed = JSON.parse(saved);
      return Array.isArray(parsed) && parsed.length > 0 ? parsed : MOCK_USERS;
    } catch { return MOCK_USERS; }
  });

  const [sessions, setSessions] = useState<Session[]>(() => {
    const saved = localStorage.getItem('app_sessions_data');
    if (!saved || saved === '[]') return MOCK_SESSIONS;
    try {
      const parsed = JSON.parse(saved);
      return Array.isArray(parsed) ? parsed : MOCK_SESSIONS;
    } catch { return MOCK_SESSIONS; }
  });

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncError, setSyncError] = useState(false);

  const lastSyncHashRef = useRef<string>("");

  const syncFromCloud = useCallback(async (silent = false) => {
    if (!silent) setIsSyncing(true);
    setSyncError(false);
    try {
      const response = await fetch(`/api/register?t=${Date.now()}`);

      // Nếu không ok (ví dụ 500 do chưa cài KV), chúng ta không throw error nữa
      if (!response.ok) {
        if (!silent) {
           console.warn("Cloud Sync không khả dụng (Có thể do chưa cấu hình Vercel KV).");
           setSyncError(true);
        }
        return;
      }

      const cloudData = await response.json();
      if (Array.isArray(cloudData)) {
        const currentHash = JSON.stringify(cloudData);

        if (currentHash !== lastSyncHashRef.current) {
          lastSyncHashRef.current = currentHash;
          setUsers(prev => {
            const cloudIds = new Set(cloudData.map(u => u.id));
            const localOnly = prev.filter(u => !cloudIds.has(u.id));
            return [...cloudData, ...localOnly];
          });
          if (!silent) console.log("Dữ liệu đã được đồng bộ từ Cloud.");
        }
      }
    } catch (e) {
      if (!silent) {
        console.warn("Lỗi kết nối API:", e);
        setSyncError(true);
      }
    } finally {
      if (!silent) setIsSyncing(false);
    }
  }, []);

  useEffect(() => {
    if (!isAuthenticated) return;
    syncFromCloud(true);
    const interval = setInterval(() => syncFromCloud(true), 30000);
    return () => clearInterval(interval);
  }, [isAuthenticated, syncFromCloud]);

  useEffect(() => {
    localStorage.setItem('app_users_data', JSON.stringify(users));
    localStorage.setItem('app_sessions_data', JSON.stringify(sessions));
    localStorage.setItem('app_current_view', currentView);
  }, [users, sessions, currentView]);

  const handleUpdateStatus = async (id: string, newStatus: User['status']) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, status: newStatus } : u));
    try {
      await fetch('/api/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'update_user', id, data: { status: newStatus } })
      });
    } catch (e) { console.warn("Cloud update failed - saved locally"); }
  };

  const handleUpdateLicenseType = async (id: string, newType: User['licenseType']) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, licenseType: newType } : u));
    try {
      await fetch('/api/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'update_user', id, data: { licenseType: newType } })
      });
    } catch (e) { console.warn("Cloud update failed - saved locally"); }
  };

  const handleUpdateExpiration = async (id: string, newDate: string) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, expirationDate: newDate } : u));
    try {
      await fetch('/api/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'update_user', id, data: { expirationDate: newDate } })
      });
    } catch (e) { console.warn("Cloud update failed - saved locally"); }
  };

  const handleDeleteUser = async (id: string) => {
    if (!window.confirm("Xóa vĩnh viễn người dùng này?")) return;
    setUsers(prev => prev.filter(u => u.id !== id));
    try {
      await fetch('/api/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'delete_user', id })
      });
    } catch (e) { console.warn("Cloud delete failed - saved locally"); }
  };

  const handleLogin = () => {
    localStorage.setItem('app_auth_token', 'true');
    setIsAuthenticated(true);
  };

  const handleLogout = () => {
    localStorage.removeItem('app_auth_token');
    setIsAuthenticated(false);
  };

  if (!isAuthenticated) return <LoginScreen onLogin={handleLogin} />;

  return (
    <div className="flex h-screen bg-slate-50 font-sans overflow-hidden">
      <Sidebar 
        currentView={currentView} 
        setCurrentView={setCurrentView} 
        isMobileOpen={isMobileMenuOpen}
        onCloseMobile={() => setIsMobileMenuOpen(false)}
        onLogout={handleLogout}
      />

      <main className="flex-1 flex flex-col h-full w-full relative overflow-hidden">
        <header className="flex-none px-4 py-4 md:px-8 border-b border-slate-200 bg-white shadow-sm flex justify-between items-center z-20">
          <div className="flex items-center gap-3">
