import { createClient } from '@vercel/kv';

export const config = {
  runtime: 'edge',
};

const getEnv = () => process.env[`KV_REST_API_URL`] || process.env[`REST_API_URL`] || '';
const getToken = () => process.env[`KV_REST_API_TOKEN`] || process.env[`REST_API_TOKEN`] || '';

export default async function handler(req: Request) {
  const headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, Authorization',
    'Cache-Control': 'no-store, no-cache, must-revalidate',
  };

  // Xử lý Preflight request cho CORS
  if (req.method === 'OPTIONS') {
    return new Response(null, { status: 204, headers });
  }

  const kvUrl = getEnv();
  const kvToken = getToken();

  // Kiểm tra cấu hình KV
  if (!kvUrl || !kvToken) {
    return new Response(JSON.stringify({ 
      Success: false, 
      Message: "Database chưa được cấu hình. Vui lòng thiết lập Vercel KV (KV_REST_API_URL & KV_REST_API_TOKEN)." 
    }), { status: 200, headers }); // Trả về 200 để tránh Fetch failed crash
  }

  const kv = createClient({ url: kvUrl, token: kvToken });
  const LIST_KEY = 'pending_registrations';

  try {
    if (req.method === 'GET') {
      const data = await kv.lrange(LIST_KEY, 0, -1);
      return new Response(JSON.stringify(data || []), { status: 200, headers });
    }

    if (req.method === 'POST') {
      const body = await req.json();
      const action = body.action || 'register';

      if (action === 'register') {
        const { fullName, email, password, machineId, company } = body;

        if (!email || !password) {
          return new Response(JSON.stringify({ Success: false, Message: "Vui lòng nhập đầy đủ Email và Mật khẩu." }), { status: 200, headers });
        }

        // Lấy danh sách kiểm tra trùng lặp
        const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
        if (allUsers && allUsers.some(u => u.email === email)) {
          return new Response(JSON.stringify({ Success: false, Message: "Email này đã được đăng ký trước đó." }), { status: 200, headers });
        }

        const newUser = {
          id: `U${Date.now()}`,
          name: fullName || "Người dùng mới",
          email: email,
          password: password, 
          machineId: machineId || "Unknown",
          status: 'on_hold',
          licenseType: 'trial',
          company: company || 'Cá nhân',
          expirationDate: new Date(Date.now() + 30 * 86400000).toISOString().split('T')[0],
          lastLogin: new Date().toISOString()
        };

        await kv.lpush(LIST_KEY, newUser);
        return new Response(JSON.stringify({ Success: true, Message: "Gửi yêu cầu thành công! Vui lòng chờ Admin kích hoạt." }), { status: 200, headers });
      }

      if (action === 'update_user') {
        const { id, data: updateData } = body;
        const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
        const index = allUsers.findIndex(u => u.id === id);

        if (index !== -1) {
          const updatedUser = { ...allUsers[index], ...updateData };
          await kv.lset(LIST_KEY, index, updatedUser);
          return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
        }
        return new Response(JSON.stringify({ Success: false, Message: "Không tìm thấy người dùng." }), { status: 200, headers });
      }

      if (action === 'delete_user') {
        const { id } = body;
        const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
        const userToDelete = allUsers.find(u => u.id === id);
        if (userToDelete) {
          await kv.lrem(LIST_KEY, 0, userToDelete);
          return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
        }
        return new Response(JSON.stringify({ Success: false, Message: "Không tìm thấy người dùng." }), { status: 200, headers });
      }
    }
  } catch (err: any) {
    console.error("API Error:", err);
    return new Response(JSON.stringify({ Success: false, Message: "Lỗi Server: " + err.message }), { status: 200, headers });
  }

  return new Response(JSON.stringify({ Success: false, Message: "Yêu cầu không hợp lệ." }), { status: 404, headers });
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { UserManagement } from './components/UserManagement';
import { SessionMonitor } from './components/SessionMonitor';
import { AiAssistant } from './components/AiAssistant';
import { IntegrationGuide } from './components/IntegrationGuide';
import { LoginScreen } from './components/LoginScreen';
import { AppView, User, Session } from './types';
import { MOCK_USERS, MOCK_SESSIONS } from './constants';
import { Menu, RefreshCw, Download as LucideDownload, Database } from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => {
    return localStorage.getItem('app_auth_token') === 'true';
  });

  const [currentView, setCurrentView] = useState<AppView>(() => {
    const saved = localStorage.getItem('app_current_view') as AppView;
    return Object.values(AppView).includes(saved) ? saved : AppView.DASHBOARD;
  });

  const [users, setUsers] = useState<User[]>(() => {
    const saved = localStorage.getItem('app_users_data');
    if (!saved || saved === '[]') return MOCK_USERS;
    try {
      const parsed = JSON.parse(saved);
      return Array.isArray(parsed) && parsed.length > 0 ? parsed : MOCK_USERS;
    } catch { return MOCK_USERS; }
  });

  const [sessions, setSessions] = useState<Session[]>(() => {
    const saved = localStorage.getItem('app_sessions_data');
    if (!saved || saved === '[]') return MOCK_SESSIONS;
    try {
      const parsed = JSON.parse(saved);
      return Array.isArray(parsed) ? parsed : MOCK_SESSIONS;
    } catch { return MOCK_SESSIONS; }
  });

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'online' | 'offline' | 'error'>('online');
  const [errorMessage, setErrorMessage] = useState('');

  const lastSyncHashRef = useRef<string>("");

  const syncFromCloud = useCallback(async (silent = false) => {
    if (!silent) setIsSyncing(true);
    try {
      const response = await fetch(`/api/register?t=${Date.now()}`);

      const result = await response.json();

      // Kiểm tra nếu API trả về thông báo lỗi cấu hình
      if (result.Success === false && result.Message?.includes("Database")) {
        setSyncStatus('error');
        setErrorMessage(result.Message);
        return;
      }

      if (Array.isArray(result)) {
        setSyncStatus('online');
        setErrorMessage('');
        const currentHash = JSON.stringify(result);
        if (currentHash !== lastSyncHashRef.current) {
          lastSyncHashRef.current = currentHash;
          setUsers(prev => {
            const cloudIds = new Set(result.map((u: any) => u.id));
            const localOnly = prev.filter(u => !cloudIds.has(u.id));
            return [...result, ...localOnly];
          });
        }
      }
    } catch (e) {
      setSyncStatus('offline');
      if (!silent) console.warn("Kết nối thất bại, đang chạy chế độ Local.");
    } finally {
      if (!silent) setIsSyncing(false);
    }
  }, []);

  useEffect(() => {
    if (!isAuthenticated) return;
    syncFromCloud(true);
    const interval = setInterval(() => syncFromCloud(true), 30000);
    return () => clearInterval(interval);
  }, [isAuthenticated, syncFromCloud]);

  useEffect(() => {
    localStorage.setItem('app_users_data', JSON.stringify(users));
    localStorage.setItem('app_sessions_data', JSON.stringify(sessions));
    localStorage.setItem('app_current_view', currentView);
  }, [users, sessions, currentView]);

  const handleUpdateStatus = async (id: string, newStatus: User['status']) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, status: newStatus } : u));
    try {
      await fetch('/api/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'update_user', id, data: { status: newStatus } })
      });
    } catch (e) {}
  };

  const handleUpdateLicenseType = async (id: string, newType: User['licenseType']) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, licenseType: newType } : u));
    try {
      await fetch('/api/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'update_user', id, data: { licenseType: newType } })
      });
    } catch (e) {}
  };

  const handleUpdateExpiration = async (id: string, newDate: string) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, expirationDate: newDate } : u));
    try {
      await fetch('/api/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'update_user', id, data: { expirationDate: newDate } })
      });
    } catch (e) {}
  };

  const handleDeleteUser = async (id: string) => {
    if (!window.confirm("Xóa vĩnh viễn người dùng này?")) return;
    setUsers(prev => prev.filter(u => u.id !== id));
    try {
      await fetch('/api/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'delete_user', id })
      });
    } catch (e) {}
  };

  if (!isAuthenticated) return <LoginScreen onLogin={() => setIsAuthenticated(true)} />;

  return (
    <div className="flex h-screen bg-slate-50 font-sans overflow-hidden">
      <Sidebar 
        currentView={currentView} 
        setCurrentView={setCurrentView} 
        isMobileOpen={isMobileMenuOpen}
        onCloseMobile={() => setIsMobileMenuOpen(false)}
        onLogout={() => setIsAuthenticated(false)}
      />

      <main className="flex-1 flex flex-col h-full w-full relative overflow-hidden">
        <header className="flex-none px-4 py-4 md:px-8 border-b border-slate-200 bg-white shadow-sm flex justify-between items-center z-20">
          <div className="flex items-center gap-3">
             <button onClick={() => setIsMobileMenuOpen(true)} className="md:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                <Menu className="w-6 h-6" />
             </button>
             <div>
                <h1 className="text-lg md:text-xl font-bold text-slate-800">{currentView}</h1>
                <div className="text-[10px] text-slate-500 flex items-center gap-1">
                    <span className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'online' ? 'bg-green-500 animate-pulse' : (syncStatus === 'error' ? 'bg-red-500' : 'bg-amber-500')}`}></span>
                    Cloud Sync: {syncStatus === 'online' ? 'Sẵn sàng' : (syncStatus === 'error' ? 'Lỗi Database' : 'Chế độ Offline')}
                </div>
             </div>
          </div>

          <div className="flex items-center gap-2">
            <button 
                onClick={() => syncFromCloud(false)}
                disabled={isSyncing}
                className="flex items-center gap-2 px-3 py-1.5 rounded-lg bg-blue-600 hover:bg-blue-700 text-white transition-colors text-xs font-semibold shadow-sm disabled:opacity-50"
            >
                {isSyncing ? <RefreshCw className="w-3.5 h-3.5 animate-spin" /> : <LucideDownload className="w-3.5 h-3.5" />}
                Đồng bộ
            </button>
          </div>
        </header>

        {syncStatus === 'error' && (
          <div className="bg-red-50 border-b border-red-100 p-3 flex items-center gap-3 text-red-700 text-xs font-medium">
            <Database className="w-4 h-4" />
            <span>{errorMessage}</span>
          </div>
        )}

        <div className="flex-1 overflow-y-auto p-4 md:p-8">
            <div className="max-w-7xl mx-auto">
                {currentView === AppView.DASHBOARD && <Dashboard users={users} sessions={sessions} onUpdateStatus={handleUpdateStatus} onUpdateLicenseType={handleUpdateLicenseType} />}
                {currentView === AppView.USERS && (
                  <UserManagement 
                    users={users} 
                    onAddUser={(u)=>setUsers([u, ...users])} 
                    onEditUser={(u)=>setUsers(users.map(x=>x.id===u.id?u:x))} 
                    onUpdateStatus={handleUpdateStatus} 
                    onUpdateLicenseType={handleUpdateLicenseType}
                    onUpdateExpiration={handleUpdateExpiration}
                    onDeleteUser={handleDeleteUser} 
                  />
                )}
                {currentView === AppView.SESSIONS && <SessionMonitor sessions={sessions} users={users} onKillSession={(id)=>setSessions(sessions.filter(s=>s.id!==id))} onAddSession={(s)=>setSessions([s, ...sessions])} />}
                {currentView === AppView.AI_INSIGHTS && <AiAssistant users={users} sessions={sessions} />}
                {currentView === AppView.INTEGRATION && <IntegrationGuide />}
            </div>
        </div>
      </main>
    </div>
  );
};

export default App;

