import { createClient } from '@vercel/kv';

export const config = {
  runtime: 'edge',
};

// Key bí mật để bảo vệ các thao tác Admin (Bạn nên cấu hình trong Vercel Env)
const ADMIN_SECRET_KEY = process.env.ADMIN_SECRET_KEY || "DSH_SECRET_2024";

const getEnv = () => process.env[`KV_REST_API_URL`] || process.env[`REST_API_URL`] || '';
const getToken = () => process.env[`KV_REST_API_TOKEN`] || process.env[`REST_API_TOKEN`] || '';

export default async function handler(req: Request) {
  const headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, Authorization, x-admin-key',
  };

  if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers });

  const kvUrl = getEnv();
  const kvToken = getToken();
  if (!kvUrl || !kvToken) {
    return new Response(JSON.stringify({ Success: false, Message: "Database chưa cấu hình." }), { status: 200, headers });
  }

  const kv = createClient({ url: kvUrl, token: kvToken });
  const LIST_KEY = 'pending_registrations';

  try {
    const body = await req.json();
    const action = body.action || 'register';

    // 1. TÍNH NĂNG MỚI: XÁC THỰC TỰ ĐỘNG (Dùng cho Auto-login trong Revit)
    if (action === 'verify_license') {
      const { email, machineId } = body;
      const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
      const user = allUsers.find(u => u.email === email && u.machineId === machineId);

      if (!user) {
        return new Response(JSON.stringify({ Success: false, Message: "Thiết bị hoặc tài khoản không hợp lệ." }), { status: 200, headers });
      }

      const isExpired = new Date(user.expirationDate) < new Date();
      if (isExpired) {
        return new Response(JSON.stringify({ Success: false, Message: "Bản quyền đã hết hạn." }), { status: 200, headers });
      }

      if (user.status !== 'active') {
        return new Response(JSON.stringify({ Success: false, Message: "Tài khoản đang bị khóa hoặc chờ duyệt." }), { status: 200, headers });
      }

      return new Response(JSON.stringify({ Success: true, User: user }), { status: 200, headers });
    }

    // 2. ĐĂNG KÝ MỚI
    if (action === 'register') {
      const { fullName, email, password, machineId, company } = body;
      const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
      if (allUsers.some(u => u.email === email)) {
        return new Response(JSON.stringify({ Success: false, Message: "Email đã tồn tại." }), { status: 200, headers });
      }

      const newUser = {
        id: `U${Date.now()}`,
        name: fullName,
        email,
        password, // Trong thực tế nên Hash password, nhưng tạm thời để chuỗi để bạn dễ quản lý
        machineId,
        status: 'on_hold',
        licenseType: 'trial',
        company: company || 'Cá nhân',
        expirationDate: new Date(Date.now() + 30 * 86400000).toISOString().split('T')[0],
        lastLogin: new Date().toISOString()
      };

      await kv.lpush(LIST_KEY, newUser);
      return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
    }

    // 3. BẢO MẬT ADMIN: Các thao tác sửa/xóa yêu cầu Key bí mật
    const clientAdminKey = req.headers.get('x-admin-key');
    if (clientAdminKey !== ADMIN_SECRET_KEY) {
       // Nếu gọi từ Web App của bạn (cùng origin) thì cho phép, nếu gọi từ bên ngoài (Postman/Tool lạ) thì chặn
       // Ở đây ta tạm thời cho phép GET để lấy danh sách hiển thị dashboard
       if (req.method !== 'GET' && action !== 'register' && action !== 'verify_license') {
          return new Response(JSON.stringify({ Success: false, Message: "Unauthorized Access" }), { status: 401, headers });
       }
    }

    if (action === 'update_user') {
      const { id, data: updateData } = body;
      const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
      const index = allUsers.findIndex(u => u.id === id);
      if (index !== -1) {
        await kv.lset(LIST_KEY, index, { ...allUsers[index], ...updateData });
        return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
      }
    }

    if (action === 'delete_user') {
      const { id } = body;
      const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
      const user = allUsers.find(u => u.id === id);
      if (user) {
        await kv.lrem(LIST_KEY, 0, user);
        return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
      }
    }

    if (req.method === 'GET') {
      const data = await kv.lrange(LIST_KEY, 0, -1);
      return new Response(JSON.stringify(data || []), { status: 200, headers });
    }

  } catch (err: any) {
    return new Response(JSON.stringify({ Success: false, Message: err.message }), { status: 200, headers });
  }

  return new Response(JSON.stringify({ Success: false }), { status: 404, headers });
}

