    public class AuthService
    {
        private readonly string _apiUrl = "${apiPath}/api/register";

        // Đường dẫn lưu file license cục bộ trên máy user
        private readonly string _localLicensePath = Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), 
            "DSH_RevitTool", "license.dat"
        );

        public async Task<bool> RegisterAsync(string name, string email, string pass, string company)
        {
            var payload = new { action = "register", fullName = name, email, password = pass, company, machineId = GetMachineId() };
            return await PostActionAsync(payload);
        }

        // HÀM MỚI: Kiểm tra license đã lưu để tự động đăng nhập
        public async Task<bool> CheckAutoLoginAsync()
        {
            try {
                if (!File.Exists(_localLicensePath)) return false;
                string savedEmail = File.ReadAllText(_localLicensePath).Trim();

                var payload = new { action = "verify_license", email = savedEmail, machineId = GetMachineId() };
                var success = await PostActionAsync(payload);
                return success;
            } catch { return false; }
        }

