namespace DSH_RevitAPI
{
    // TransactionMode.Manual là bắt buộc cho các lệnh Revit
    [Transaction(TransactionMode.Manual)]
    public class ShowLoginCommand : IExternalCommand
    {
        public Result Execute(ExternalCommandData commandData, ref string message, ElementSet elements)
        {
            AuthService auth = new AuthService();

            // 1. Kiểm tra Auto-login trước
            var isAuthorized = Task.Run(() => auth.CheckAutoLoginAsync()).Result;

            if (isAuthorized)
            {
                // Nếu đã có license hợp lệ, chạy thẳng tool không hiện Form
                return Result.Succeeded;
            }

            // 2. Nếu chưa có, mới hiện Form đăng nhập
            License_WPF loginWindow = new License_WPF();
            if (loginWindow.ShowDialog() == true)
            {
                // Lưu lại email để lần sau tự đăng nhập
                auth.SaveLicenseLocally(loginWindow.UserEmail);
                return Result.Succeeded;
            }
            return Result.Cancelled;
        }
    }
}
