        {
            try
            {
                string dir = Path.GetDirectoryName(_localLicensePath);
                if (!Directory.Exists(dir)) Directory.CreateDirectory(dir);

                // Mã hóa email trước khi lưu
                string encryptedEmail = Encrypt(email);
                File.WriteAllText(_localLicensePath, encryptedEmail);
            }
            catch { }
        }

        private async Task<bool> PostActionAsync(object payload)
        {
            using (var client = new HttpClient())
            {
                var json = JsonConvert.SerializeObject(payload);
                var content = new StringContent(json, Encoding.UTF8, "application/json");
                try {
