  const [copiedFile, setCopiedFile] = useState<string | null>(null);

  const handleCopy = (code: string, fileName: string) => {
    navigator.clipboard.writeText(code);
    setCopiedFile(fileName);
    setTimeout(() => setCopiedFile(null), 2000);
  };

  const vercelUrl = "https://revit-api.vercel.app/api/register";

  const authServiceCode = `using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;

namespace DSH_RevitAPI.Services
{
    public class AuthService
    {
        private readonly string _apiUrl = "${vercelUrl}";
        private readonly string _localLicensePath = Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
            "DSH_RevitTool", "license.dat"
        );

        // Key mã hóa (Nên giữ bí mật, không đổi để tránh mất dữ liệu đã lưu)
        private static readonly string EncryptionKey = "DSH_Secret_Key_For_Revit_Tool_2024";

        public async Task<bool> RegisterAsync(string name, string email, string pass, string company)
        {
            var payload = new { action = "register", fullName = name, email, password = pass, company, machineId = GetMachineId() };
            return await PostActionAsync(payload);
        }

        public async Task<bool> LoginAsync(string email, string pass)
        {
            var payload = new { action = "verify_license", email = email, password = pass, machineId = GetMachineId() };
            bool success = await PostActionAsync(payload);
            if (success) SaveLicenseLocally(email);
            return success;
        }

        public async Task<bool> CheckAutoLoginAsync()
        {
            try
            {
                if (!File.Exists(_localLicensePath)) return false;

                // Giải mã dữ liệu từ file
                string encryptedData = File.ReadAllText(_localLicensePath);
                string savedEmail = Decrypt(encryptedData);

                var payload = new { action = "verify_license", email = savedEmail, machineId = GetMachineId() };
                return await PostActionAsync(payload);
            }
            catch { return false; }
        }

        public void SaveLicenseLocally(string email)
        {
            try
            {
                string dir = Path.GetDirectoryName(_localLicensePath);
                if (!Directory.Exists(dir)) Directory.CreateDirectory(dir);

                // Mã hóa email trước khi lưu
                string encryptedEmail = Encrypt(email);
                File.WriteAllText(_localLicensePath, encryptedEmail);
            }
            catch { }
        }

        private async Task<bool> PostActionAsync(object payload)
        {
            using (var client = new HttpClient())
            {
                var json = JsonConvert.SerializeObject(payload);
                var content = new StringContent(json, Encoding.UTF8, "application/json");
                try {
                    var response = await client.PostAsync(_apiUrl, content);
                    if (response.IsSuccessStatusCode)
                    {
                        var resultJson = await response.Content.ReadAsStringAsync();
                        dynamic result = JsonConvert.DeserializeObject(resultJson);
                        return (bool)result.Success;
                    }
                } catch { return false; }
                return false;
            }
        }

        private string GetMachineId() => Environment.MachineName + "-" + Environment.UserName;

        #region Encryption Logic (AES)
        private string Encrypt(string clearText)
        {
            byte[] clearBytes = Encoding.Unicode.GetBytes(clearText);
            using (Aes encryptor = Aes.Create())
            {
                Rfc2898DeriveBytes pdb = new Rfc2898DeriveBytes(EncryptionKey, new byte[] { 0x49, 0x76, 0x61, 0x6e, 0x20, 0x4d, 0x65, 0x64, 0x76, 0x65, 0x64, 0x65, 0x76 });
                encryptor.Key = pdb.GetBytes(32);
                encryptor.IV = pdb.GetBytes(16);
                using (MemoryStream ms = new MemoryStream())
                {
                    using (CryptoStream cs = new CryptoStream(ms, encryptor.CreateEncryptor(), CryptoStreamMode.Write))
                    {
                        cs.Write(clearBytes, 0, clearBytes.Length);
                        cs.Close();
                    }
                    clearText = Convert.ToBase64String(ms.ToArray());
                }
            }
            return clearText;
        }

        private string Decrypt(string cipherText)
        {
            try {
                cipherText = cipherText.Replace(" ", "+");
                // SỬA LỖI: Sử dụng Convert.FromBase64String thay vì Convert.Base64String
                byte[] cipherBytes = Convert.FromBase64String(cipherText);
                using (Aes encryptor = Aes.Create())
                {
                    Rfc2898DeriveBytes pdb = new Rfc2898DeriveBytes(EncryptionKey, new byte[] { 0x49, 0x76, 0x61, 0x6e, 0x20, 0x4d, 0x65, 0x64, 0x76, 0x65, 0x64, 0x65, 0x76 });
                    encryptor.Key = pdb.GetBytes(32);
                    encryptor.IV = pdb.GetBytes(16);
                    using (MemoryStream ms = new MemoryStream())
                    {
                        using (CryptoStream cs = new CryptoStream(ms, encryptor.CreateDecryptor(), CryptoStreamMode.Write))
                        {
                            cs.Write(cipherBytes, 0, cipherBytes.Length);
                            cs.Close();
                        }
                        return Encoding.Unicode.GetString(ms.ToArray());
                    }
                }
            } catch { return ""; }
        }
        #endregion
    }
}`;

  const wpfCode = `// FILE: License_WPF.xaml.cs
