  id: string;
  name: string;
  email: string;
  password?: string;
  company: string;
  status: 'active' | 'expired' | 'blocked' | 'on_hold';
  licenseType: 'perpetual' | 'subscription' | 'trial';
  expirationDate: string;
  lastLogin: string;
  machineId?: string;
}

export interface Session {
  id: string;
  userId: string;
  userName: string;
  machineId: string;
  revitVersion: string;
  ipAddress: string;
  loginTime: string;
  status: 'online' | 'idle';
}

