import { createClient } from '@vercel/kv';

export const config = {
  runtime: 'edge',
};

const ADMIN_SECRET_KEY = process.env.ADMIN_SECRET_KEY || "DSH_SECRET_2024";

const getEnv = () => process.env[`KV_REST_API_URL`] || process.env[`REST_API_URL`] || '';
const getToken = () => process.env[`KV_REST_API_TOKEN`] || process.env[`REST_API_TOKEN`] || '';

export default async function handler(req: Request) {
  const headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, Authorization, x-admin-key',
  };

  if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers });

  const kvUrl = getEnv();
  const kvToken = getToken();
  if (!kvUrl || !kvToken) return new Response(JSON.stringify({ Success: false, Message: "KV Not Configured" }), { status: 200, headers });

  const kv = createClient({ url: kvUrl, token: kvToken });
  const LIST_KEY = 'pending_registrations';

  try {
    const body = await req.json().catch(() => ({}));
    const action = body.action || 'get_all';

    // XỬ LÝ ĐĂNG NHẬP VÀ KIỂM TRA BẢN QUYỀN
    if (action === 'verify_license') {
      const { email, machineId, password } = body;
      const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
      const user = allUsers.find(u => u.email === email);

      if (!user) return new Response(JSON.stringify({ Success: false, Message: "Tài khoản không tồn tại." }), { status: 200, headers });

      if (password && user.password !== password) {
          return new Response(JSON.stringify({ Success: false, Message: "Sai mật khẩu." }), { status: 200, headers });
      }

      if (user.machineId && user.machineId !== machineId) {
          return new Response(JSON.stringify({ Success: false, Message: "Tài khoản này đã được đăng ký cho thiết bị khác." }), { status: 200, headers });
      }

      if (user.status !== 'active') return new Response(JSON.stringify({ Success: false, Message: "Tài khoản chưa được kích hoạt." }), { status: 200, headers });
      if (new Date(user.expirationDate) < new Date()) return new Response(JSON.stringify({ Success: false, Message: "Bản quyền đã hết hạn." }), { status: 200, headers });

      return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
    }

    // ĐĂNG KÝ (Dành cho khách hàng tự đăng ký từ Tool)
    if (action === 'register') {
      const { fullName, email, password, machineId, company } = body;
      const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
      if (allUsers.some(u => u.email === email)) return new Response(JSON.stringify({ Success: false, Message: "Email đã tồn tại." }), { status: 200, headers });

      const newUser = {
        id: `U${Date.now()}`,
        name: fullName, email, password, machineId,
        status: 'on_hold', licenseType: 'trial', company: company || 'Cá nhân',
        expirationDate: new Date(Date.now() + 30 * 86400000).toISOString().split('T')[0],
        lastLogin: new Date().toISOString()
      };
      await kv.lpush(LIST_KEY, newUser);
      return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
    }

    // ADMIN ACTIONS (Yêu cầu Secret Key)
    const adminKey = req.headers.get('x-admin-key');
    if (adminKey === ADMIN_SECRET_KEY) {
        if (action === 'get_all') {
            const data = await kv.lrange(LIST_KEY, 0, -1);
            return new Response(JSON.stringify(data || []), { status: 200, headers });
        }

        // Thêm người dùng mới từ Admin Panel
        if (action === 'add_user') {
            const { user } = body;
            await kv.lpush(LIST_KEY, user);
            return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
        }

        if (action === 'update_user') {
            const { id, data: updateData } = body;
            const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
            const index = allUsers.findIndex(u => u.id === id);
            if (index !== -1) {
                const updatedUser = { ...allUsers[index], ...updateData };
                await kv.lset(LIST_KEY, index, updatedUser);
                return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
            }
        }

        if (action === 'delete_user') {
            const { id } = body;
            const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
            const user = allUsers.find(u => u.id === id);
            if (user) {
                await kv.lrem(LIST_KEY, 0, user);
                return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
            }
        }
    }

    return new Response(JSON.stringify({ Success: false, Message: "Unauthorized or Invalid action" }), { status: 200, headers });

  } catch (err: any) {
    return new Response(JSON.stringify({ Success: false, Message: err.message }), { status: 200, headers });
  }
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { UserManagement } from './components/UserManagement';
import { SessionMonitor } from './components/SessionMonitor';
import { AiAssistant } from './components/AiAssistant';
import { IntegrationGuide } from './components/IntegrationGuide';
import { LoginScreen } from './components/LoginScreen';
import { AppView, User, Session } from './types';
import { MOCK_USERS, MOCK_SESSIONS } from './constants';
import { Menu, RefreshCw, Download as LucideDownload, Database, AlertCircle } from 'lucide-react';

const ADMIN_SECRET_KEY = "DSH_SECRET_2024";

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => {
    return localStorage.getItem('app_auth_token') === 'true';
  });

  const [currentView, setCurrentView] = useState<AppView>(() => {
    const saved = localStorage.getItem('app_current_view') as AppView;
    return Object.values(AppView).includes(saved) ? saved : AppView.DASHBOARD;
  });

  const [users, setUsers] = useState<User[]>(() => {
    const saved = localStorage.getItem('app_users_data');
    if (!saved || saved === '[]') return MOCK_USERS;
    try {
      return JSON.parse(saved);
    } catch { return MOCK_USERS; }
  });

  const [sessions, setSessions] = useState<Session[]>(() => {
    const saved = localStorage.getItem('app_sessions_data');
    if (!saved || saved === '[]') return MOCK_SESSIONS;
    try {
      return JSON.parse(saved);
    } catch { return MOCK_SESSIONS; }
  });

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'online' | 'offline' | 'error'>('online');

  // Lưu state vào localStorage để dự phòng offline
  useEffect(() => {
    localStorage.setItem('app_users_data', JSON.stringify(users));
  }, [users]);

  useEffect(() => {
    localStorage.setItem('app_sessions_data', JSON.stringify(sessions));
  }, [sessions]);

  useEffect(() => {
    localStorage.setItem('app_current_view', currentView);
  }, [currentView]);

  const syncFromCloud = useCallback(async (silent = false) => {
    if (!silent) setIsSyncing(true);
    try {
      const response = await fetch('/api/register', {
        headers: { 'x-admin-key': ADMIN_SECRET_KEY }
      });
      if (!response.ok) {
        setSyncStatus('offline');
        return;
      }
      const result = await response.json();
      if (Array.isArray(result)) {
        setSyncStatus('online');
        setUsers(result);
      }
    } catch (e) {
      setSyncStatus('offline');
    } finally {
      if (!silent) setIsSyncing(false);
    }
  }, []);

  useEffect(() => {
    if (isAuthenticated) {
      syncFromCloud(true);
      const interval = setInterval(() => syncFromCloud(true), 15000); // Sync mỗi 15s
      return () => clearInterval(interval);
    }
  }, [isAuthenticated, syncFromCloud]);

  const apiCall = async (action: string, payload: any) => {
    // Luôn cố gắng gọi API kể cả khi syncStatus không online (để thử kết nối lại)
    try {
      const response = await fetch('/api/register', {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json',
          'x-admin-key': ADMIN_SECRET_KEY
        },
        body: JSON.stringify({ action, ...payload })
      });
      return await response.json();
    } catch (e) {
      console.error("API Call failed:", e);
      return { Success: false };
    }
  };

  const handleAddUser = (u: User) => {
    setUsers(prev => [u, ...prev]);
    apiCall('add_user', { user: u });
  };

  const handleEditUser = (u: User) => {
    setUsers(prev => prev.map(x => x.id === u.id ? u : x));
    apiCall('update_user', { id: u.id, data: u });
  };

  const handleUpdateStatus = (id: string, status: User['status']) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, status } : u));
    apiCall('update_user', { id, data: { status } });
  };

  const handleUpdateLicenseType = (id: string, licenseType: User['licenseType']) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, licenseType } : u));
    apiCall('update_user', { id, data: { licenseType } });
  };

  const handleUpdateExpiration = (id: string, expirationDate: string) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, expirationDate } : u));
    apiCall('update_user', { id, data: { expirationDate } });
  };

  const handleDeleteUser = (id: string) => {
    if (!window.confirm("Xác nhận xóa người dùng này?")) return;
    setUsers(prev => prev.filter(u => u.id !== id));
    apiCall('delete_user', { id });
  };

  if (!isAuthenticated) return <LoginScreen onLogin={() => {
    setIsAuthenticated(true);
    localStorage.setItem('app_auth_token', 'true');
  }} />;

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans">
      <Sidebar 
        currentView={currentView} 
        setCurrentView={setCurrentView} 
        isMobileOpen={isMobileMenuOpen}
        onCloseMobile={() => setIsMobileMenuOpen(false)}
        onLogout={() => {
          setIsAuthenticated(false);
          localStorage.removeItem('app_auth_token');
        }}
      />

      <main className="flex-1 flex flex-col h-full overflow-hidden">
        <header className="px-8 py-4 bg-white border-b border-slate-200 flex justify-between items-center z-10">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsMobileMenuOpen(true)} className="md:hidden text-slate-600"><Menu /></button>
             <div>
                <h1 className="text-xl font-bold text-slate-800 uppercase tracking-tight">
                  {currentView}
                </h1>
                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">
                  Status: <span className={syncStatus === 'online' ? 'text-green-500' : 'text-amber-500'}>{syncStatus}</span>
                </p>
             </div>
          </div>
          <button 
              onClick={() => syncFromCloud(false)} 
              disabled={isSyncing}
              className="p-2 hover:bg-slate-100 rounded-full transition-colors disabled:opacity-50"
          >
              <RefreshCw className={`w-5 h-5 text-slate-400 ${isSyncing ? 'animate-spin' : ''}`} />
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-8">
            {currentView === AppView.DASHBOARD && <Dashboard users={users} sessions={sessions} onUpdateStatus={handleUpdateStatus} onUpdateLicenseType={handleUpdateLicenseType} />}
            {currentView === AppView.USERS && (
              <UserManagement 
                users={users} 
                onAddUser={handleAddUser} 
                onEditUser={handleEditUser}
                onUpdateStatus={handleUpdateStatus}
                onUpdateLicenseType={handleUpdateLicenseType}
                onUpdateExpiration={handleUpdateExpiration}
                onDeleteUser={handleDeleteUser}
              />
            )}
            {currentView === AppView.SESSIONS && <SessionMonitor sessions={sessions} users={users} onKillSession={(id) => setSessions(sessions.filter(s => s.id !== id))} onAddSession={(s) => setSessions([s, ...sessions])} />}
            {currentView === AppView.AI_INSIGHTS && <AiAssistant users={users} sessions={sessions} />}
            {currentView === AppView.INTEGRATION && <IntegrationGuide />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { User, Session } from '../types';
import { CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, LineChart, Line, XAxis, YAxis, AreaChart, Area } from 'recharts';
import { Wifi, AlertTriangle, ShieldCheck, Activity, BellRing, X, UserCheck, Calendar, ChevronDown, Filter } from 'lucide-react';

interface DashboardProps {
  users: User[];
  sessions: Session[];
  onUpdateStatus: (id: string, status: User['status']) => void;
  onUpdateLicenseType: (id: string, type: User['licenseType']) => void;
}

type ModalType = 'new' | 'online' | 'expired' | 'active' | null;
type TimeRange = 'week' | 'month' | 'year';

export const Dashboard: React.FC<DashboardProps> = ({ users = [], sessions = [], onUpdateStatus, onUpdateLicenseType }) => {
  const [activeModal, setActiveModal] = useState<ModalType>(null);
  const [timeRange, setTimeRange] = useState<TimeRange>('week');

  const safeUsers = Array.isArray(users) ? users : [];
  const safeSessions = Array.isArray(sessions) ? sessions : [];

  const onHoldUsers = safeUsers.filter(u => u.status === 'on_hold');
  const onlineSessions = safeSessions;
  const expiredUsers = safeUsers.filter(u => u.status === 'expired');
  const activeUsers = safeUsers.filter(u => u.status === 'active');

  // Logic xử lý dữ liệu biểu đồ theo thời gian
  const chartData = useMemo(() => {
    const now = new Date();
    const dataMap: Record<string, number> = {};

    if (timeRange === 'week') {
      // 7 ngày qua
      for (let i = 6; i >= 0; i--) {
        const d = new Date();
        d.setDate(now.getDate() - i);
        dataMap[d.toLocaleDateString('vi-VN', { day: 'numeric', month: 'short' })] = 0;
      }
    } else if (timeRange === 'month') {
      // 30 ngày qua
      for (let i = 29; i >= 0; i--) {
        const d = new Date();
        d.setDate(now.getDate() - i);
        dataMap[d.toLocaleDateString('vi-VN', { day: 'numeric', month: 'short' })] = 0;
      }
    } else {
      // 12 tháng qua
      for (let i = 11; i >= 0; i--) {
        const d = new Date();
        d.setMonth(now.getMonth() - i);
        dataMap[d.toLocaleDateString('vi-VN', { month: 'short' })] = 0;
      }
    }

    safeUsers.forEach(user => {
      const date = new Date(user.lastLogin || Date.now());
      let key = "";
      if (timeRange === 'year') {
        key = date.toLocaleDateString('vi-VN', { month: 'short' });
      } else {
        key = date.toLocaleDateString('vi-VN', { day: 'numeric', month: 'short' });
      }

      if (dataMap[key] !== undefined) {
        dataMap[key]++;
      }
    });

    return Object.entries(dataMap).map(([name, count]) => ({ name, count }));
  }, [safeUsers, timeRange]);

  const licenseTypeData = [
    { name: 'Subscription', value: safeUsers.filter(u => u.licenseType === 'subscription').length },
    { name: 'Perpetual', value: safeUsers.filter(u => u.licenseType === 'perpetual').length },
    { name: 'Trial', value: safeUsers.filter(u => u.licenseType === 'trial').length },
  ].filter(d => d.value > 0);

  const COLORS = ['#3b82f6', '#8b5cf6', '#64748b'];

  const StatCard = ({ title, value, subValue, icon: Icon, color, bg, highlight, onClick }: any) => (
    <button 
      onClick={onClick}
      className={`w-full text-left bg-white p-6 rounded-2xl shadow-sm border ${highlight ? 'border-blue-200 ring-2 ring-blue-50' : 'border-slate-100'} flex items-start justify-between hover:shadow-lg hover:border-blue-300 transition-all hover:-translate-y-1 active:scale-95 group`}
    >
      <div>
        <p className="text-sm font-medium text-slate-500 mb-1 group-hover:text-blue-600 transition-colors">{title}</p>
        <div className="flex items-baseline gap-2">
            <h3 className="text-3xl font-bold text-slate-800">{value}</h3>
