                    <Activity className="w-5 h-5 text-indigo-500" /> Xu hướng đăng ký
                </h3>
                <div className="flex bg-slate-100 p-1 rounded-xl">
                    <button 
                        onClick={() => setTimeRange('week')}
                        className={`px-3 py-1.5 text-xs font-bold rounded-lg transition-all ${timeRange === 'week' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
