            <div className="flex justify-end mb-2">
              <button onClick={() => setActiveModal(null)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400 transition-colors"><X className="w-5 h-5" /></button>
            </div>
            {renderModalContent()}
