import { createClient } from '@vercel/kv';

export const config = {
  runtime: 'edge',
};

const DEFAULT_ADMIN_KEY = "DSH_SECRET_2024";
const MAX_MACHINES = 4; // Giới hạn tối đa 4 máy

const getEnv = (key: string) => process.env[key] || '';

export default async function handler(req: Request) {
  const headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, Authorization, x-admin-key',
  };

  if (req.method === 'OPTIONS') {
    return new Response(null, { status: 204, headers });
  }

  const kvUrl = getEnv('KV_REST_API_URL') || getEnv('REST_API_URL');
  const kvToken = getEnv('KV_REST_API_TOKEN') || getEnv('REST_API_TOKEN');
  const ADMIN_SECRET_KEY = getEnv('ADMIN_SECRET_KEY') || DEFAULT_ADMIN_KEY;

  if (!kvUrl || !kvToken) {
    return new Response(JSON.stringify({ 
      Success: false, 
      Message: "Hệ thống lưu trữ KV chưa được cấu hình." 
    }), { status: 200, headers });
  }

  const kv = createClient({ url: kvUrl, token: kvToken });
  const LIST_KEY = 'pending_registrations';

  try {
    let action = 'get_all';
    let body: any = {};

    if (req.method === 'POST' || req.method === 'PUT') {
      try {
        body = await req.json();
        action = body.action || 'get_all';
      } catch (e) {
        action = 'get_all';
      }
    }

    // 1. CÔNG KHAI: Kiểm tra bản quyền
    if (action === 'verify_license') {
      const { email, machineId, password } = body;
      const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
      const userIndex = allUsers.findIndex(u => u.email === email);
      const user = allUsers[userIndex];

      if (!user) return new Response(JSON.stringify({ Success: false, Message: "Tài khoản không tồn tại." }), { status: 200, headers });
      if (password && user.password !== password) return new Response(JSON.stringify({ Success: false, Message: "Sai mật khẩu." }), { status: 200, headers });

      if (!user.machineIds) user.machineIds = [];

      if (machineId) {
        if (!user.machineIds.includes(machineId)) {
          if (user.machineIds.length >= MAX_MACHINES) {
            return new Response(JSON.stringify({ 
              Success: false, 
              Message: `Tài khoản này đã đạt giới hạn ${MAX_MACHINES} thiết thiết bị.` 
            }), { status: 200, headers });
          }
          user.machineIds.push(machineId);
          await kv.lset(LIST_KEY, userIndex, user);
        }
      }

      if (user.status !== 'active') return new Response(JSON.stringify({ Success: false, Message: "Tài khoản chưa được kích hoạt." }), { status: 200, headers });
      if (new Date(user.expirationDate) < new Date()) return new Response(JSON.stringify({ Success: false, Message: "License đã hết hạn." }), { status: 200, headers });

      return new Response(JSON.stringify({ Success: true, User: { name: user.name, type: user.licenseType } }), { status: 200, headers });
    }

    if (action === 'register') {
      const { fullName, email, password, machineId, company } = body;
      const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
      if (allUsers.some(u => u.email === email)) return new Response(JSON.stringify({ Success: false, Message: "Email đã tồn tại." }), { status: 200, headers });

      const newUser = {
        id: `U${Date.now()}`,
        name: fullName, email, password, 
        machineIds: machineId ? [machineId] : [],
        status: 'on_hold', licenseType: 'trial', company: company || 'Cá nhân',
        createdAt: new Date().toISOString().split('T')[0], // Lưu ngày đăng ký
        expirationDate: new Date(Date.now() + 30 * 86400000).toISOString().split('T')[0],
        lastLogin: new Date().toISOString()
      };
      await kv.lpush(LIST_KEY, newUser);
      return new Response(JSON.stringify({ Success: true, Message: "Đăng ký thành công." }), { status: 200, headers });
    }

    // 2. QUẢN TRỊ
    const adminKey = req.headers.get('x-admin-key');
    if (adminKey !== ADMIN_SECRET_KEY) return new Response(JSON.stringify({ Success: false, Message: "Unauthorized" }), { status: 200, headers });

    if (action === 'get_all') {
      const data = await kv.lrange(LIST_KEY, 0, -1);
      const fixedData = (data || []).map((u: any) => ({
        ...u,
        machineIds: u.machineIds || (u.machineId ? [u.machineId] : []),
        createdAt: u.createdAt || u.expirationDate || new Date().toISOString().split('T')[0] // Fix dữ liệu cũ
      }));
      return new Response(JSON.stringify(fixedData), { status: 200, headers });
    }

    if (action === 'add_user') {
      const { user } = body;
      user.machineIds = user.machineIds || [];
      user.createdAt = user.createdAt || new Date().toISOString().split('T')[0]; // Gán ngày đăng ký nếu thiếu
      await kv.lpush(LIST_KEY, user);
      return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
    }

    if (action === 'update_user') {
      const { id, data: updateData } = body;
      const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
      const index = allUsers.findIndex(u => u.id === id);
      if (index !== -1) {
        const updatedUser = { ...allUsers[index], ...updateData };
        await kv.lset(LIST_KEY, index, updatedUser);
        return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
      }
    }

    if (action === 'delete_user') {
      const { id } = body;
      const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
      const user = allUsers.find(u => u.id === id);
      if (user) {
        await kv.lrem(LIST_KEY, 0, user);
        return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
      }
    }

    return new Response(JSON.stringify({ Success: false, Message: "Invalid action" }), { status: 200, headers });

  } catch (err: any) {
    return new Response(JSON.stringify({ Success: false, Message: err.message }), { status: 200, headers });
  }
}

