              <div className="flex justify-end gap-3 mt-6">
                <button type="button" onClick={handleCloseModal} className="px-5 py-2 text-slate-600 hover:bg-slate-100 rounded-lg font-bold">Hủy</button>
                <button type="submit" className="px-7 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-bold shadow-lg shadow-blue-100 flex items-center gap-2">
