                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import { createClient } from '@vercel/kv';

export const config = {
  runtime: 'edge',
};

const DEFAULT_ADMIN_KEY = "DSH_SECRET_2024";
const MAX_MACHINES = 4; 

const getEnv = (key: string) => process.env[key] || '';

export default async function handler(req: Request) {
  const headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, Authorization, x-admin-key',
  };

  if (req.method === 'OPTIONS') {
    return new Response(null, { status: 204, headers });
  }

  const kvUrl = getEnv('KV_REST_API_URL') || getEnv('REST_API_URL');
  const kvToken = getEnv('KV_REST_API_TOKEN') || getEnv('REST_API_TOKEN');
  const ADMIN_SECRET_KEY = getEnv('ADMIN_SECRET_KEY') || DEFAULT_ADMIN_KEY;

  if (!kvUrl || !kvToken) {
    return new Response(JSON.stringify({ 
      Success: false, 
      Message: "Hệ thống lưu trữ KV chưa được cấu hình." 
    }), { status: 200, headers });
  }

  const kv = createClient({ url: kvUrl, token: kvToken });
  const LIST_KEY = 'pending_registrations';

  try {
    let action = 'get_all';
    let body: any = {};

    if (req.method === 'POST' || req.method === 'PUT') {
      try {
        body = await req.json();
        action = body.action || 'get_all';
      } catch (e) {
        action = 'get_all';
      }
    }

    // 1. DÀNH CHO TOOL REVIT: Kiểm tra bản quyền
    if (action === 'verify_license') {
      const { email, machineId, password } = body;
      const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
      const userIndex = allUsers.findIndex(u => u.email === email);
      const user = allUsers[userIndex];

      if (!user) return new Response(JSON.stringify({ Success: false, Message: "Tài khoản không tồn tại." }), { status: 200, headers });

      // Kiểm tra mật khẩu nếu có gửi lên (lúc đăng nhập mới)
      if (password && user.password !== password) {
          return new Response(JSON.stringify({ Success: false, Message: "Sai mật khẩu đăng nhập." }), { status: 200, headers });
      }

      if (!user.machineIds) user.machineIds = [];

      if (machineId) {
        if (!user.machineIds.includes(machineId)) {
          if (user.machineIds.length >= MAX_MACHINES) {
            return new Response(JSON.stringify({ 
              Success: false, 
              Message: `Tài khoản này đã đạt giới hạn ${MAX_MACHINES} thiết bị.` 
            }), { status: 200, headers });
          }
          user.machineIds.push(machineId);
          await kv.lset(LIST_KEY, userIndex, user);
        }
      }

      if (user.status !== 'active') return new Response(JSON.stringify({ Success: false, Message: "Tài khoản chưa kích hoạt hoặc bị khóa." }), { status: 200, headers });

      const isExpired = new Date(user.expirationDate) < new Date();
      if (isExpired && user.expirationDate !== '2099-12-31') {
          return new Response(JSON.stringify({ Success: false, Message: "Bản quyền đã hết hạn sử dụng." }), { status: 200, headers });
      }

      // TRẢ VỀ ĐẦY ĐỦ THÔNG TIN ĐỂ TOOL HIỂN THỊ TRÊN UI
      return new Response(JSON.stringify({ 
        Success: true, 
        User: { 
          name: user.name, 
          email: user.email,
          company: user.company || "Cá nhân",
          licenseType: user.licenseType === 'subscription' ? 'Standard' : (user.licenseType === 'perpetual' ? 'Permanent' : 'Trial'),
          createdAt: user.createdAt || "Chưa cập nhật",
          expirationDate: user.expirationDate === '2099-12-31' ? "Không giới hạn" : user.expirationDate,
          status: "Đang hoạt động",
          machineIds: user.machineIds
        } 
      }), { status: 200, headers });
    }

    // 2. DÀNH CHO ADMIN WEB
    const adminKey = req.headers.get('x-admin-key');
    if (adminKey !== ADMIN_SECRET_KEY) return new Response(JSON.stringify({ Success: false, Message: "Unauthorized" }), { status: 200, headers });

    if (action === 'get_all') {
      const data = await kv.lrange(LIST_KEY, 0, -1);
      return new Response(JSON.stringify(data || []), { status: 200, headers });
    }

    if (action === 'add_user') {
      const { user } = body;
      user.machineIds = user.machineIds || [];
      user.createdAt = user.createdAt || new Date().toISOString().split('T')[0];
      await kv.lpush(LIST_KEY, user);
      return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
    }

    if (action === 'update_user') {
      const { id, data: updateData } = body;
      const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
      const index = allUsers.findIndex(u => u.id === id);
      if (index !== -1) {
        // Cực kỳ quan trọng: Nếu mật khẩu gửi lên là rỗng, giữ lại mật khẩu cũ của user
        const oldUser = allUsers[index];
        const finalData = { ...oldUser, ...updateData };

        if (!updateData.password || updateData.password.trim() === "") {
          finalData.password = oldUser.password;
        }

        await kv.lset(LIST_KEY, index, finalData);
        return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
      }
    }

    if (action === 'delete_user') {
      const { id } = body;
      const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) as any[];
      const user = allUsers.find(u => u.id === id);
      if (user) {
        await kv.lrem(LIST_KEY, 0, user);
        return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
      }
    }

    return new Response(JSON.stringify({ Success: false, Message: "Invalid action" }), { status: 200, headers });

  } catch (err: any) {
    return new Response(JSON.stringify({ Success: false, Message: err.message }), { status: 200, headers });
  }
}

import React, { useState } from 'react';
import { User } from '../types';
import { Search, Trash2, Eye, EyeOff, X, Save, Edit3, Monitor, Laptop, Calendar, Key, UserPlus } from 'lucide-react';

interface UserManagementProps {
  users: User[];
  onAddUser: (user: User) => void;
  onEditUser: (user: User) => void;
  onUpdateStatus: (id: string, status: User['status']) => void;
  onUpdateLicenseType: (id: string, type: User['licenseType']) => void;
  onUpdateExpiration: (id: string, date: string) => void;
  onDeleteUser: (id: string) => void;
}

const INITIAL_FORM_STATE: Partial<User> = {
  name: '',
  email: '',
  password: '',
  company: '',
  licenseType: 'subscription',
  status: 'active',
  expirationDate: new Date(Date.now() + 365 * 86400000).toISOString().split('T')[0],
  createdAt: new Date().toISOString().split('T')[0],
  machineIds: [],
};

export const UserManagement: React.FC<UserManagementProps> = ({ 
  users = [], 
  onAddUser,
  onEditUser,
  onUpdateStatus, 
  onUpdateLicenseType,
  onUpdateExpiration,
  onDeleteUser 
}) => {
  const [search, setSearch] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [formData, setFormData] = useState<Partial<User>>(INITIAL_FORM_STATE);

  const handleOpenAdd = () => {
    setEditingUser(null);
    setFormData({
      ...INITIAL_FORM_STATE,
      createdAt: new Date().toISOString().split('T')[0]
    });
    setIsModalOpen(true);
  };

  const handleOpenEdit = (user: User) => {
    setEditingUser(user);
    // Khi sửa, để trống mật khẩu để Admin biết là nếu không nhập gì sẽ giữ nguyên mật khẩu cũ
    setFormData({ ...user, password: '' });
    setIsModalOpen(true);
  };

  const handleRemoveMachine = (machineId: string) => {
    if (!formData.machineIds) return;
    const newList = formData.machineIds.filter(id => id !== machineId);
    setFormData({ ...formData, machineIds: newList });
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setFormData(INITIAL_FORM_STATE);
    setShowPassword(false);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingUser) {
      const dataToSubmit = { ...formData };
      // Nếu mật khẩu để trống khi đang sửa, ta xóa nó khỏi payload gửi đi 
      // để API bên trên biết là giữ nguyên pass cũ
      if (dataToSubmit.password === '') {
        delete dataToSubmit.password;
      }
      onEditUser({ ...editingUser, ...dataToSubmit } as User);
    } else {
      const newUser: User = {
        ...formData,
        id: `U${Date.now()}`,
        lastLogin: new Date().toISOString(),
        createdAt: formData.createdAt || new Date().toISOString().split('T')[0],
        machineIds: formData.machineIds || []
      } as User;
      onAddUser(newUser);
    }
    setIsModalOpen(false);
  };

  const filtered = users.filter(u => {
    const s = search.toLowerCase();
    const matchesMachine = u.machineIds?.some(id => id.toLowerCase().includes(s));
    return (u.name || '').toLowerCase().includes(s) || 
           (u.email || '').toLowerCase().includes(s) || 
           (u.company || '').toLowerCase().includes(s) ||
           matchesMachine;
  });

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
            <h2 className="text-2xl font-bold text-slate-800">Quản lý License & Thiết bị</h2>
            <p className="text-sm text-slate-500">Thông tin người dùng sẽ được đồng bộ trực tiếp lên Tool Revit.</p>
        </div>
        <div className="flex flex-col sm:flex-row items-center gap-3 w-full md:w-auto">
          <div className="relative w-full sm:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
            <input 
              className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500 shadow-sm transition-all"
              placeholder="Tìm tên, email, machine ID..."
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
          </div>
          <button onClick={handleOpenAdd} className="w-full sm:w-auto flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-xl text-sm font-bold shadow-sm transition-all active:scale-95">
            <UserPlus className="w-4 h-4" /> Thêm người dùng
          </button>
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50/50 border-b border-slate-100 text-slate-500 font-semibold">
              <tr>
                <th className="px-6 py-4">Thông tin</th>
                <th className="px-6 py-4">Ngày ĐK</th>
                <th className="px-6 py-4">Thiết bị (ID)</th>
                <th className="px-6 py-4">Loại License</th>
                <th className="px-6 py-4">Trạng thái</th>
                <th className="px-6 py-4">Hạn dùng</th>
                <th className="px-6 py-4 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filtered.map(user => (
                <tr key={user.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-6 py-4">
                    <div className="font-bold text-slate-900">{user.name}</div>
                    <div className="text-xs text-slate-500">{user.email}</div>
                    <div className="text-[10px] text-blue-600 mt-1 uppercase font-bold">{user.company || 'CÁ NHÂN'}</div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-1.5 text-slate-600 font-medium">
                       <Calendar className="w-3.5 h-3.5 text-slate-400" />
                       {user.createdAt ? new Date(user.createdAt).toLocaleDateString('vi-VN') : '---'}
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex flex-wrap gap-1">
                      {(user.machineIds || []).length > 0 ? (
                        user.machineIds.map((mid, idx) => (
                          <div key={idx} className="text-[9px] text-blue-600 bg-blue-50 px-1.5 py-0.5 rounded flex items-center gap-1 font-mono">
                             <Laptop className="w-2.5 h-2.5" /> {mid.substring(0, 8)}...
                          </div>
                        ))
                      ) : (
                        <span className="text-[10px] text-slate-300 italic">Chưa có máy</span>
                      )}
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <select value={user.licenseType} onChange={e => onUpdateLicenseType(user.id, e.target.value as any)} className="text-[10px] font-bold px-3 py-1.5 rounded-full uppercase outline-none border-none bg-slate-100 text-slate-700">
                      <option value="subscription">Subscription</option>
                      <option value="perpetual">Perpetual</option>
                      <option value="trial">Trial</option>
                    </select>
                  </td>
                  <td className="px-6 py-4">
                    <select value={user.status} onChange={e => onUpdateStatus(user.id, e.target.value as any)} className={`text-[10px] font-bold px-3 py-1.5 rounded-full uppercase outline-none border-none ${user.status === 'active' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                      <option value="active">Active</option>
                      <option value="on_hold">Pending</option>
                      <option value="blocked">Blocked</option>
                      <option value="expired">Expired</option>
                    </select>
