import { createClient } from '@vercel/kv';

export const config = {
  runtime: 'edge',
};

const DEFAULT_ADMIN_KEY = "DSH_SECRET_2024";
const MAX_MACHINES = 4; 

const getEnv = (key: string) => process.env[key] || '';

export default async function handler(req: Request) {
  const headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, Authorization, x-admin-key',
  };

  if (req.method === 'OPTIONS') {
    return new Response(null, { status: 204, headers });
  }

  const kvUrl = getEnv('KV_REST_API_URL') || getEnv('REST_API_URL');
  const kvToken = getEnv('KV_REST_API_TOKEN') || getEnv('REST_API_TOKEN');
  const ADMIN_SECRET_KEY = getEnv('ADMIN_SECRET_KEY') || DEFAULT_ADMIN_KEY;

  if (!kvUrl || !kvToken) {
    return new Response(JSON.stringify({ 
      Success: false, 
      Message: "Hệ thống lưu trữ (KV) chưa được cấu hình trên Vercel." 
    }), { status: 200, headers });
  }

  const kv = createClient({ url: kvUrl, token: kvToken });
  const LIST_KEY = 'pending_registrations';

  try {
    let action = 'get_all';
    let body: any = {};

    if (req.method === 'POST' || req.method === 'PUT') {
      try {
        const text = await req.text();
        body = text ? JSON.parse(text) : {};
        action = body.action || 'get_all';
      } catch (e) {
        action = 'get_all';
      }
    }

    // 1. DÀNH CHO TOOL REVIT: Kiểm tra bản quyền
    if (action === 'verify_license') {
      const { email, machineId, password } = body;
      const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) || [];
      const userIndex = allUsers.findIndex((u: any) => u.email === email);
      const user = allUsers[userIndex];

      if (!user) {
        return new Response(JSON.stringify({ Success: false, Message: "Tài khoản không tồn tại." }), { status: 200, headers });
      }

      // Kiểm tra mật khẩu (nếu tool có gửi password lên)
      if (password && user.password && user.password !== password) {
          return new Response(JSON.stringify({ Success: false, Message: "Sai mật khẩu đăng nhập." }), { status: 200, headers });
      }

      if (!user.machineIds) user.machineIds = [];

      if (machineId) {
        if (!user.machineIds.includes(machineId)) {
          if (user.machineIds.length >= MAX_MACHINES) {
            return new Response(JSON.stringify({ 
              Success: false, 
              Message: `Vượt quá giới hạn ${MAX_MACHINES} máy.` 
            }), { status: 200, headers });
          }
          user.machineIds.push(machineId);
          await kv.lset(LIST_KEY, userIndex, user);
        }
      }

      if (user.status !== 'active') {
        return new Response(JSON.stringify({ Success: false, Message: "Tài khoản chưa kích hoạt hoặc bị khóa." }), { status: 200, headers });
      }

      const isExpired = new Date(user.expirationDate) < new Date();
      if (isExpired && user.expirationDate !== '2099-12-31') {
          return new Response(JSON.stringify({ Success: false, Message: "Bản quyền đã hết hạn." }), { status: 200, headers });
      }

      return new Response(JSON.stringify({ 
        Success: true, 
        User: { 
          name: user.name, 
          email: user.email,
          company: user.company || "Cá nhân",
          licenseType: user.licenseType === 'subscription' ? 'Standard' : (user.licenseType === 'perpetual' ? 'Permanent' : 'Trial'),
          createdAt: user.createdAt || "",
          expirationDate: user.expirationDate === '2099-12-31' ? "Vĩnh viễn" : user.expirationDate,
          status: "Đang hoạt động"
        } 
      }), { status: 200, headers });
    }

    // 2. DÀNH CHO ADMIN WEB
    const adminKey = req.headers.get('x-admin-key');
    if (adminKey !== ADMIN_SECRET_KEY) {
      return new Response(JSON.stringify({ Success: false, Message: "Không có quyền truy cập." }), { status: 401, headers });
    }

    if (action === 'get_all') {
      const data = await kv.lrange(LIST_KEY, 0, -1);
      return new Response(JSON.stringify(data || []), { status: 200, headers });
    }

    if (action === 'add_user') {
      const { user } = body;
      user.machineIds = user.machineIds || [];
      user.createdAt = user.createdAt || new Date().toISOString().split('T')[0];
      await kv.lpush(LIST_KEY, user);
      return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
    }

    if (action === 'update_user') {
      const { id, data: updateData } = body;
      const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) || [];
      const index = allUsers.findIndex((u: any) => u.id === id);

      if (index !== -1) {
        const oldUser = allUsers[index];
        // Merge dữ liệu, nếu password trong updateData rỗng thì dùng lại oldUser.password
        const finalUser = { ...oldUser, ...updateData };
        if (!updateData.password || updateData.password.trim() === "") {
          finalUser.password = oldUser.password;
        }

        await kv.lset(LIST_KEY, index, finalUser);
        return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
      }
    }

    if (action === 'delete_user') {
      const { id } = body;
      const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) || [];
      const userToDelete = allUsers.find((u: any) => u.id === id);
      if (userToDelete) {
        await kv.lrem(LIST_KEY, 0, userToDelete);
        return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
      }
    }

    return new Response(JSON.stringify({ Success: false, Message: "Yêu cầu không hợp lệ" }), { status: 400, headers });

  } catch (err: any) {
    console.error("API Error:", err);
    return new Response(JSON.stringify({ Success: false, Message: "Lỗi Server: " + err.message }), { status: 500, headers });
  }
}

import React, { useState, useEffect, useCallback } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { UserManagement } from './components/UserManagement';
import { SessionMonitor } from './components/SessionMonitor';
import { AiAssistant } from './components/AiAssistant';
import { IntegrationGuide } from './components/IntegrationGuide';
import { LoginScreen } from './components/LoginScreen';
import { AppView, User, Session } from './types';
import { MOCK_USERS, MOCK_SESSIONS } from './constants';
import { Menu, RefreshCw } from 'lucide-react';

const ADMIN_SECRET_KEY = "DSH_SECRET_2024";

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => {
    return localStorage.getItem('app_auth_token') === 'true';
  });

  const [currentView, setCurrentView] = useState<AppView>(() => {
    const saved = localStorage.getItem('app_current_view') as AppView;
    return Object.values(AppView).includes(saved) ? saved : AppView.DASHBOARD;
  });

  const [users, setUsers] = useState<User[]>(() => {
    const saved = localStorage.getItem('app_users_data');
    if (!saved || saved === '[]') return MOCK_USERS;
    try {
      return JSON.parse(saved);
    } catch { return MOCK_USERS; }
  });

  const [sessions, setSessions] = useState<Session[]>(() => {
    const saved = localStorage.getItem('app_sessions_data');
    if (!saved || saved === '[]') return MOCK_SESSIONS;
    try {
      return JSON.parse(saved);
    } catch { return MOCK_SESSIONS; }
  });

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'online' | 'offline' | 'error'>('online');

  useEffect(() => {
    localStorage.setItem('app_users_data', JSON.stringify(users));
  }, [users]);

  useEffect(() => {
    localStorage.setItem('app_sessions_data', JSON.stringify(sessions));
  }, [sessions]);

  useEffect(() => {
    localStorage.setItem('app_current_view', currentView);
  }, [currentView]);

  const syncFromCloud = useCallback(async (silent = false) => {
    if (!silent) setIsSyncing(true);
    try {
      const response = await fetch('/api/register', {
        method: 'GET',
        headers: { 
          'x-admin-key': ADMIN_SECRET_KEY,
          'Accept': 'application/json'
        }
      });

      const text = await response.text();
      let result;

      try {
        result = JSON.parse(text.trim());
      } catch (parseError) {
        console.error("API returned invalid JSON:", text);
        setSyncStatus('error');
        return;
      }

      if (Array.isArray(result)) {
        setSyncStatus('online');
        setUsers(result);
      } else if (result && result.Success === false) {
        console.error("Sync Error:", result.Message);
        setSyncStatus('error');
      }
    } catch (e) {
      console.error("Network error:", e);
      setSyncStatus('offline');
    } finally {
      if (!silent) setIsSyncing(false);
    }
  }, []);

  useEffect(() => {
    if (isAuthenticated) {
      syncFromCloud(true);
      const interval = setInterval(() => syncFromCloud(true), 20000);
      return () => clearInterval(interval);
    }
  }, [isAuthenticated, syncFromCloud]);

  const apiCall = async (action: string, payload: any) => {
    try {
      const response = await fetch('/api/register', {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json',
          'x-admin-key': ADMIN_SECRET_KEY
        },
        body: JSON.stringify({ action, ...payload })
      });

      const text = await response.text();
      let res;
      try {
        res = JSON.parse(text.trim());
      } catch (e) {
        return { Success: false, Message: "Phản hồi từ máy chủ không hợp lệ." };
      }

      if (res && res.Success === false) {
        alert("Thông báo: " + res.Message);
      }
      return res;
    } catch (e) {
      return { Success: false, Message: "Không thể kết nối tới máy chủ." };
    }
  };

  const handleAddUser = async (u: User) => {
    setUsers(prev => [u, ...prev]);
    await apiCall('add_user', { user: u });
    syncFromCloud(true);
  };

  const handleEditUser = async (u: User) => {
    setUsers(prev => prev.map(x => x.id === u.id ? u : x));
    await apiCall('update_user', { id: u.id, data: u });
    syncFromCloud(true);
  };

  const handleUpdateStatus = async (id: string, status: User['status']) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, status } : u));
    await apiCall('update_user', { id, data: { status } });
  };

  const handleUpdateLicenseType = async (id: string, licenseType: User['licenseType']) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, licenseType } : u));
    await apiCall('update_user', { id, data: { licenseType } });
  };

  const handleUpdateExpiration = async (id: string, expirationDate: string) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, expirationDate } : u));
    await apiCall('update_user', { id, data: { expirationDate } });
  };

  const handleDeleteUser = async (id: string) => {
    if (!window.confirm("Xác nhận xóa người dùng này khỏi hệ thống?")) return;
    setUsers(prev => prev.filter(u => u.id !== id));
    await apiCall('delete_user', { id });
  };

  if (!isAuthenticated) return <LoginScreen onLogin={() => {
    setIsAuthenticated(true);
    localStorage.setItem('app_auth_token', 'true');
  }} />;

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans">
      <Sidebar 
        currentView={currentView} 
        setCurrentView={setCurrentView} 
        isMobileOpen={isMobileMenuOpen}
        onCloseMobile={() => setIsMobileMenuOpen(false)}
        onLogout={() => {
          setIsAuthenticated(false);
          localStorage.removeItem('app_auth_token');
        }}
      />

      <main className="flex-1 flex flex-col h-full overflow-hidden">
        <header className="px-8 py-4 bg-white border-b border-slate-200 flex justify-between items-center z-10 shadow-sm">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsMobileMenuOpen(true)} className="md:hidden text-slate-600 p-1 hover:bg-slate-100 rounded"><Menu /></button>
             <div>
                <h1 className="text-xl font-bold text-slate-800 uppercase tracking-tight">
                  {currentView}
                </h1>
                <p className="text-[10px] font-bold uppercase tracking-widest flex items-center gap-1.5">
                  <span className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'online' ? 'bg-green-500' : syncStatus === 'error' ? 'bg-red-500' : 'bg-amber-500'}`}></span>
                  Status: <span className={syncStatus === 'online' ? 'text-green-500' : 'text-amber-500'}>{syncStatus.toUpperCase()}</span>
                </p>
             </div>
          </div>
          <button 
              onClick={() => syncFromCloud(false)} 
              disabled={isSyncing}
              className="p-2 hover:bg-slate-100 rounded-full transition-all disabled:opacity-50 active:scale-90"
              title="Làm mới dữ liệu"
          >
              <RefreshCw className={`w-5 h-5 text-slate-400 ${isSyncing ? 'animate-spin text-blue-500' : ''}`} />
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-8">
            {currentView === AppView.DASHBOARD && <Dashboard users={users} sessions={sessions} onUpdateStatus={handleUpdateStatus} onUpdateLicenseType={handleUpdateLicenseType} />}
            {currentView === AppView.USERS && (
              <UserManagement 
                users={users} 
                onAddUser={handleAddUser} 
                onEditUser={handleEditUser}
                onUpdateStatus={handleUpdateStatus}
                onUpdateLicenseType={handleUpdateLicenseType}
                onUpdateExpiration={handleUpdateExpiration}
                handleDeleteUser={handleDeleteUser}
              />
            )}
            {currentView === AppView.SESSIONS && <SessionMonitor sessions={sessions} users={users} onKillSession={(id) => setSessions(sessions.filter(s => s.id !== id))} onAddSession={(s) => setSessions([s, ...sessions])} />}
            {currentView === AppView.AI_INSIGHTS && <AiAssistant users={users} sessions={sessions} />}
            {currentView === AppView.INTEGRATION && <IntegrationGuide />}
        </div>
      </main>
    </div>
  );
};

