    const adminKey = req.headers.get('x-admin-key');
    if (adminKey !== ADMIN_SECRET_KEY) {
      return new Response(JSON.stringify({ Success: false, Message: "Unauthorized" }), { status: 401, headers });
    }

    if (action === 'get_all') {
      const data = (await kv.lrange(LIST_KEY, 0, -1)) || [];
      return new Response(JSON.stringify(data), { status: 200, headers });
    }

    if (action === 'add_user') {
      const { user } = body;
      user.machineIds = user.machineIds || [];
      user.createdAt = user.createdAt || new Date().toISOString().split('T')[0];
      await kv.lpush(LIST_KEY, user);
      return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
    }

    if (action === 'update_user') {
      const { id, data: updateData } = body;
      const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) || [];
      const index = allUsers.findIndex((u: any) => u.id === id);

      if (index !== -1) {
        const oldUser = allUsers[index];
        const finalUser = { ...oldUser, ...updateData };
        if (!updateData.password || updateData.password.trim() === "") {
          finalUser.password = oldUser.password;
        }
        await kv.lset(LIST_KEY, index, finalUser);
        return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
      }
    }

    if (action === 'delete_user') {
      const { id } = body;
      const allUsers = (await kv.lrange(LIST_KEY, 0, -1)) || [];
      const userToDelete = allUsers.find((u: any) => u.id === id);
      if (userToDelete) {
        await kv.lrem(LIST_KEY, 0, userToDelete);
        return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
      }
    }

    return new Response(JSON.stringify({ Success: false, Message: "Invalid Action" }), { status: 400, headers });

  } catch (err: any) {
    return new Response(JSON.stringify({ Success: false, Message: err.message }), { status: 500, headers });
  }
}

import React, { useState } from 'react';
import { User } from '../types';
import { Search, Trash2, Eye, EyeOff, X, Save, Edit3, Monitor, Laptop, Calendar, Key, UserPlus } from 'lucide-react';

interface UserManagementProps {
  users: User[];
  onAddUser: (user: User) => void;
  onEditUser: (user: User) => void;
  onUpdateStatus: (id: string, status: User['status']) => void;
  onUpdateLicenseType: (id: string, type: User['licenseType']) => void;
  onUpdateExpiration: (id: string, date: string) => void;
  onDeleteUser: (id: string) => void;
}

const INITIAL_FORM_STATE: Partial<User> = {
  name: '',
  email: '',
  password: '',
  company: '',
  licenseType: 'subscription',
  status: 'active',
  expirationDate: new Date(Date.now() + 365 * 86400000).toISOString().split('T')[0],
  createdAt: new Date().toISOString().split('T')[0],
  machineIds: [],
};

export const UserManagement: React.FC<UserManagementProps> = ({ 
  users = [], 
  onAddUser,
  onEditUser,
  onUpdateStatus, 
  onUpdateLicenseType,
  onUpdateExpiration,
  onDeleteUser 
}) => {
  const [search, setSearch] = useState('');
  const [visiblePasswords, setVisiblePasswords] = useState<Record<string, boolean>>({});
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [formData, setFormData] = useState<Partial<User>>(INITIAL_FORM_STATE);
  const [showFormPassword, setShowFormPassword] = useState(false);

  const togglePasswordVisibility = (userId: string) => {
    setVisiblePasswords(prev => ({
      ...prev,
      [userId]: !prev[userId]
    }));
  };

  const handleOpenAdd = () => {
    setEditingUser(null);
    setFormData({
      ...INITIAL_FORM_STATE,
      createdAt: new Date().toISOString().split('T')[0]
    });
    setIsModalOpen(true);
  };

  const handleOpenEdit = (user: User) => {
    setEditingUser(user);
    setFormData({ ...user, password: '' });
    setIsModalOpen(true);
  };

  const handleRemoveMachine = (machineId: string) => {
    if (!formData.machineIds) return;
    const newList = formData.machineIds.filter(id => id !== machineId);
    setFormData({ ...formData, machineIds: newList });
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setFormData(INITIAL_FORM_STATE);
    setShowFormPassword(false);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingUser) {
      const dataToSubmit = { ...formData };
      if (dataToSubmit.password === '') {
        delete dataToSubmit.password;
      }
      onEditUser({ ...editingUser, ...dataToSubmit } as User);
    } else {
      const newUser: User = {
        ...formData,
        id: `U${Date.now()}`,
        lastLogin: new Date().toISOString(),
        createdAt: formData.createdAt || new Date().toISOString().split('T')[0],
        machineIds: formData.machineIds || []
      } as User;
      onAddUser(newUser);
    }
    setIsModalOpen(false);
  };

  const filtered = users.filter(u => {
    const s = search.toLowerCase();
    return (u.name || '').toLowerCase().includes(s) || 
           (u.email || '').toLowerCase().includes(s) || 
           (u.company || '').toLowerCase().includes(s) ||
           (u.machineIds || []).some(id => id.toLowerCase().includes(s));
  });

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
            <h2 className="text-2xl font-bold text-slate-800">Quản lý License</h2>
            <p className="text-sm text-slate-500">Thông tin người dùng và mã máy Revit.</p>
        </div>
        <div className="flex flex-col sm:flex-row items-center gap-3 w-full md:w-auto">
          <div className="relative w-full sm:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
            <input 
              className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500 shadow-sm transition-all"
              placeholder="Tìm tên, email, machine ID..."
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
          </div>
          <button onClick={handleOpenAdd} className="w-full sm:w-auto flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-xl text-sm font-bold shadow-sm transition-all active:scale-95">
            <UserPlus className="w-4 h-4" /> Thêm mới
          </button>
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50/50 border-b border-slate-100 text-slate-500 font-semibold">
              <tr>
                <th className="px-6 py-4">Người dùng</th>
                <th className="px-6 py-4">Mật khẩu</th>
                <th className="px-6 py-4">Máy (HWID)</th>
                <th className="px-6 py-4">Loại</th>
                <th className="px-6 py-4">Trạng thái</th>
                <th className="px-6 py-4">Hết hạn</th>
                <th className="px-6 py-4 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filtered.map(user => (
                <tr key={user.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-6 py-4">
                    <div className="font-bold text-slate-900">{user.name}</div>
                    <div className="text-[11px] text-slate-500">{user.email}</div>
                    <div className="text-[10px] text-blue-600 mt-1 uppercase font-bold">{user.company || 'Cá nhân'}</div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-2">
                      <span className="font-mono text-slate-600 min-w-[60px]">
                        {visiblePasswords[user.id] ? user.password : '••••••••'}
                      </span>
                      <button 
                        onClick={() => togglePasswordVisibility(user.id)}
                        className="p-1 hover:bg-slate-200 rounded text-slate-400"
                      >
                        {visiblePasswords[user.id] ? <EyeOff className="w-3.5 h-3.5" /> : <Eye className="w-3.5 h-3.5" />}
                      </button>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex flex-wrap gap-1 max-w-[150px]">
                      {(user.machineIds || []).length > 0 ? (
                        user.machineIds.map((mid, idx) => (
                          <div key={idx} title={mid} className="text-[9px] text-blue-600 bg-blue-50 px-1.5 py-0.5 rounded border border-blue-100 font-mono">
                             {mid.substring(0, 6)}...
                          </div>
                        ))
                      ) : (
                        <span className="text-[10px] text-slate-300 italic">Trống</span>
                      )}
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <select value={user.licenseType} onChange={e => onUpdateLicenseType(user.id, e.target.value as any)} className="text-[10px] font-bold px-2 py-1 rounded bg-slate-100 text-slate-700 border-none outline-none">
                      <option value="subscription">SUB</option>
                      <option value="perpetual">PERM</option>
                      <option value="trial">TRIAL</option>
                    </select>
                  </td>
                  <td className="px-6 py-4">
                    <select value={user.status} onChange={e => onUpdateStatus(user.id, e.target.value as any)} className={`text-[10px] font-bold px-2 py-1 rounded border-none outline-none ${user.status === 'active' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                      <option value="active">ACTIVE</option>
                      <option value="on_hold">PENDING</option>
                      <option value="blocked">BLOCK</option>
                    </select>
                  </td>
                  <td className="px-6 py-4">
                    <input type="date" value={user.expirationDate} onChange={(e) => onUpdateExpiration(user.id, e.target.value)} className="bg-transparent border-none text-xs font-medium w-28 p-0" />
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={() => handleOpenEdit(user)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg"><Edit3 className="w-4 h-4" /></button>
                      <button onClick={() => onDeleteUser(user.id)} className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg"><Trash2 className="w-4 h-4" /></button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* MODAL THÊM / SỬA */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in">
          <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-slate-800">{editingUser ? 'Cập nhật tài khoản' : 'Tạo tài khoản mới'}</h3>
              <button onClick={handleCloseModal} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X className="w-5 h-5" /></button>
            </div>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Họ tên</label>
                  <input className="w-full px-3 py-2 border border-slate-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-500" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} required />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Email</label>
                  <input className="w-full px-3 py-2 border border-slate-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-500" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} required />
                </div>
              </div>

              <div className="relative">
                <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Mật khẩu</label>
                <div className="relative">
                  <Key className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                  <input 
                    type={showFormPassword ? "text" : "password"}
                    className="w-full pl-10 pr-10 py-2 border border-slate-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                    placeholder={editingUser ? "Để trống nếu giữ nguyên" : "Nhập mật khẩu..."}
                    value={formData.password}
                    onChange={e => setFormData({...formData, password: e.target.value})}
                    required={!editingUser}
                  />
                  <button type="button" onClick={() => setShowFormPassword(!showFormPassword)} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400">
                    {showFormPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                  </button>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Công ty</label>
                  <input className="w-full px-3 py-2 border border-slate-200 rounded-lg" value={formData.company} onChange={e => setFormData({...formData, company: e.target.value})} />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Ngày đăng ký</label>
                  <input type="date" className="w-full px-3 py-2 border border-slate-200 rounded-lg" value={formData.createdAt} onChange={e => setFormData({...formData, createdAt: e.target.value})} />
                </div>
              </div>

              <div className="p-3 bg-slate-50 rounded-xl border border-slate-200">
                 <label className="text-[10px] font-bold text-slate-700 uppercase mb-2 block flex items-center gap-1.5"><Monitor className="w-3 h-3"/> Máy đang liên kết ({(formData.machineIds || []).length}/4)</label>
                 <div className="space-y-1">
                    {(formData.machineIds || []).map((mid, idx) => (
                      <div key={idx} className="flex items-center justify-between bg-white p-1.5 rounded border text-[10px] font-mono">
                        <span className="truncate max-w-[200px]">{mid}</span>
                        <button type="button" onClick={() => handleRemoveMachine(mid)} className="text-red-400 hover:text-red-600 flex-none ml-2"><Trash2 className="w-3 h-3"/></button>
                      </div>
                    ))}
                    {(formData.machineIds || []).length === 0 && <p className="text-[10px] text-slate-400 italic">Chưa có máy nào.</p>}
                 </div>
              </div>

              <div className="flex justify-end gap-3 pt-4 border-t border-slate-100">
                <button type="button" onClick={handleCloseModal} className="px-4 py-2 text-sm font-bold text-slate-500">Hủy</button>
                <button type="submit" className="px-6 py-2 bg-blue-600 text-white rounded-lg font-bold text-sm shadow-lg hover:bg-blue-700 transition-all">
                  <Save className="w-4 h-4 inline-block mr-2" /> {editingUser ? 'Cập nhật' : 'Tạo mới'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { UserManagement } from './components/UserManagement';
import { SessionMonitor } from './components/SessionMonitor';
import { AiAssistant } from './components/AiAssistant';
import { IntegrationGuide } from './components/IntegrationGuide';
import { LoginScreen } from './components/LoginScreen';
import { AppView, User, Session } from './types';
import { MOCK_USERS, MOCK_SESSIONS } from './constants';
import { Menu, RefreshCw } from 'lucide-react';

const ADMIN_SECRET_KEY = "DSH_SECRET_2024";

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => {
    return localStorage.getItem('app_auth_token') === 'true';
  });

  const [currentView, setCurrentView] = useState<AppView>(() => {
    const saved = localStorage.getItem('app_current_view') as AppView;
    return Object.values(AppView).includes(saved) ? saved : AppView.DASHBOARD;
  });

  const [users, setUsers] = useState<User[]>(() => {
    const saved = localStorage.getItem('app_users_data');
    if (!saved || saved === '[]') return MOCK_USERS;
    try {
      return JSON.parse(saved);
    } catch { return MOCK_USERS; }
  });

  const [sessions, setSessions] = useState<Session[]>(() => {
    const saved = localStorage.getItem('app_sessions_data');
    if (!saved || saved === '[]') return MOCK_SESSIONS;
    try {
      return JSON.parse(saved);
    } catch { return MOCK_SESSIONS; }
  });

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'online' | 'offline' | 'error'>('online');

  useEffect(() => {
    localStorage.setItem('app_users_data', JSON.stringify(users));
  }, [users]);

  useEffect(() => {
    localStorage.setItem('app_sessions_data', JSON.stringify(sessions));
  }, [sessions]);

  useEffect(() => {
    localStorage.setItem('app_current_view', currentView);
  }, [currentView]);

  const syncFromCloud = useCallback(async (silent = false) => {
    if (!silent) setIsSyncing(true);
    try {
      const response = await fetch('/api/register', {
        method: 'GET',
        headers: { 
          'x-admin-key': ADMIN_SECRET_KEY,
          'Accept': 'application/json'
        }
      });

      const rawText = await response.text();
      const cleanedText = rawText.trim();

      if (!cleanedText) {
        if (!silent) console.warn("API returned empty response");
        return;
      }

      let result;
      try {
        result = JSON.parse(cleanedText);
      } catch (parseError) {
        console.error("Malformed JSON:", cleanedText);
        setSyncStatus('error');
        return;
      }

      if (Array.isArray(result)) {
        setSyncStatus('online');
        setUsers(result);
      }
    } catch (e) {
      console.error("Network error:", e);
      setSyncStatus('offline');
    } finally {
      if (!silent) setIsSyncing(false);
    }
  }, []);

  useEffect(() => {
    if (isAuthenticated) {
      syncFromCloud(true);
      const interval = setInterval(() => syncFromCloud(true), 30000);
      return () => clearInterval(interval);
    }
  }, [isAuthenticated, syncFromCloud]);

  const apiCall = async (action: string, payload: any) => {
    try {
      const response = await fetch('/api/register', {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json',
          'x-admin-key': ADMIN_SECRET_KEY
        },
        body: JSON.stringify({ action, ...payload })
      });

      const rawText = await response.text();
      const cleanedText = rawText.trim();

      if (!cleanedText) return { Success: false, Message: "Không có phản hồi từ máy chủ." };

      let res;
      try {
        res = JSON.parse(cleanedText);
      } catch (e) {
        return { Success: false, Message: "Lỗi cấu trúc dữ liệu từ máy chủ." };
      }

      if (res && res.Success === false) {
        alert("Thông báo: " + res.Message);
      }
      return res;
    } catch (e) {
      return { Success: false, Message: "Không thể kết nối tới máy chủ." };
    }
  };

  const handleAddUser = async (u: User) => {
    setUsers(prev => [u, ...prev]);
    await apiCall('add_user', { user: u });
    syncFromCloud(true);
  };

  const handleEditUser = async (u: User) => {
    setUsers(prev => prev.map(x => x.id === u.id ? u : x));
    await apiCall('update_user', { id: u.id, data: u });
    syncFromCloud(true);
  };

  const handleUpdateStatus = async (id: string, status: User['status']) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, status } : u));
    await apiCall('update_user', { id, data: { status } });
  };

  const handleUpdateLicenseType = async (id: string, licenseType: User['licenseType']) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, licenseType } : u));
    await apiCall('update_user', { id, data: { licenseType } });
  };

  const handleUpdateExpiration = async (id: string, expirationDate: string) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, expirationDate } : u));
    await apiCall('update_user', { id, data: { expirationDate } });
  };

  const handleDeleteUser = async (id: string) => {
    if (!window.confirm("Xác nhận xóa người dùng này?")) return;
    setUsers(prev => prev.filter(u => u.id !== id));
    await apiCall('delete_user', { id });
  };

  if (!isAuthenticated) return <LoginScreen onLogin={() => {
    setIsAuthenticated(true);
    localStorage.setItem('app_auth_token', 'true');
  }} />;

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans">
      <Sidebar 
        currentView={currentView} 
        setCurrentView={setCurrentView} 
        isMobileOpen={isMobileMenuOpen}
        onCloseMobile={() => setIsMobileMenuOpen(false)}
        onLogout={() => {
          setIsAuthenticated(false);
          localStorage.removeItem('app_auth_token');
        }}
      />

      <main className="flex-1 flex flex-col h-full overflow-hidden">
        <header className="px-8 py-4 bg-white border-b border-slate-200 flex justify-between items-center z-10 shadow-sm">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsMobileMenuOpen(true)} className="md:hidden text-slate-600 p-1 hover:bg-slate-100 rounded"><Menu /></button>
             <div>
                <h1 className="text-xl font-bold text-slate-800 uppercase tracking-tight">
                  {currentView}
                </h1>
                <p className="text-[10px] font-bold uppercase tracking-widest flex items-center gap-1.5">
                  <span className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'online' ? 'bg-green-500' : syncStatus === 'error' ? 'bg-red-500' : 'bg-amber-500'}`}></span>
                  Status: <span className={syncStatus === 'online' ? 'text-green-500' : 'text-amber-500'}>{syncStatus.toUpperCase()}</span>
                </p>
             </div>
          </div>
          <button 
              onClick={() => syncFromCloud(false)} 
              disabled={isSyncing}
              className="p-2 hover:bg-slate-100 rounded-full transition-all disabled:opacity-50 active:scale-90"
          >
              <RefreshCw className={`w-5 h-5 text-slate-400 ${isSyncing ? 'animate-spin text-blue-500' : ''}`} />
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-8">
            {currentView === AppView.DASHBOARD && <Dashboard users={users} sessions={sessions} onUpdateStatus={handleUpdateStatus} onUpdateLicenseType={handleUpdateLicenseType} />}
            {currentView === AppView.USERS && (
              <UserManagement 
                users={users} 
                onAddUser={handleAddUser} 
                onEditUser={handleEditUser}
                onUpdateStatus={handleUpdateStatus}
                onUpdateLicenseType={handleUpdateLicenseType}
                onUpdateExpiration={handleUpdateExpiration}
                onDeleteUser={handleDeleteUser}
              />
            )}
            {currentView === AppView.SESSIONS && <SessionMonitor sessions={sessions} users={users} onKillSession={(id) => setSessions(sessions.filter(s => s.id !== id))} onAddSession={(s) => setSessions([s, ...sessions])} />}
            {currentView === AppView.AI_INSIGHTS && <AiAssistant users={users} sessions={sessions} />}
            {currentView === AppView.INTEGRATION && <IntegrationGuide />}
        </div>
      </main>
    </div>
  );
};

