  }

  const kvUrl = getEnv('KV_REST_API_URL') || getEnv('REST_API_URL');
  const kvToken = getEnv('KV_REST_API_TOKEN') || getEnv('REST_API_TOKEN');
  const ADMIN_SECRET_KEY = getEnv('ADMIN_SECRET_KEY') || DEFAULT_ADMIN_KEY;

  if (!kvUrl || !kvToken) {
    return new Response(JSON.stringify({ 
      Success: false, 
      Message: "Hệ thống KV chưa được cấu hình. Vui lòng kiểm tra biến môi trường KV_REST_API_URL và KV_REST_API_TOKEN." 
    }), { status: 200, headers });
  }

  const kv = createClient({ url: kvUrl, token: kvToken });
  const LIST_KEY = 'pending_registrations';

  try {
    let action = 'get_all';
    let body: any = {};

    if (req.method === 'POST' || req.method === 'PUT') {
      try {
        const text = await req.text();
        if (text) {
          body = JSON.parse(text.trim());
          action = body.action || 'get_all';
        }
      } catch (e) {
        return new Response(JSON.stringify({ Success: false, Message: "Dữ liệu JSON không hợp lệ" }), { status: 400, headers });
      }
    }

    // Hàm tiện ích để lấy và parse danh sách người dùng an toàn
    const getAllUsers = async (): Promise<UserData[]> => {
      const raw = await kv.lrange(LIST_KEY, 0, -1);
      if (!raw) return [];
      // Vercel KV đôi khi trả về object trực tiếp, đôi khi trả về chuỗi JSON tùy môi trường/driver
      return raw.map((item: any) => {
        if (typeof item === 'string') {
          try { return JSON.parse(item); } catch { return null; }
        }
        return item;
      }).filter((item: any) => item !== null) as UserData[];
    };

    // 1. DÀNH CHO TOOL REVIT: Kiểm tra bản quyền
    if (action === 'verify_license') {
      const { email, machineId, password } = body;
      const allUsers = await getAllUsers();
      const userIndex = allUsers.findIndex((u) => u.email === email);
      const user = allUsers[userIndex];

      if (!user) {
        return new Response(JSON.stringify({ Success: false, Message: "Tài khoản không tồn tại." }), { status: 200, headers });
      }

      if (password && user.password && user.password !== password) {
          return new Response(JSON.stringify({ Success: false, Message: "Sai mật khẩu đăng nhập." }), { status: 200, headers });
      }

      const currentMachineIds = user.machineIds || [];

      if (machineId) {
        if (!currentMachineIds.includes(machineId)) {
          if (currentMachineIds.length >= MAX_MACHINES) {
            return new Response(JSON.stringify({ 
              Success: false, 
              Message: `Vượt quá giới hạn ${MAX_MACHINES} máy.` 
            }), { status: 200, headers });
          }
          const updatedUser = { ...user, machineIds: [...currentMachineIds, machineId] };
          await kv.lset(LIST_KEY, userIndex, updatedUser);
        }
      }

      if (user.status !== 'active') {
        return new Response(JSON.stringify({ Success: false, Message: "Tài khoản chưa kích hoạt hoặc đã bị khóa." }), { status: 200, headers });
      }

      const isExpired = new Date(user.expirationDate) < new Date();
      if (isExpired && user.expirationDate !== '2099-12-31') {
          return new Response(JSON.stringify({ Success: false, Message: "Bản quyền đã hết hạn." }), { status: 200, headers });
      }

      return new Response(JSON.stringify({ 
        Success: true, 
        User: { 
          name: user.name, 
          email: user.email,
          company: user.company || "Cá nhân",
          licenseType: user.licenseType,
          createdAt: user.createdAt || "",
          expirationDate: user.expirationDate === '2099-12-31' ? "Vĩnh viễn" : user.expirationDate,
          status: "Đang hoạt động"
        } 
      }), { status: 200, headers });
    }

    // 2. DÀNH CHO ADMIN WEB: Kiểm tra Admin Key
    const adminKey = req.headers.get('x-admin-key');
    if (adminKey !== ADMIN_SECRET_KEY) {
      return new Response(JSON.stringify({ 
        Success: false, 
        Message: `Từ chối truy cập (Admin Key sai). Key nhận được: ${adminKey?.substring(0,3)}...` 
      }), { status: 401, headers });
    }

    if (action === 'get_all') {
      const data = await getAllUsers();
      return new Response(JSON.stringify(data), { status: 200, headers });
    }

    if (action === 'add_user') {
      const { user } = body;
      const newUser = { ...(user as UserData) };
      newUser.machineIds = newUser.machineIds || [];
      newUser.createdAt = newUser.createdAt || new Date().toISOString().split('T')[0];
      await kv.lpush(LIST_KEY, newUser);
      return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
    }

    if (action === 'update_user') {
      const { id, data: updateData } = body;
      const allUsers = await getAllUsers();
      const index = allUsers.findIndex((u) => u.id === id);

      if (index !== -1) {
        const oldUser = allUsers[index];
        const finalUser = { ...oldUser, ...updateData };

        // Bảo vệ mật khẩu nếu updateData không chứa pass mới
        if (!updateData.password || updateData.password.trim() === "") {
          finalUser.password = oldUser.password;
        }

        await kv.lset(LIST_KEY, index, finalUser);
        return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
      }
      return new Response(JSON.stringify({ Success: false, Message: "Không tìm thấy User" }), { status: 404, headers });
    }

    if (action === 'delete_user') {
      const { id } = body;
      const allUsers = await getAllUsers();
      const userToDelete = allUsers.find((u) => u.id === id);
      if (userToDelete) {
        await kv.lrem(LIST_KEY, 0, userToDelete);
        return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
      }
    }

    return new Response(JSON.stringify({ Success: false, Message: "Hành động không hợp lệ" }), { status: 400, headers });

  } catch (err: any) {
    console.error("API Error:", err);
    return new Response(JSON.stringify({ Success: false, Message: "Lỗi Server nội bộ: " + err.message }), { status: 500, headers });
  }
}

