    let action = url.searchParams.get('action') || 'get_all';
    let body: any = {};

    if (req.method === 'POST' || req.method === 'PUT') {
      try {
        const text = await req.text();
        if (text) {
          body = JSON.parse(text.trim());
          action = body.action || action;
        }
      } catch (e) {
        // Nếu không parse được body, vẫn giữ action từ URL
      }
    }

    const getAllUsers = async (): Promise<UserData[]> => {
      const raw = await kv.lrange(LIST_KEY, 0, -1);
      if (!raw) return [];
      return raw.map((item: any) => {
        if (typeof item === 'string') {
          try { return JSON.parse(item); } catch { return null; }
        }
        return item;
      }).filter((item: any) => item !== null) as UserData[];
    };

    // 1. DÀNH CHO TOOL REVIT: Kiểm tra bản quyền (Không cần Admin Key)
    if (action === 'verify_license') {
      const { email, machineId, password } = body;
      const allUsers = await getAllUsers();
      const userIndex = allUsers.findIndex((u) => u.email === email);
      const user = allUsers[userIndex];

      if (!user) {
        return new Response(JSON.stringify({ Success: false, Message: "Tài khoản không tồn tại." }), { status: 200, headers });
      }

      if (password && user.password && user.password !== password) {
          return new Response(JSON.stringify({ Success: false, Message: "Sai mật khẩu đăng nhập." }), { status: 200, headers });
      }

      const currentMachineIds = user.machineIds || [];
      if (machineId && !currentMachineIds.includes(machineId)) {
        if (currentMachineIds.length >= MAX_MACHINES) {
          return new Response(JSON.stringify({ Success: false, Message: `Vượt quá giới hạn ${MAX_MACHINES} máy.` }), { status: 200, headers });
        }
        const updatedUser = { ...user, machineIds: [...currentMachineIds, machineId] };
        await kv.lset(LIST_KEY, userIndex, updatedUser);
      }

      if (user.status !== 'active') {
        return new Response(JSON.stringify({ Success: false, Message: "Tài khoản chưa kích hoạt hoặc bị khóa." }), { status: 200, headers });
      }

      const isExpired = new Date(user.expirationDate) < new Date();
      if (isExpired && user.expirationDate !== '2099-12-31') {
          return new Response(JSON.stringify({ Success: false, Message: "Bản quyền đã hết hạn." }), { status: 200, headers });
      }

      return new Response(JSON.stringify({ 
        Success: true, 
        User: { 
          name: user.name, 
          email: user.email,
          company: user.company || "Cá nhân",
          licenseType: user.licenseType,
          createdAt: user.createdAt || "",
          expirationDate: user.expirationDate === '2099-12-31' ? "Vĩnh viễn" : user.expirationDate,
          status: "Đang hoạt động"
        } 
      }), { status: 200, headers });
    }

    // 2. DÀNH CHO ADMIN WEB: Kiểm tra Admin Key đa phương thức
    // Thử lấy từ Header tùy chỉnh, Header Authorization chuẩn, hoặc Query String
    const authHeader = req.headers.get('Authorization')?.replace('Bearer ', '');
    const customHeader = req.headers.get('x-admin-key');
    const queryKey = url.searchParams.get('key');

    const providedKey = authHeader || customHeader || queryKey;

    if (providedKey !== ADMIN_SECRET_KEY) {
      return new Response(JSON.stringify({ 
        Success: false, 
        Message: `Từ chối truy cập (Admin Key sai).`,
        Debug: providedKey ? "Key không khớp" : "Không tìm thấy Key trong Header/URL"
      }), { status: 401, headers });
    }

    // Các hành động quản trị
    if (action === 'get_all') {
      const data = await getAllUsers();
      return new Response(JSON.stringify(data), { status: 200, headers });
    }

    if (action === 'add_user') {
      const { user } = body;
      const newUser = { ...(user as UserData) };
      newUser.machineIds = newUser.machineIds || [];
      newUser.createdAt = newUser.createdAt || new Date().toISOString().split('T')[0];
      await kv.lpush(LIST_KEY, newUser);
      return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
    }

    if (action === 'update_user') {
      const { id, data: updateData } = body;
      const allUsers = await getAllUsers();
      const index = allUsers.findIndex((u) => u.id === id);

      if (index !== -1) {
        const oldUser = allUsers[index];
        const finalUser = { ...oldUser, ...updateData };
        if (!updateData.password || updateData.password.trim() === "") {
          finalUser.password = oldUser.password;
        }
        await kv.lset(LIST_KEY, index, finalUser);
        return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
      }
      return new Response(JSON.stringify({ Success: false, Message: "Không tìm thấy User" }), { status: 404, headers });
    }

    if (action === 'delete_user') {
      const { id } = body;
      const allUsers = await getAllUsers();
      const userToDelete = allUsers.find((u) => u.id === id);
      if (userToDelete) {
        await kv.lrem(LIST_KEY, 0, userToDelete);
        return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
      }
    }

    return new Response(JSON.stringify({ Success: false, Message: "Hành động không hợp lệ" }), { status: 400, headers });

  } catch (err: any) {
    return new Response(JSON.stringify({ Success: false, Message: "Lỗi hệ thống: " + err.message }), { status: 500, headers });
  }
}

import React, { useState, useEffect, useCallback } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { UserManagement } from './components/UserManagement';
import { SessionMonitor } from './components/SessionMonitor';
import { AiAssistant } from './components/AiAssistant';
import { IntegrationGuide } from './components/IntegrationGuide';
import { LoginScreen } from './components/LoginScreen';
import { AppView, User, Session } from './types';
import { MOCK_USERS, MOCK_SESSIONS } from './constants';
import { Menu, RefreshCw } from 'lucide-react';

const ADMIN_SECRET_KEY = "DSH_SECRET_2024";

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => {
    return localStorage.getItem('app_auth_token') === 'true';
  });

  const [currentView, setCurrentView] = useState<AppView>(() => {
    const saved = localStorage.getItem('app_current_view') as AppView;
    return Object.values(AppView).includes(saved) ? saved : AppView.DASHBOARD;
  });

  const [users, setUsers] = useState<User[]>(() => {
    const saved = localStorage.getItem('app_users_data');
    if (!saved || saved === '[]') return MOCK_USERS;
    try {
      return JSON.parse(saved);
    } catch { return MOCK_USERS; }
  });

  const [sessions, setSessions] = useState<Session[]>(() => {
    const saved = localStorage.getItem('app_sessions_data');
    if (!saved || saved === '[]') return MOCK_SESSIONS;
    try {
      return JSON.parse(saved);
    } catch { return MOCK_SESSIONS; }
  });

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'online' | 'offline' | 'error'>('online');

  useEffect(() => {
    localStorage.setItem('app_users_data', JSON.stringify(users));
  }, [users]);

  useEffect(() => {
    localStorage.setItem('app_sessions_data', JSON.stringify(sessions));
  }, [sessions]);

  useEffect(() => {
    localStorage.setItem('app_current_view', currentView);
  }, [currentView]);

  const syncFromCloud = useCallback(async (silent = false) => {
    if (!silent) setIsSyncing(true);
    try {
      // Gửi key qua cả header và query string để đảm bảo an toàn
      const response = await fetch(`/api/register?key=${ADMIN_SECRET_KEY}&action=get_all`, {
        method: 'GET',
        headers: { 
          'Authorization': `Bearer ${ADMIN_SECRET_KEY}`,
          'x-admin-key': ADMIN_SECRET_KEY,
          'Accept': 'application/json'
        }
      });

      if (!response.ok) {
        setSyncStatus('error');
        return;
      }

      const rawText = await response.text();
      const cleanedText = rawText.trim();
      if (!cleanedText) return;

      let result;
      try {
        result = JSON.parse(cleanedText);
      } catch (e) {
        setSyncStatus('error');
        return;
      }

      if (Array.isArray(result)) {
        setSyncStatus('online');
        setUsers(result);
      }
    } catch (e) {
      setSyncStatus('offline');
    } finally {
      if (!silent) setIsSyncing(false);
    }
  }, []);

  useEffect(() => {
    if (isAuthenticated) {
      syncFromCloud(true);
      const interval = setInterval(() => syncFromCloud(true), 30000);
      return () => clearInterval(interval);
    }
  }, [isAuthenticated, syncFromCloud]);

  const apiCall = async (action: string, payload: any) => {
    try {
      const response = await fetch(`/api/register?key=${ADMIN_SECRET_KEY}`, {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${ADMIN_SECRET_KEY}`,
          'x-admin-key': ADMIN_SECRET_KEY
        },
        body: JSON.stringify({ action, ...payload })
      });

      if (!response.ok) {
        const errTxt = await response.text();
        console.error("API Error Response:", errTxt);
        return { Success: false, Message: `Lỗi Server (${response.status})` };
      }

      const rawText = await response.text();
      const res = JSON.parse(rawText.trim());

      if (res && res.Success === false) {
        alert("Lỗi: " + res.Message);
      }
      return res;
    } catch (e) {
      return { Success: false, Message: "Không thể kết nối tới Server" };
    }
  };

  const handleAddUser = async (u: User) => {
    setUsers(prev => [u, ...prev]);
    const res = await apiCall('add_user', { user: u });
    if (res?.Success) syncFromCloud(true);
  };

  const handleEditUser = async (u: User) => {
    setUsers(prev => prev.map(x => x.id === u.id ? u : x));
    const res = await apiCall('update_user', { id: u.id, data: u });
    if (res?.Success) syncFromCloud(true);
  };

  const handleUpdateStatus = async (id: string, status: User['status']) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, status } : u));
    await apiCall('update_user', { id, data: { status } });
  };

  const handleUpdateLicenseType = async (id: string, licenseType: User['licenseType']) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, licenseType } : u));
    await apiCall('update_user', { id, data: { licenseType } });
  };

  const handleUpdateExpiration = async (id: string, expirationDate: string) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, expirationDate } : u));
    await apiCall('update_user', { id, data: { expirationDate } });
  };

  const handleDeleteUser = async (id: string) => {
    if (!window.confirm("Xác nhận xóa vĩnh viễn người dùng này?")) return;
    setUsers(prev => prev.filter(u => u.id !== id));
    await apiCall('delete_user', { id });
  };

  if (!isAuthenticated) return <LoginScreen onLogin={() => {
    setIsAuthenticated(true);
    localStorage.setItem('app_auth_token', 'true');
  }} />;

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans">
      <Sidebar 
        currentView={currentView} 
        setCurrentView={setCurrentView} 
        isMobileOpen={isMobileMenuOpen}
        onCloseMobile={() => setIsMobileMenuOpen(false)}
        onLogout={() => {
          setIsAuthenticated(false);
          localStorage.removeItem('app_auth_token');
        }}
      />

      <main className="flex-1 flex flex-col h-full overflow-hidden">
        <header className="px-8 py-4 bg-white border-b border-slate-200 flex justify-between items-center z-10 shadow-sm">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsMobileMenuOpen(true)} className="md:hidden text-slate-600 p-1 hover:bg-slate-100 rounded"><Menu /></button>
             <div>
                <h1 className="text-xl font-bold text-slate-800 uppercase tracking-tight">
                  {currentView}
                </h1>
                <p className="text-[10px] font-bold uppercase tracking-widest flex items-center gap-1.5">
                  <span className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'online' ? 'bg-green-500' : syncStatus === 'error' ? 'bg-red-500' : 'bg-amber-500'}`}></span>
                  Hệ thống: <span className={syncStatus === 'online' ? 'text-green-500' : syncStatus === 'error' ? 'text-red-500' : 'text-amber-500'}>
                    {syncStatus === 'online' ? 'TRỰC TUYẾN' : syncStatus === 'error' ? 'LỖI KẾT NỐI' : 'NGOẠI TUYẾN'}
                  </span>
                </p>
             </div>
          </div>
          <button 
              onClick={() => syncFromCloud(false)} 
              disabled={isSyncing}
              className="p-2 hover:bg-slate-100 rounded-full transition-all disabled:opacity-50 active:scale-90 flex items-center gap-2"
          >
              <RefreshCw className={`w-5 h-5 text-slate-400 ${isSyncing ? 'animate-spin text-blue-500' : ''}`} />
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-8">
            {currentView === AppView.DASHBOARD && <Dashboard users={users} sessions={sessions} onUpdateStatus={handleUpdateStatus} onUpdateLicenseType={handleUpdateLicenseType} />}
            {currentView === AppView.USERS && (
              <UserManagement 
                users={users} 
                onAddUser={handleAddUser} 
                onEditUser={handleEditUser}
                onUpdateStatus={handleUpdateStatus}
                onUpdateLicenseType={handleUpdateLicenseType}
                onUpdateExpiration={handleUpdateExpiration}
                onDeleteUser={handleDeleteUser}
              />
            )}
            {currentView === AppView.SESSIONS && <SessionMonitor sessions={sessions} users={users} onKillSession={(id) => setSessions(sessions.filter(s => s.id !== id))} onAddSession={(s) => setSessions([s, ...sessions])} />}
            {currentView === AppView.AI_INSIGHTS && <AiAssistant users={users} sessions={sessions} />}
            {currentView === AppView.INTEGRATION && <IntegrationGuide />}
        </div>
      </main>
    </div>
  );
};

export default App;

import { createClient } from '@vercel/kv';

export const config = {
  runtime: 'edge',
};

interface UserData {
  id: string;
  name: string;
  email: string;
  password?: string;
  company?: string;
  status: 'active' | 'expired' | 'blocked' | 'on_hold';
  licenseType: 'perpetual' | 'subscription' | 'trial';
  expirationDate: string;
  createdAt: string;
  machineIds: string[];
}

// QUAN TRỌNG: Mã này phải khớp với ADMIN_SECRET_KEY trong App.tsx
const DEFAULT_ADMIN_KEY = "DSH_SECRET_2024";
const MAX_MACHINES = 4; 

const getEnv = (key: string) => process.env[key] || '';

export default async function handler(req: Request) {
  const url = new URL(req.url);
  const headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, Authorization, x-admin-key',
  };

  if (req.method === 'OPTIONS') {
    return new Response(null, { status: 204, headers });
  }

  const kvUrl = getEnv('KV_REST_API_URL') || getEnv('REST_API_URL');
  const kvToken = getEnv('KV_REST_API_TOKEN') || getEnv('REST_API_TOKEN');

  // Ưu tiên lấy từ biến môi trường Vercel, nếu không có thì dùng mặc định
  const ADMIN_SECRET_KEY = getEnv('ADMIN_SECRET_KEY') || DEFAULT_ADMIN_KEY;

  if (!kvUrl || !kvToken) {
    return new Response(JSON.stringify({ 
      Success: false, 
      Message: "Hệ thống KV chưa được kết nối. Vui lòng kiểm tra Storage trên Vercel." 
    }), { status: 200, headers });
  }

  const kv = createClient({ url: kvUrl, token: kvToken });
  const LIST_KEY = 'pending_registrations';

  try {
    let action = url.searchParams.get('action') || 'get_all';
    let body: any = {};

    if (req.method === 'POST' || req.method === 'PUT') {
      try {
        const text = await req.text();
        if (text) {
          body = JSON.parse(text.trim());
          action = body.action || action;
        }
      } catch (e) {}
    }

    const getAllUsers = async (): Promise<UserData[]> => {
      const raw = await kv.lrange(LIST_KEY, 0, -1);
      if (!raw) return [];
      return raw.map((item: any) => {
        if (typeof item === 'string') {
          try { return JSON.parse(item); } catch { return null; }
        }
        return item;
      }).filter((item: any) => item !== null) as UserData[];
    };

    // 1. DÀNH CHO TOOL REVIT: verify_license không yêu cầu Admin Key
    if (action === 'verify_license') {
      const { email, machineId, password } = body;
      const allUsers = await getAllUsers();
      const userIndex = allUsers.findIndex((u) => u.email === email);
      const user = allUsers[userIndex];

      if (!user) return new Response(JSON.stringify({ Success: false, Message: "Tài khoản không tồn tại." }), { status: 200, headers });
      if (password && user.password && user.password !== password) return new Response(JSON.stringify({ Success: false, Message: "Sai mật khẩu." }), { status: 200, headers });

      const currentMachineIds = user.machineIds || [];
      if (machineId && !currentMachineIds.includes(machineId)) {
        if (currentMachineIds.length >= MAX_MACHINES) return new Response(JSON.stringify({ Success: false, Message: "Hết lượt đăng ký máy." }), { status: 200, headers });
        await kv.lset(LIST_KEY, userIndex, { ...user, machineIds: [...currentMachineIds, machineId] });
      }

      if (user.status !== 'active') return new Response(JSON.stringify({ Success: false, Message: "Tài khoản chưa được kích hoạt." }), { status: 200, headers });

      const isExpired = new Date(user.expirationDate) < new Date();
      if (isExpired && user.expirationDate !== '2099-12-31') return new Response(JSON.stringify({ Success: false, Message: "Hết hạn sử dụng." }), { status: 200, headers });

      return new Response(JSON.stringify({ Success: true, User: user }), { status: 200, headers });
    }

    // 2. KIỂM TRA QUYỀN ADMIN
    const authHeader = req.headers.get('Authorization')?.replace('Bearer ', '');
    const customHeader = req.headers.get('x-admin-key');
    const queryKey = url.searchParams.get('key');
    const providedKey = authHeader || customHeader || queryKey;

    if (providedKey !== ADMIN_SECRET_KEY) {
      return new Response(JSON.stringify({ 
        Success: false, 
        Message: "Lỗi: Admin Key không khớp.",
        Detail: "Mã bạn gửi lên không trùng với mã cấu hình trên Server. Vui lòng kiểm tra lại ADMIN_SECRET_KEY trong App.tsx và biến môi trường Vercel."
      }), { status: 401, headers });
    }

    // Xử lý các yêu cầu Admin
    if (action === 'get_all') {
      const data = await getAllUsers();
      return new Response(JSON.stringify(data), { status: 200, headers });
    }

    if (action === 'add_user') {
      const { user } = body;
      const newUser = { ...(user as UserData) };
      newUser.machineIds = newUser.machineIds || [];
      await kv.lpush(LIST_KEY, newUser);
      return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
    }

    if (action === 'update_user') {
      const { id, data: updateData } = body;
      const allUsers = await getAllUsers();
      const index = allUsers.findIndex((u) => u.id === id);
      if (index !== -1) {
        const finalUser = { ...allUsers[index], ...updateData };
        if (!updateData.password) finalUser.password = allUsers[index].password;
        await kv.lset(LIST_KEY, index, finalUser);
        return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
      }
    }

    if (action === 'delete_user') {
      const { id } = body;
      const allUsers = await getAllUsers();
      const userToDelete = allUsers.find((u) => u.id === id);
      if (userToDelete) {
        await kv.lrem(LIST_KEY, 0, userToDelete);
        return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
      }
    }

    return new Response(JSON.stringify({ Success: false, Message: "Yêu cầu không hợp lệ." }), { status: 400, headers });

  } catch (err: any) {
    return new Response(JSON.stringify({ Success: false, Message: err.message }), { status: 500, headers });
  }
}

import React, { useState, useEffect, useCallback } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { UserManagement } from './components/UserManagement';
import { SessionMonitor } from './components/SessionMonitor';
import { AiAssistant } from './components/AiAssistant';
import { IntegrationGuide } from './components/IntegrationGuide';
import { LoginScreen } from './components/LoginScreen';
import { AppView, User, Session } from './types';
import { MOCK_USERS, MOCK_SESSIONS } from './constants';
import { Menu, RefreshCw } from 'lucide-react';

// QUAN TRỌNG: Mã này phải khớp với DEFAULT_ADMIN_KEY trong api/register.ts
// Hoặc khớp với biến môi trường ADMIN_SECRET_KEY trên Vercel
const ADMIN_SECRET_KEY = "DSH_SECRET_2024";

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => {
    return localStorage.getItem('app_auth_token') === 'true';
  });

  const [currentView, setCurrentView] = useState<AppView>(() => {
    const saved = localStorage.getItem('app_current_view') as AppView;
    return Object.values(AppView).includes(saved) ? saved : AppView.DASHBOARD;
  });

  const [users, setUsers] = useState<User[]>(() => {
    const saved = localStorage.getItem('app_users_data');
    if (!saved || saved === '[]') return MOCK_USERS;
    try {
      return JSON.parse(saved);
    } catch { return MOCK_USERS; }
  });

  const [sessions, setSessions] = useState<Session[]>(() => {
    const saved = localStorage.getItem('app_sessions_data');
    if (!saved || saved === '[]') return MOCK_SESSIONS;
    try {
      return JSON.parse(saved);
    } catch { return MOCK_SESSIONS; }
  });

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'online' | 'offline' | 'error'>('online');

  useEffect(() => {
    localStorage.setItem('app_users_data', JSON.stringify(users));
  }, [users]);

  useEffect(() => {
    localStorage.setItem('app_sessions_data', JSON.stringify(sessions));
  }, [sessions]);

  const syncFromCloud = useCallback(async (silent = false) => {
    if (!silent) setIsSyncing(true);
    try {
      const response = await fetch(`/api/register?key=${ADMIN_SECRET_KEY}&action=get_all`, {
        method: 'GET',
        headers: { 
          'Authorization': `Bearer ${ADMIN_SECRET_KEY}`,
          'x-admin-key': ADMIN_SECRET_KEY,
          'Accept': 'application/json'
        }
      });

      const resultText = await response.text();

      if (!response.ok) {
        try {
           const errJson = JSON.parse(resultText);
           if (response.status === 401) {
             console.error("LỖI XÁC THỰC:", errJson.Detail);
             if (!silent) alert(errJson.Message + "\n" + errJson.Detail);
           }
        } catch(e) {}
        setSyncStatus('error');
        return;
      }

      if (resultText.trim()) {
        const result = JSON.parse(resultText);
        if (Array.isArray(result)) {
          setSyncStatus('online');
          setUsers(result);
        }
      }
    } catch (e) {
      setSyncStatus('offline');
    } finally {
      if (!silent) setIsSyncing(false);
    }
  }, []);

  useEffect(() => {
    if (isAuthenticated) {
      syncFromCloud(true);
      const interval = setInterval(() => syncFromCloud(true), 30000);
      return () => clearInterval(interval);
    }
  }, [isAuthenticated, syncFromCloud]);

  const apiCall = async (action: string, payload: any) => {
    try {
      const response = await fetch(`/api/register?key=${ADMIN_SECRET_KEY}`, {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${ADMIN_SECRET_KEY}`,
          'x-admin-key': ADMIN_SECRET_KEY
        },
        body: JSON.stringify({ action, ...payload })
      });

      const rawText = await response.text();
      const res = JSON.parse(rawText.trim());

      if (res && res.Success === false) {
        alert("Lỗi: " + res.Message + (res.Detail ? "\n" + res.Detail : ""));
      }
      return res;
    } catch (e) {
      return { Success: false, Message: "Không thể kết nối tới Server" };
    }
  };

  const handleAddUser = async (u: User) => {
    setUsers(prev => [u, ...prev]);
    const res = await apiCall('add_user', { user: u });
    if (res?.Success) syncFromCloud(true);
  };

  const handleEditUser = async (u: User) => {
    setUsers(prev => prev.map(x => x.id === u.id ? u : x));
    const res = await apiCall('update_user', { id: u.id, data: u });
    if (res?.Success) syncFromCloud(true);
  };

  const handleUpdateStatus = async (id: string, status: User['status']) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, status } : u));
    await apiCall('update_user', { id, data: { status } });
  };

  const handleUpdateLicenseType = async (id: string, licenseType: User['licenseType']) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, licenseType } : u));
    await apiCall('update_user', { id, data: { licenseType } });
  };

  const handleUpdateExpiration = async (id: string, expirationDate: string) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, expirationDate } : u));
    await apiCall('update_user', { id, data: { expirationDate } });
  };

  const handleDeleteUser = async (id: string) => {
    if (!window.confirm("Xác nhận xóa vĩnh viễn người dùng này?")) return;
    setUsers(prev => prev.filter(u => u.id !== id));
    await apiCall('delete_user', { id });
  };

  if (!isAuthenticated) return <LoginScreen onLogin={() => {
    setIsAuthenticated(true);
    localStorage.setItem('app_auth_token', 'true');
  }} />;

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans">
      <Sidebar 
        currentView={currentView} 
        setCurrentView={setCurrentView} 
        isMobileOpen={isMobileMenuOpen}
        onCloseMobile={() => setIsMobileMenuOpen(false)}
        onLogout={() => {
          setIsAuthenticated(false);
          localStorage.removeItem('app_auth_token');
        }}
      />

      <main className="flex-1 flex flex-col h-full overflow-hidden">
        <header className="px-8 py-4 bg-white border-b border-slate-200 flex justify-between items-center z-10 shadow-sm">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsMobileMenuOpen(true)} className="md:hidden text-slate-600 p-1 hover:bg-slate-100 rounded"><Menu /></button>
             <div>
                <h1 className="text-xl font-bold text-slate-800 uppercase tracking-tight">
                  {currentView}
                </h1>
                <p className="text-[10px] font-bold uppercase tracking-widest flex items-center gap-1.5">
                  <span className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'online' ? 'bg-green-500' : syncStatus === 'error' ? 'bg-red-500' : 'bg-amber-500'}`}></span>
                  Hệ thống: <span className={syncStatus === 'online' ? 'text-green-500' : syncStatus === 'error' ? 'text-red-500' : 'text-amber-500'}>
                    {syncStatus === 'online' ? 'TRỰC TUYẾN' : syncStatus === 'error' ? 'LỖI KẾT NỐI' : 'NGOẠI TUYẾN'}
                  </span>
                </p>
             </div>
          </div>
          <button 
              onClick={() => syncFromCloud(false)} 
              disabled={isSyncing}
              className="p-2 hover:bg-slate-100 rounded-full transition-all disabled:opacity-50 active:scale-90 flex items-center gap-2"
          >
              <RefreshCw className={`w-5 h-5 text-slate-400 ${isSyncing ? 'animate-spin text-blue-500' : ''}`} />
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-8">
            {currentView === AppView.DASHBOARD && <Dashboard users={users} sessions={sessions} onUpdateStatus={handleUpdateStatus} onUpdateLicenseType={handleUpdateLicenseType} />}
            {currentView === AppView.USERS && (
              <UserManagement 
                users={users} 
                onAddUser={handleAddUser} 
                onEditUser={handleEditUser}
                onUpdateStatus={handleUpdateStatus}
                onUpdateLicenseType={handleUpdateLicenseType}
                onUpdateExpiration={handleUpdateExpiration}
                onDeleteUser={handleDeleteUser}
              />
            )}
            {currentView === AppView.SESSIONS && <SessionMonitor sessions={sessions} users={users} onKillSession={(id) => setSessions(sessions.filter(s => s.id !== id))} onAddSession={(s) => setSessions([s, ...sessions])} />}
            {currentView === AppView.AI_INSIGHTS && <AiAssistant users={users} sessions={sessions} />}
            {currentView === AppView.INTEGRATION && <IntegrationGuide />}
        </div>
      </main>
    </div>
  );
};

export default App;

import { createClient } from '@vercel/kv';

export const config = {
  runtime: 'edge',
};

interface UserData {
  id: string;
  name: string;
  email: string;
  password?: string;
  company?: string;
  status: 'active' | 'expired' | 'blocked' | 'on_hold';
  licenseType: 'perpetual' | 'subscription' | 'trial';
  expirationDate: string;
  createdAt: string;
  machineIds: string[];
}

const DEFAULT_ADMIN_KEY = "DSH_SECRET_2024";
const MAX_MACHINES = 4; 

const getEnv = (key: string) => process.env[key] || '';

export default async function handler(req: Request) {
  const url = new URL(req.url);
  const headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, Authorization, x-admin-key',
  };

  if (req.method === 'OPTIONS') {
    return new Response(null, { status: 204, headers });
  }

  const kvUrl = getEnv('KV_REST_API_URL') || getEnv('REST_API_URL');
  const kvToken = getEnv('KV_REST_API_TOKEN') || getEnv('REST_API_TOKEN');
  const ADMIN_SECRET_KEY = getEnv('ADMIN_SECRET_KEY') || DEFAULT_ADMIN_KEY;

  if (!kvUrl || !kvToken) {
    return new Response(JSON.stringify({ Success: false, Message: "KV Storage chưa cấu hình." }), { status: 200, headers });
  }

  const kv = createClient({ url: kvUrl, token: kvToken });
  const LIST_KEY = 'pending_registrations';

  try {
    let body: any = {};
    let action = url.searchParams.get('action') || '';

    if (req.method === 'POST' || req.method === 'PUT') {
      try {
        const text = await req.text();
        if (text) {
          body = JSON.parse(text);
          action = body.action || action;
        }
      } catch (e) {}
    }

    // Tự động nhận diện action cho Tool nếu thiếu
    if (!action && body.email && body.password) {
      action = 'verify_license';
    }

    const getAllUsers = async (): Promise<UserData[]> => {
      const raw = await kv.lrange(LIST_KEY, 0, -1);
      if (!raw) return [];
      return raw.map((item: any) => (typeof item === 'string' ? JSON.parse(item) : item)).filter(Boolean);
    };

    // --- CHỨC NĂNG CHO REIVT TOOL (Không cần Admin Key) ---

    // 1. Đăng ký tài khoản mới (Từ Tool)
    if (action === 'register') {
      const { email, password, fullName, company, machineId } = body;
      const allUsers = await getAllUsers();

      if (allUsers.some(u => u.email === email)) {
        return new Response(JSON.stringify({ Success: false, Message: "Email này đã được sử dụng." }), { status: 200, headers });
      }

      const newUser: UserData = {
        id: `U${Date.now()}`,
        name: fullName || "Người dùng mới",
        email: email,
        password: password,
        company: company || "Cá nhân",
        status: 'on_hold',
        licenseType: 'trial',
        expirationDate: new Date(Date.now() + 7 * 86400000).toISOString().split('T')[0], // Mặc định 7 ngày trial
        createdAt: new Date().toISOString().split('T')[0],
        machineIds: machineId ? [machineId] : []
      };

      await kv.lpush(LIST_KEY, newUser);
      return new Response(JSON.stringify({ Success: true, Message: "Đăng ký thành công! Vui lòng chờ Admin kích hoạt." }), { status: 200, headers });
    }

    // 2. Kiểm tra bản quyền / Đăng nhập (Từ Tool)
    if (action === 'verify_license') {
      const { email, password, machineId } = body;
      const allUsers = await getAllUsers();
      const userIndex = allUsers.findIndex(u => u.email === email);
      const user = allUsers[userIndex];

      if (!user) return new Response(JSON.stringify({ Success: false, Message: "Tài khoản không tồn tại." }), { status: 200, headers });
      if (password && user.password !== password) return new Response(JSON.stringify({ Success: false, Message: "Sai mật khẩu." }), { status: 200, headers });

      // Cập nhật HWID nếu máy mới
      if (machineId && !user.machineIds.includes(machineId)) {
        if (user.machineIds.length >= MAX_MACHINES) {
          return new Response(JSON.stringify({ Success: false, Message: `Đã đạt giới hạn ${MAX_MACHINES} máy.` }), { status: 200, headers });
        }
        user.machineIds.push(machineId);
        await kv.lset(LIST_KEY, userIndex, user);
      }

      if (user.status !== 'active') {
        const msg = user.status === 'on_hold' ? "Tài khoản đang chờ duyệt." : "Tài khoản đã bị khóa.";
        return new Response(JSON.stringify({ Success: false, Message: msg }), { status: 200, headers });
      }

      const isExpired = new Date(user.expirationDate) < new Date() && user.expirationDate !== '2099-12-31';
      if (isExpired) return new Response(JSON.stringify({ Success: false, Message: "Bản quyền đã hết hạn." }), { status: 200, headers });

      return new Response(JSON.stringify({ Success: true, User: user }), { status: 200, headers });
    }

    // --- CHỨC NĂNG CHO ADMIN PANEL (Yêu cầu Admin Key) ---
    const providedKey = req.headers.get('Authorization')?.replace('Bearer ', '') || 
                        req.headers.get('x-admin-key') || 
                        url.searchParams.get('key');

    if (providedKey !== ADMIN_SECRET_KEY) {
      return new Response(JSON.stringify({ Success: false, Message: "Từ chối truy cập (Admin Key sai)." }), { status: 401, headers });
    }

    if (action === 'get_all' || action === '') {
      const data = await getAllUsers();
      return new Response(JSON.stringify(data), { status: 200, headers });
    }

    if (action === 'add_user') {
      await kv.lpush(LIST_KEY, body.user);
      return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
    }

    if (action === 'update_user') {
      const allUsers = await getAllUsers();
      const idx = allUsers.findIndex(u => u.id === body.id);
      if (idx !== -1) {
        const updated = { ...allUsers[idx], ...body.data };
        if (!body.data.password) updated.password = allUsers[idx].password;
        await kv.lset(LIST_KEY, idx, updated);
        return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
      }
    }

    if (action === 'delete_user') {
      const allUsers = await getAllUsers();
      const user = allUsers.find(u => u.id === body.id);
      if (user) {
        await kv.lrem(LIST_KEY, 0, user);
        return new Response(JSON.stringify({ Success: true }), { status: 200, headers });
      }
    }

    return new Response(JSON.stringify({ Success: false, Message: "Yêu cầu không hợp lệ." }), { status: 400, headers });

  } catch (err: any) {
    return new Response(JSON.stringify({ Success: false, Message: err.message }), { status: 500, headers });
  }
}

